Config.SkillData1.data_get_skill_cache = {}

function Config.SkillData1.data_get_skill(slot0)
	if Config.SkillData1.data_get_skill_cache[slot0] == nil then
		if not Config.SkillData1.data_get_skill_table[slot0] then
			return
		end

		if not loadstring(string.format("return %s", slot1))() then
			return
		end

		Config.SkillData1.data_get_skill_cache[slot0] = {
			bid = slot1[1],
			name = slot1[2],
			owner = slot1[3],
			group = slot1[4],
			next_id = slot1[5],
			level = slot1[6],
			is_normal_skill = slot1[7],
			cd = slot1[8],
			type = slot1[9],
			fit_combat_type = slot1[10],
			best_target = slot1[11],
			target = slot1[12],
			count = slot1[13],
			effect_list = slot1[14],
			add_attr = slot1[15],
			hallows_atk = slot1[16],
			des = slot1[17],
			open_desc = slot1[18],
			skill_desc = slot1[19],
			icon = slot1[20],
			is_play_sound = slot1[21],
			skill_type = slot1[22],
			passive_skill_show = slot1[23],
			buff_des = slot1[24],
			power = slot1[25],
			target_multi = slot1[26],
			fire_cd = slot1[27],
			client_lev = slot1[28]
		}
	end

	return Config.SkillData1.data_get_skill_cache[slot0]
end

