	[513402.0] = "{513402, \"心网\", \"艾尼路\", 51340, 513403, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5134002,5134012}, {}, 0, \"每回合开始时，若自身生命值不低于30%，则给自身附加暴击率提升15%的效果，持续1回合；若低于30%，则给提升自身20%攻击力，持续1回合\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"20231\", 0, 1, 1, {{11302,10162}}, 0, 0, 0, 0}",
	[763505.0] = "{763505, \"[觉醒]灵魂之王\", \"布鲁克(新世界)\", 74450, 0, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7635005}, {}, 0, \"战斗开始时，给全体队友增加【灵魂之王】，增加35%速度，增加35%攻击，增加30%暴击几率\", \"激活条件：忍者到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：忍者到达<div fontcolor=45a536>6星</div>自动升级\", \"705014\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[531401.0] = "{531401, \"诡诈占卜\", \"霍金斯\", 53140, 531402, 1, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5314001}, {}, 0, \"霍金斯在战斗开始时进行命运抽卡，40%使敌方随机单位死亡，60%概率使自己死亡\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"23714\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[777102.0] = "{777102, \"橡胶·火拳铳\", \"路飞(和之国)\", 77710, 777103, 2, 0, 2, \"active_skill\", 0, 0, 1, 1, {7771002,7771012,7770111}, {}, 0, \"路飞对敌方全体英雄发起攻击，对敌方全体造成198%物理伤害附加自身攻击力60%，对灼烧状态下的单位额外增加40%的伤害，且必定暴击\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>7星</div>自动升级\", \"777101\", 0, 1, 1, {{76011}}, 0, 0, 1, 0}",
	[757015.0] = "{757015, \"普通攻击\", \"罗杰\", 75705, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {7570015}, {}, 0, \"对前方1个目标造成100%的物理伤害\", \"\", \"\", \"20000\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[782403.0] = "{782403, \"草帽航海士\", \"娜美(宙斯)\", 78240, 782404, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7824003,7824013}, {}, 0, \"回合开始为自身提供免疫控制，持续1回合，为友方全体单位提供以下随机一种效果；1、增加30%暴击率，持续1回合，2、增加30%攻击力，持续1回合，3、增加30%免伤，持续1回合，4、增加30%速度，持续1回合\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"782401\", 0, 0, 1, {{27103,26103}}, 0, 0, 0, 0}",
	[522101.0] = "{522101, \"女王鼓舞\", \"汉库克\", 52210, 522102, 1, 0, 4, \"active_skill\", 0, \"max_atk\", 2, 1, {5221001,5221021}, {}, 0, \"提升我方攻击最高的3个单位10%防御2回合，且对攻击力最高的1个单位施加一个持续2回合的【庇护】\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"22993\", 0, 1, 1, {{10601,16601}}, 0, 0, 1, 0}",
	[513405.0] = "{513405, \"[觉醒]心网\", \"艾尼路\", 51340, 0, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5134003,5134013}, {}, 0, \"每回合开始时，若自身生命值不低于30%，则给自身附加暴击率提升20%的效果，持续1回合；若低于30%，则给提升自身30%攻击力，持续1回合\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"20231\", 0, 1, 1, {{11303,10163}}, 0, 0, 0, 0}",
	[522105.0] = "{522105, \"[觉醒]女王鼓舞\", \"汉库克\", 52210, 0, 5, 0, 4, \"active_skill\", 0, \"max_atk\", 2, 1, {5221003,5221013,5221021}, {}, 0, \"提升我方攻击最高的4个单位20%防御2回合，若该单位为强者英雄则额外提升其10%伤害2回合（该效果不可被驱散），且对攻击力最高的1个单位施加一个持续2回合的【庇护】\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"22993\", 0, 1, 1, {{10603,11822,16601}}, 0, 0, 1, 0}",
	[782404.0] = "{782404, \"草帽航海士\", \"娜美(宙斯)\", 78240, 782405, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7824004,7824014}, {}, 0, \"回合开始为自身提供免疫控制，持续1回合，为友方全体单位提供以下随机一种效果；1、增加40%暴击率，持续1回合，2、增加40%攻击力，持续1回合，3、增加40%免伤，持续1回合，4、增加40%速度，持续1回合\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"782401\", 0, 0, 1, {{27104,26104}}, 0, 0, 0, 0}",
	[545303.0] = "{545303, \"穿刺波动\", \"罗(和之国)\", 54530, 545304, 3, 0, 4, \"active_skill\", 0, 0, 1, 1, {5453003}, {}, 0, \"手术果实觉醒后的终极招式，通过波动直接伤害敌方全体，此技能无视50%防御，对敌方全体造成162%的法术伤害，同时目标身上每有一个负面效果，额外造成目标最大生命值2%的伤害（最大不超过罗攻击力5倍）\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>15星</div>自动升级\", \"54530\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[549301.0] = "{549301, \"腐骨毒雾\", \"蕾玖\", 54930, 549302, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {5493001,5493101,5493201}, {}, 0, \"蕾玖在己方阵地喷吐出腐骨毒雾，会使3名友方单位失去最大生命20%的当前生命值（此效果可致死），同时驱除目标2个负面状态，且附加【再生毒素】，持续4回合\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"54930\", 0, 1, 1, {{54931}}, 0, 0, 2, 0}",
	[516311.0] = "{516311, \"冥灭巨镰\", \"白胡子\", 51631, 516312, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {5163001,5163011,5164002}, {}, 0, \"白胡子对敌方后排单体发出2段共【222%+目标损失血量百分比*100%】的物理伤害\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"22583\", 0, 1, 1, {}, 0, 0, 2, 0}",
