	[523203.0] = "{523203, \"鱼人热血\", \"甚平\", 52320, 523204, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5232003}, {{'hp_max_per',400},{'def_per',200},{'res',100}}, 0, \"生命提升40%，防御提升20%，免伤提升10%；自身生命值每降低3%，免伤提高1%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"23312\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[523301.0] = "{523301, \"武赖贯\", \"甚平\", 52330, 523302, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {5233001,5233011}, {}, 0, \"对敌方前中排单位造成自身14%生命值上限的真实伤害（无视免伤和防御），并有40%概率对其附加2回合的【出血】状态，该技能不会触发暴击且不受伤害加成影响\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"23311\", 0, 0, 1, {{21011}}, 0, 0, 2, 0}",
	[552001.0] = "{552001, \"普通攻击\", \"凯多(神龙)\", 55200, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {5520001}, {}, 0, \"对前方单体造成100%物理伤害\", \"\", \"\", \"20000\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[516312.0] = "{516312, \"冥灭巨镰\", \"白胡子\", 51631, 516313, 2, 0, 4, \"active_skill\", 0, 0, 1, 1, {5163002,5163012,5164002}, {}, 0, \"白胡子对敌方后排单体发出2段共【268%+目标损失血量百分比*120%】的物理伤害；若在第二段斩击时单位生命值低于20%，则直接击杀目标（该伤害值无视护盾、防御、伤害分摊，伤害为该单位生命值的20%）\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>9星</div>自动升级\", \"22583\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[523305.0] = "{523305, \"[觉醒]武赖贯\", \"甚平\", 52330, 0, 5, 0, 4, \"active_skill\", 0, 0, 1, 1, {5233003,5233013,5233023}, {}, 0, \"对敌方前中排单位造成自身20%生命值上限的真实伤害（无视免伤和防御），并有70%概率对其附加2回合的【出血】状态，且对前方1个单位附加一个持续1回合的【环身水流】状态，该技能不会触发暴击且不受伤害加成影响\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"23311\", 0, 0, 1, {{21011,29302}}, 0, 0, 2, 0}",
	[523404.0] = "{523404, \"援护\", \"甚平\", 52340, 523405, 4, 0, 0, \"passive_skill\", 0, 0, 7, 1, {5234003}, {}, 0, \"每回合开始时，选择我方的优先后排生命值最低的2个英雄，若其生命值低于50%，则对其附加一个【绝对援护】效果，并提升其20%免伤，均持续1回合\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"23314\", 0, 0, 1, {{12852,10809}}, 0, 0, 0, 0}",
	[523405.0] = "{523405, \"[觉醒]援护\", \"甚平\", 52340, 0, 5, 0, 0, \"passive_skill\", 0, 0, 7, 1, {5234003}, {}, 0, \"每回合开始时，选择我方的优先后排生命值最低的2个英雄，若其生命值低于50%，则对其附加一个【绝对援护】效果，并提升其20%免伤，均持续1回合\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"23314\", 0, 0, 1, {{12852,10809}}, 0, 0, 0, 0}",
	[781102.0] = "{781102, \"熊之冲击\", \"熊(机械)\", 78110, 781103, 2, 0, 2, \"active_skill\", 0, 0, 1, 1, {7811002}, {}, 0, \"攻击敌方全体，造成240%法术伤害，附加自身攻击力的60%，自身生命值的15%真实伤害，(该伤害最大不超过自身攻击力的9倍)，50%概率附加【破甲】，持续2回合；\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"781101\", 0, 1, 1, {{22101}}, 0, 0, 1, 0}",
	[240301.0] = "{240301, \"模仿伪装\", \"冯克雷\", 24030, 240302, 1, 0, 4, \"active_skill\", 0, 0, 5, 1, {2403001}, {}, 0, \"提升自身15%免伤，持续3回合\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"24040\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[542305.0] = "{542305, \"[觉醒]刮盘·爆\", \"阿普\", 54230, 0, 5, 0, 4, \"active_skill\", 0, 0, 1, 1, {5423003,5423993}, {}, 0, \"阿普在敌方阵地炸开音波，对敌方全体造成91%的法术伤害，目标身上每存在一种负面效果，则额外增加6%的伤害，以及5%概率使目标陷入【音波共震】（每种负面状态单独计算概率）。对己方全体100%概率施加【音波协调】。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"54230\", 0, 1, 1, {{54231,54232}}, 0, 0, 0, 0}",
	[535201.0] = "{535201, \"海军导师\", \"泽法\", 53520, 535202, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5352001}, {{'hp_max_per',150},{'atk_per',100}}, 0, \"生命提升15%，攻击提升10%。战斗开始时，友方全体海军提升2%的攻击力，此效果不可驱散，持续到战斗结束。\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"53520\", 0, 1, 1, {{53521}}, 0, 0, 0, 0}",
	[516313.0] = "{516313, \"冥灭巨镰\", \"白胡子\", 51631, 516314, 3, 0, 4, \"active_skill\", 0, 0, 1, 1, {5163003,5163013,5164002}, {}, 0, \"白胡子对敌方后排单体发出2段共【320%+目标损失血量百分比*146%】的物理伤害；若在第二段斩击时单位生命值低于30%，则直接击杀目标（该伤害值无视护盾、防御、伤害分摊，伤害为该单位生命值的30%）\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"22583\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[524204.0] = "{524204, \"凤凰印\", \"马尔科\", 52420, 524205, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {}, {{'atk_per',400},{'hp_max_per',200},{'speed',15}}, 0, \"攻击提升40%，生命提升20%，速度提升15\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"23402\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[218207.0] = "{218207, \"水流护体\", \"海贼6号\", 21820, 218208, 7, 0, 0, \"passive_skill\", 0, 0, 5, 1, {2182007}, {}, 0, \"被动技能：受到攻击时根据自身生命值上限的5.4%对攻击者造成伤害\", \"开启条件测试\", \"\", \"21820\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[524401.0] = "{524401, \"再生之炎\", \"马尔科\", 52440, 524402, 1, 0, 1, \"passive_skill\", 0, 0, 2, 1, {5244001}, {}, 0, \"自身行动后，为随机3个己方单位驱散1层非控制类的负面状态\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"23404\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[524402.0] = "{524402, \"再生之炎\", \"马尔科\", 52440, 524403, 2, 0, 1, \"passive_skill\", 0, 0, 2, 1, {5244002}, {}, 0, \"自身行动后，为随机4个己方单位驱散1层非控制类的负面状态\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"23404\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[757305.0] = "{757305, \"[觉醒]神避\", \"罗杰\", 75730, 0, 5, 0, 4, \"active_skill\", 0, 0, 1, 1, {7573005,7573015,7573021}, {}, 0, \"罗杰发动终极招式【神避】，对敌方全体单位造成罗杰攻击力400%+生命值上限的40%伤害（该伤害无视防御，不受免伤效果影响），对【霸王色·破甲】状态下的敌人增伤50%,并且每次受到的伤害不可超过自身生命值上限的60%\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"75730\", 0, 1, 1, {{75711,75712}}, 0, 0, 2, 0}",
	[525001.0] = "{525001, \"普通攻击\", \"赤犬\", 52500, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {5250001}, {}, 0, \"对前方单体造成100%物理伤害\", \"\", \"\", \"20000\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[506403.0] = "{506403, \"鹰波\", \"索隆(伟大航路)\", 50640, 0, 3, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5064003}, {}, 0, \"对处于【出血】或【大出血】状态的单位伤害提升20%，【普通攻击】优先攻击处于【出血】或【大出血】状态的单位\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"32194\", 0, 1, 1, {{21010}}, 0, 0, 0, 0}",
	[516314.0] = "{516314, \"冥灭巨镰\", \"白胡子\", 51631, 516315, 4, 0, 4, \"active_skill\", 0, 0, 1, 1, {5163003,5163013,5164002}, {}, 0, \"白胡子对敌方后排单体发出2段共【320%+目标损失血量百分比*146%】的物理伤害；若在第二段斩击时单位生命值低于30%，则直接击杀目标（该伤害值无视护盾、防御、伤害分摊，伤害为该单位生命值的30%）\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"22583\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[549104.0] = "{549104, \"粉色毒雾\", \"蕾玖\", 54910, 549105, 4, 0, 4, \"active_skill\", 0, 0, 1, 1, {5491003}, {}, 0, \"蕾玖对敌方释放出大量具有强烈毒性的毒雾，对敌方全体造成145%的法术伤害，并有55%概率为目标附加1层【粉红毒素】\", \"初始激活\", \"\", \"54910\", 0, 1, 1, {{54911}}, 0, 0, 1, 0}",
	[549403.0] = "{549403, \"血统因子\", \"蕾玖\", 54940, 549404, 3, 0, 0, \"passive_skill\", 0, 0, 1, 1, {}, {}, 0, \"蕾玖因“血统因子”的改造基因而获得了超人般的身体，拥有特殊的抗毒体质，其普通攻击改为对敌方单体造成144%法术伤害，为目标附加2层【粉红毒素】，并随机为一个友方单体附加【治疗毒素】持续2回合\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"54940\", 0, 1, 1, {{54931}}, 0, 0, 0, 0}",
	[755404.0] = "{755404, \"饼干骑士\", \"克力架\", 75540, 755405, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7554004,7554014,7554024,7554034,7554044}, {}, 0, \"克力架对友方单位进行援护，抵挡50%的伤害，自己再承受被抵挡伤害的20%，克力架生命值低于50%为自身增加【饼干反刺】【饼干骑士】【免疫控制】\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"75540\", 0, 0, 1, {{75524,75544,19803}}, 0, 0, 0, 0}",
	[783601.0] = "{783601, \"黑足受击\", \"山治(鬼岛)\", 78360, 783602, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7836001}, {}, 0, \"受到伤害时时，自身获得1层【黑足】，持续4回合。\", \"激活条件：忍者到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：忍者到达<div fontcolor=45a536>6星</div>自动升级\", \"783401\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[240302.0] = "{240302, \"模仿伪装\", \"冯克雷\", 24030, 240303, 2, 0, 4, \"active_skill\", 0, 0, 5, 1, {2403002}, {}, 0, \"提升自身20%免伤和10%抗控，持续3回合\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>9星</div>自动升级\", \"24040\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[757304.0] = "{757304, \"神避\", \"罗杰\", 75730, 757305, 4, 0, 4, \"active_skill\", 0, 0, 1, 1, {7573004,7573014,7573021}, {}, 0, \"罗杰发动终极招式【神避】，对敌方全体单位造成罗杰攻击力250%+生命值上限的25%伤害（该伤害无视防御，不受免伤效果影响），对【霸王色·破甲】状态下的敌人增伤50%,并且每次受到的伤害不可超过自身生命值上限的80%\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"75730\", 0, 1, 1, {{75711,75712}}, 0, 0, 2, 0}",
	[539402.0] = "{539402, \"御田二刀流\", \"光月御田\", 53940, 539403, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5394001}, {}, 0, \"己方造成暴击时，45%概率使御田获得一层【阎魔】。己方受到伤害时，33%概率使御田获得一层【天羽羽斩】。在使用【桃源白泷】时，每层【天羽羽斩】提高20%的物理伤害和21%的吸血效果。御田在使用【桃源十拳】时会消耗所有【阎魔】层数和【天羽羽斩】层数，每层【阎魔】提高附带消耗生命值*0.25的物理伤害和无视10%的防御，每层【天羽羽斩】会为自身回复2%的最大生命值。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"53940\", 0, 1, 1, {{53951,53961}}, 0, 0, 0, 0}",
