	[529403.0] = "{529403, \"盲人赌徒\", \"藤虎\", 52940, 529404, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5294003}, {}, 0, \"藤虎是狂热的赌徒，他将敌我命运都赌在了这一把上！每个回合开始时，有70%的概率使自身伤害提高150%，30%的概率使自身伤害降低20%\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"27504\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[274101.0] = "{274101, \"大舞刀\", \"海贼10号\", 27410, 0, 1, 0, 4, \"active_skill\", 0, 0, 2, 1, {2741001}, {}, 0, \"为己方随机单体提升25%攻击力和20%暴击伤害，持续2回合\", \"初始激活\", \"\", \"15020\", 0, 1, 1, {}, 0, 0, 1, 0}",
	[783605.0] = "{783605, \"[魂]黑足受击\", \"山治(鬼岛)\", 78360, 0, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7836005}, {}, 0, \"受到伤害时时，自身获得1层【黑足】，持续4回合。\", \"激活条件：忍者到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：10星忍者<div fontcolor=45a536>技能突破</div>升级\", \"783401\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[516305.0] = "{516305, \"[觉醒]空裂\", \"白胡子\", 51630, 0, 5, 0, 4, \"active_skill\", 0, 0, 1, 1, {5163003,5163013}, {}, 0, \"白胡子对敌方后排单体发出2段共【320%+目标损失血量百分比*146%】的物理伤害；若在第二段斩击时单位生命值低于30%，则直接击杀目标（斩杀的伤害值无视护盾、防御、伤害分摊，伤害为该单位生命值的30%，不超过自身攻击力的4倍）\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"22583\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[529402.0] = "{529402, \"盲人赌徒\", \"藤虎\", 52940, 529403, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5294002}, {}, 0, \"藤虎是狂热的赌徒，他将敌我命运都赌在了这一把上！每个回合开始时，有60%的概率使自身伤害提高120%，40%的概率使自身伤害降低20%\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"27504\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[526901.0] = "{526901, \"普通攻击\", \"萨博（路西）\", 52690, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {5269001}, {}, 0, \"对前方单体造成100%物理伤害\", \"\", \"\", \"20000\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[527103.0] = "{527103, \"黑洞\", \"黑胡子\", 52710, 0, 3, 0, 2, \"active_skill\", 0, 0, 1, 1, {5271003,5271013}, {}, 0, \"制造一片黑暗领域，对前方一列单位造成162%魔法伤害，且额外有70%概率对随机一个单位附加【黑暗缠绕】和【破甲】，均持续2回合，若该单位速度比自身低，则附加概率提升为100%\", \"初始激活\", \"\", \"23801\", 0, 0, 1, {{29503,22104}}, 0, 0, 1, 0}",
	[536105.0] = "{536105, \"[觉醒]灵魂咒文\", \"BIG·MOM\", 53610, 0, 5, 0, 4, \"active_skill\", 0, 0, 1, 1, {5361203,5361204,5361205,5361206}, {}, 0, \"BIG·MOM站在战场中间对随机一个敌方单体进行问话，使当前目标受到BIG·MOM攻击力337%的法术伤害和【灵魂创伤】效果，若目标的攻击力低于BIG·MOM，则额外附加【灵魂剥夺】，转移目标最大生命值20%到BIG·MOM身上，且BIG·MOM获得一层【摄魂印记】和【灵魂擭取】。\", \"初始激活\", \"\", \"53610\", 0, 0, 1, {{53611,53635,53636,53637}}, 0, 0, 1, 0}",
	[529401.0] = "{529401, \"盲人赌徒\", \"藤虎\", 52940, 529402, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5294001}, {}, 0, \"藤虎是狂热的赌徒，他将敌我命运都赌在了这一把上！每个回合开始时，有50%的概率使自身伤害提高100%，50%的概率使自身伤害降低20%\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"27504\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[761051.0] = "{761051, \"普通攻击\", \"佩罗娜\", 76105, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {7610001,7614005,7614015}, {}, 0, \"对前方单体造成100%魔法伤害\", \"\", \"\", \"20000\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[755303.0] = "{755303, \"饼干防御\", \"克力架\", 75530, 755304, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7553003,7553013}, {}, 0, \"克力架受到伤害时召唤饼干战士对敌方生命值最低单位进行一次攻击，造成250%+防御*0.3的物理伤害，克力架被攻击时为自身增加【饼干护甲】。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>15星</div>自动升级\", \"75530\", 0, 1, 1, {{75533}}, 0, 0, 2, 0}",
	[218201.0] = "{218201, \"水流护体\", \"海贼6号\", 21820, 218202, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {2182001}, {}, 0, \"被动技能：受到攻击时根据自身生命值上限的3%对攻击者造成伤害\", \"开启条件测试\", \"\", \"21820\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[536102.0] = "{536102, \"灵魂咒文\", \"BIG·MOM\", 53610, 536103, 2, 0, 4, \"active_skill\", 0, 0, 1, 1, {5361103,5361104,5361105,5361106}, {}, 0, \"BIG·MOM站在战场中间对随机一个敌方单体进行问话，使当前目标受到BIG·MOM攻击力229%的法术伤害和【灵魂创伤】效果，若目标的攻击力低于BIG·MOM，则额外附加【灵魂剥夺】，转移目标最大生命值15%到BIG·MOM身上，且BIG·MOM获得一层【摄魂印记】和【灵魂擭取】。\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>7星</div>自动升级\", \"53610\", 0, 0, 1, {{53611,53625,53626,53627}}, 0, 0, 1, 0}",
	[528105.0] = "{528105, \"[觉醒]万紫千红·花园\", \"罗宾\", 52810, 0, 5, 0, 2, \"active_skill\", 0, \"min_hp_per\", 2, 1, {5281003,5281023,5281013}, {}, 0, \"回复己方生命值最低的3个单位罗宾攻击力108%的生命值，并提升其20%暴击伤害1回合，额外为其中2个单位附加持续1回合的【万紫千红·花园】\", \"初始激活\", \"\", \"23901\", 0, 0, 1, {{16903,10505}}, 0, 0, 1, 0}",
	[204301.0] = "{204301, \"岚脚·十破\", \"加布拉\", 20430, 0, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {2043001,2043101,2043201,2043301,2043401,2043501}, {}, 0, \"连续攻击前方单体5次，每次造成64%物理伤害，使用后停止行动1回合\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"20410\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[773202.0] = "{773202, \"阿修罗\", \"索隆(鬼岛)\", 77320, 773203, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7732002}, {{'hp_max_per',350},{'atk_per',200},{'speed',20},{'crit_rate',100}}, 0, \"生命值提升35%，攻击力升20%，速度提升20，暴击率提升10%，索隆死亡后立马以30%的生命值复活(每场战斗仅触发一次)\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>8星</div>自动升级\", \"773201\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[536103.0] = "{536103, \"灵魂咒文\", \"BIG·MOM\", 53610, 536104, 3, 0, 4, \"active_skill\", 0, 0, 1, 1, {5361203,5361204,5361205,5361206}, {}, 0, \"BIG·MOM站在战场中间对随机一个敌方单体进行问话，使当前目标受到BIG·MOM攻击力337%的法术伤害和【灵魂创伤】效果，若目标的攻击力低于BIG·MOM，则额外附加【灵魂剥夺】，转移目标最大生命值20%到BIG·MOM身上，且BIG·MOM获得一层【摄魂印记】和【灵魂擭取】。\", \"初始激活\", \"\", \"53610\", 0, 0, 1, {{53611,53635,53636,53637}}, 0, 0, 1, 0}",
	[503901.0] = "{503901, \"假战斗普攻\", \"龙马\", 50390, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {5039001}, {}, 0, \"对前方单体造成100%物理伤害\", \"\", \"\", \"20000\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[528301.0] = "{528301, \"万紫千红·三轮华\", \"罗宾\", 52830, 528302, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {5283001,5283011}, {}, 0, \"对敌方随机4个单位造成82%魔法伤害，对随机2个单位50%概率附加【出血】，持续2回合\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"23903\", 0, 0, 1, {{21001}}, 0, 0, 2, 0}",
	[518301.0] = "{518301, \"移植\", \"罗\", 51830, 518302, 1, 0, 4, \"active_skill\", 0, 0, 2, 1, {5183001,5183011}, {}, 0, \"罗使用手术果实能力，使友方全体回复罗90%攻击力的生命，溢出的治疗量将转化为等量的【治疗盾】，持续2回合\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"22953\", 0, 1, 1, {{16301}}, 0, 2, 0, 0}",
	[542402.0] = "{542402, \"战斗音乐\", \"阿普\", 54240, 542403, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5424101,5424102,5424103,5424001,5424002,5424003}, {}, 0, \"回合结束时阿普会弹奏战斗音乐，39%概率使友方全体身上携带的增益效果延长2回合，33%概率使敌方全体身上携带的负面和控制效果延长2回合。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"54240\", 0, 1, 1, {}, 0, 0, 0, 0}",
