	[553501.0] = "{553501, \"最强正义\", \"佛之战国\", 55350, 553112, 1, 0, 0, \"active_skill\", 0, 0, 1, 1, {5531101,5531111,5531121}, {}, 0, \"使出最强正义，对敌方全体目标造成188%法术伤害，并附加【防御降低】效果，同时全体队友附加【正义】效果，如果队友已携带【正义】效果，将附加【无敌】效果\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"22810\", 0, 1, 1, {{59020,59000,31060}}, 0, 0, 1, 0}",
