	[537901.0] = "{537901, \"跑打动作\", \"白星\", 53790, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {5370001}, {}, 0, \"对前方单体造成100%物理伤害\", \"\", \"\", \"20000\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[556202.0] = "{556202, \"武装色霸气\", \"山治(外骨骼)\", 55620, 556203, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5562002}, {{'hp_max_per',300},{'def_per',150},{'res_s',200}}, 0, \"防御提升15%，生命值提升30%，物理免伤提升20%；山治(外骨骼)每降低10%生命值，提高10%防御\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>8星</div>自动升级\", \"55620\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[551305.0] = "{551305, \"[觉醒]雷霆万钧\", \"路飞(尼卡形态)\", 55130, 0, 5, 0, 4, \"active_skill\", 0, 0, 1, 1, {5513005,5513015}, {}, 0, \"路飞跳出云霄携带雷电，对敌方全体单位发动雷电攻击，对敌方全体英雄造成535%法术伤害附加路飞自身攻击力的100%真实伤害，对处于【麻痹】状态下的敌人额外增加60%伤害(该伤害最多不超过自身攻击力的10倍)并且有60%概率使敌方进入【感电】状态\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"70430\", 0, 1, 1, {{58025}}, 0, 0, 2, 0}",
	[532305.0] = "{532305, \"[觉醒]仁爱之心\", \"金鱼乙姬\", 53230, 0, 5, 0, 4, \"active_skill\", 0, 0, 2, 1, {5323003}, {}, 0, \"选择宽容一切的乙姬慰藉伙伴，复活己方单体，并回复其等同自身攻击力198%的生命，若己方无死亡单位，则为己方全体恢复乙姬攻击力105%生命，且为其附加一层【不屈】效果，持续2回合\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"53230\", 0, 1, 1, {{19201}}, 0, 0, 2, 0}",
	[516323.0] = "{516323, \"空裂\", \"白胡子\", 51632, 516324, 3, 0, 4, \"active_skill\", 0, 0, 1, 1, {5163003,5163013,5164003}, {}, 0, \"白胡子对敌方后排单体发出2段共【320%+目标损失血量百分比*146%】的物理伤害；若在第二段斩击时单位生命值低于30%，则直接击杀目标（该伤害值无视护盾、防御、伤害分摊，伤害为该单位生命值的30%）\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"22583\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[535101.0] = "{535101, \"灭世计划\", \"泽法\", 53510, 535102, 1, 0, 0, \"active_skill\", 0, 0, 5, 1, {5351001}, {}, 0, \"泽法秘密进行自己的灭世计划，第一步是弱化敌方，强化自身。吸取敌方全体6%的攻击力附加到自己身上，此效果每4个回合的前3回合均会释放\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"53510\", 0, 0, 1, {{53511}}, 0, 0, 1, 0}",
	[555204.0] = "{555204, \"见闻色霸气\", \"藤虎(三大将)\", 55520, 555205, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5552002}, {{'atk_per',600},{'hp_max_per',400},{'res',200}}, 0, \"攻击升提60%，生命值提升40%，免伤提升20%，每回合回复自身5%生命值\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"55520\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[777404.0] = "{777404, \"流樱\", \"路飞(和之国)\", 77740, 777405, 4, 0, 0, \"passive_skill\", 0, 0, 1, 1, {7774004,7774014}, {}, 0, \"战斗开始路飞为自身附加流樱，路飞的所有攻击都将对敌方单位附加【灼烧】\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"777401\", 0, 1, 1, {{77816,77804,77814,77834}}, 0, 0, 0, 0}",
	[777303.0] = "{777303, \"橡胶·象枪\", \"路飞(和之国)\", 77730, 777304, 3, 0, 4, \"active_skill\", 0, 0, 1, 1, {7773003,7773013,7770111,7773023}, {}, 0, \"路飞使用【橡胶·象枪】对敌方发起攻击，对敌方全体单位造成318%物理伤害附加自身攻击力的70%，自身生命值的70%真实伤害，对灼烧状态下的单位额外增加60%的伤害，且必定暴击，击杀目标再次释放（每回合仅触发一次）\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"777301\", 0, 1, 1, {{76012}}, 0, 0, 2, 0}",
	[764315.0] = "{764315, \"[觉醒]大炎戒·炎帝\", \"艾斯(龙年)\", 76431, 0, 5, 0, 2, \"active_skill\", 0, 0, 1, 1, {7643105,7643115,7643125}, {}, 0, \"普通状态下与【火拳】效果一致，进入炎帝状态下升级为【大炎戒·炎帝】对敌方全体单位造成300%物理伤害加自身攻击力的200%伤害，该伤害无视防御，并且有20%概率对敌方单位附加【神火·不知火】，对灼烧状态下的敌人增加50%伤害，击杀敌方单位再次施法(每回合最多触发一次)\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"764030\", 0, 1, 1, {{76445}}, 0, 0, 2, 0}",
	[770405.0] = "{770405, \"[觉醒]露娜利亚族\", \"烬\", 77040, 0, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7704005}, {}, 0, \"露娜利亚族拥有极高的速度，烬在战斗开始后为自身增加【露娜利亚族】【负面状态免疫】，烬的每次攻击都会叠加一层【露娜利亚族】，【露娜利亚族】叠加至5层释放【御守·火龙皇】释放技能后清空自身增益buff，并且为自身提供【最终形态】\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"770040\", 0, 1, 1, {{77005,77101,77102,19851}}, 0, 0, 0, 0}",
	[516324.0] = "{516324, \"空裂\", \"白胡子\", 51632, 516325, 4, 0, 4, \"active_skill\", 0, 0, 1, 1, {5163003,5163013,5164003}, {}, 0, \"白胡子对敌方后排单体发出2段共【320%+目标损失血量百分比*146%】的物理伤害；若在第二段斩击时单位生命值低于30%，则直接击杀目标（该伤害值无视护盾、防御、伤害分摊，伤害为该单位生命值的30%）\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"22583\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[273101.0] = "{273101, \"顺劈\", \"海贼9号\", 27310, 0, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {2731001}, {}, 0, \"对随机3个敌方单位造成111%魔法伤害\", \"初始激活\", \"\", \"31191\", 0, 1, 1, {}, 0, 0, 1, 0}",
	[515401.0] = "{515401, \"黑切\", \"鹰眼\", 51540, 515402, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5154001}, {}, 0, \"每次受到来自英雄的攻击时，自身能获得1个【怒气】效果，【怒气】效果可叠加，最多可叠加10层\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"22934\", 0, 1, 1, {{15201}}, 0, 0, 0, 0}",
	[778401.0] = "{778401, \"高速移动\", \"尼治\", 77840, 778402, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7784001}, {}, 0, \"尼治普通攻击附加【感电效果】敌方所有目标使用技能尼治获得一层【高速移动】，【高速移动】叠加至3层尼治释放【起电针刺】，释放【起电针刺】后冷却1回合\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"778401\", 0, 1, 1, {{77911}}, 0, 0, 0, 0}",
