	[534901.0] = "{534901, \"跑打动作\", \"凯多\", 53490, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {5340001}, {}, 0, \"对前方单体造成100%物理伤害\", \"\", \"\", \"20000\", 0, 0, 1, {}, 0, 0, 0, 0}",
