	[771402.0] = "{771402, \"狼神\", \"狼刑\", 77140, 771403, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7714002,7714012}, {}, 0, \"死亡时将立刻以自身35%最大生命值复活，并进入【狼神】状态，此技能只可触发一次\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"77104\", 0, 0, 1, {{66602}}, 0, 0, 0, 0}",
