	[534101.0] = "{534101, \"降三世·引奈落\", \"凯多\", 53410, 534102, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {5341001,5344001}, {}, 0, \"跳到空中，将霸王色霸气缠绕在铁棒上，向下攻击，对敌方单体造成一次134%的伤害，同时附加自身损失生命值百分比的额外伤害。攻击完成后，恢复自身5%最大生命值。\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"53410\", 0, 0, 1, {{53401}}, 0, 0, 1, 0}",
	[554204.0] = "{554204, \"飘飘果实\", \"金狮子·史基\", 55420, 554205, 4, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5542004,5542014}, {{'atk_per',600},{'hp_max_per',400},{'dodge_magic',150}}, 0, \"攻击升提60%，生命值提升40%，抗控提升15%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"70720\", 0, 1, 0, {}, 0, 0, 0, 0}",
	[515402.0] = "{515402, \"黑切\", \"鹰眼\", 51540, 515403, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5154002}, {}, 0, \"每次受到来自英雄的攻击时，自身能获得1个【怒气】效果，【怒气】效果可叠加，最多可叠加10层\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"22934\", 0, 1, 1, {{15202}}, 0, 0, 0, 0}",
	[527001.0] = "{527001, \"普通攻击\", \"黑胡子\", 52700, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {5270001}, {}, 0, \"对前方单体造成100%物理伤害\", \"\", \"\", \"20000\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[765401.0] = "{765401, \"歌歌果实\", \"乌塔(世界歌姬)\", 76540, 765402, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7654001}, {}, 0, \"每回合结束乌塔利用歌歌果实对友方全体单位进行激励，不同的英雄定位会获得不同效果增益\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"765040\", 0, 1, 1, {{765311,765411,765611,765211,765511}}, 0, 0, 0, 0}",
	[554205.0] = "{554205, \"飘飘果实\", \"金狮子·史基\", 55420, 0, 5, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5542005,5542015}, {{'atk_per',700},{'hp_max_per',500},{'dodge_magic',250}}, 0, \"攻击升提70%，生命值提升50%，抗控提升25%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"70720\", 0, 1, 0, {}, 0, 0, 0, 0}",
	[555301.0] = "{555301, \"地狱旅\", \"藤虎(三大将)\", 55530, 555302, 1, 0, 4, \"active_skill\", 0, 0, 2, 1, {5553011,5553021}, {}, 0, \"造成600%的总伤害，由敌方所有单位共同承受，敌方存活英雄越少，每个单位所受伤害越高，每个单位所受伤害不得超过藤虎攻击力的3倍；同时有30%概率附加【致盲】，持续2回合\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"55530\", 0, 1, 1, {{25001}}, 0, 0, 2, 0}",
	[781204.0] = "{781204, \"和平主义者\", \"熊(机械)\", 78120, 781205, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7812004}, {{'hp_max_per',500},{'atk_per',400},{'speed',40},{'res',200}}, 0, \"攻击提升40%，生命提升50%，免伤提升20%，速度提升40；回合开始时，自身获得【和平主义者】\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"781201\", 0, 0, 1, {{26001}}, 0, 0, 0, 0}",
	[536011.0] = "{536011, \"普通攻击\", \"BIG·MOM\", 53601, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {5360011}, {}, 0, \"对前方单体造成100%物理伤害\", \"\", \"\", \"20000\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[515405.0] = "{515405, \"[觉醒]黑切\", \"鹰眼\", 51540, 0, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5154003}, {}, 0, \"每次受到来自英雄的攻击时，自身能获得1个【怒气】效果，【怒气】效果可叠加，最多可叠加10层\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"22934\", 0, 1, 1, {{15203}}, 0, 0, 0, 0}",
	[771405.0] = "{771405, \"[觉醒]狼神\", \"狼刑\", 77140, 0, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7714005,7714015}, {}, 0, \"死亡时将立刻以自身50%最大生命值复活，并进入【狼神】状态，此技能只可触发一次\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"77104\", 0, 0, 1, {{66605}}, 0, 0, 0, 0}",
	[777501.0] = "{777501, \"流樱(复活)\", \"路飞(和之国)\", 77750, 777501, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7775001}, {}, 0, \"\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"225501\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[533105.0] = "{533105, \"[觉醒]无双年糕刃弹\", \"卡塔库栗\", 53310, 0, 5, 0, 4, \"active_skill\", 0, 0, 1, 1, {5331003,5331803}, {}, 0, \"卡塔库栗用武装色霸气将年糕包裹如雨般攻击敌方全体，造成160%的物理伤害且有100%概率将在命中目标身上添加一层等同自身攻击力50%的【年糕附着】效果，如目标血量高于40%，则额外60%概率再添加一层【年糕附着】\", \"初始激活\", \"\", \"53310\", 0, 0, 1, {{53303}}, 0, 0, 1, 0}",
	[252201.0] = "{252201, \"鱼人体质\", \"阿龙\", 25220, 0, 1, 0, 2, \"passive_skill\", 0, 0, 1, 1, {}, {{'atk_per',100},{'crit_rate',60}}, 0, \"攻击提升10%，暴击提升6%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"60392\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[527301.0] = "{527301, \"黑暗领域\", \"黑胡子\", 52730, 527302, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {5273001,5273011}, {}, 0, \"黑胡子将黑暗果实能力压缩后释放，造成巨大的爆裂伤害，对敌方全体造成105%魔法伤害，并在敌方形成一个持续2回合的【黑暗之地】\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"23803\", 0, 0, 1, {{29601}}, 0, 0, 2, 0}",
	[536201.0] = "{536201, \"魂魂果实\", \"BIG·MOM\", 53620, 536202, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5362001}, {{'hp_max_per',150},{'atk_per',100}}, 0, \"生命提升15%，攻击提升10%。战斗开始时，友方全体五皇团提升10%的法抗，此效果不可驱散，持续到战斗结束。BIG·MOM的普通攻击将额外触发随机1种【霍米兹】进行追击。\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"53620\", 0, 0, 1, {{53651,53652,53653}}, 0, 0, 0, 0}",
