	[515404.0] = "{515404, \"黑切\", \"鹰眼\", 51540, 515405, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5154003}, {}, 0, \"每次受到来自英雄的攻击时，自身能获得1个【怒气】效果，【怒气】效果可叠加，最多可叠加10层\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"22934\", 0, 1, 1, {{15203}}, 0, 0, 0, 0}",
