	[536205.0] = "{536205, \"[觉醒]魂魂果实\", \"BIG·MOM\", 53620, 0, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5362003}, {{'hp_max_per',250},{'atk_per',300}}, 0, \"生命提升25%，攻击提升30%。战斗开始时，友方全体五皇团提升30%的法抗，此效果不可驱散，持续到战斗结束。BIG·MOM的普通攻击将额外触发随机2种【霍米兹】进行追击。\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"53620\", 0, 0, 1, {{53651,53652,53653}}, 0, 0, 0, 0}",
	[508403.0] = "{508403, \"心灵强化\", \"鹤\", 50840, 508404, 3, 0, 0, \"passive_skill\", 0, 0, 0, 1, {}, {}, 0, \"普通攻击时，对生命最低的己方单体回复等同自身攻击力50%的生命值\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"51294\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[533103.0] = "{533103, \"无双年糕刃弹\", \"卡塔库栗\", 53310, 533104, 3, 0, 4, \"active_skill\", 0, 0, 1, 1, {5331003,5331803}, {}, 0, \"卡塔库栗用武装色霸气将年糕包裹如雨般攻击敌方全体，造成160%的物理伤害且有100%概率将在命中目标身上添加一层等同自身攻击力50%的【年糕附着】效果，如目标血量高于40%，则额外60%概率再添加一层【年糕附着】\", \"初始激活\", \"\", \"53310\", 0, 0, 1, {{53303}}, 0, 0, 1, 0}",
	[554201.0] = "{554201, \"飘飘果实\", \"金狮子·史基\", 55420, 554202, 1, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5542001,5542011}, {{'atk_per',300},{'hp_max_per',150},{'dodge_magic',50}}, 0, \"攻击提升30%，生命值提升15%，抗控提升5%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"70720\", 0, 1, 0, {}, 0, 0, 0, 0}",
	[758403.0] = "{758403, \"最强剑豪\", \"鹰眼(七武海)\", 75840, 758404, 3, 0, 0, \"passive_skill\", 0, 0, 1, 1, {7584001,7584011,7584021,7585001,7585102}, {}, 0, \"鹰眼(七武海)血量达到一定百分比时受到伤害，将释放他的霸气以消除自身所有的控制效果，并根据他的生命百分比执行以下操作；≤70%：为所有友方恢复鹰眼(七武海)100%攻击力的生命值，并附加【强化】效果；≤50%：对所有敌人造成等同于鹰眼(七武海)生命值上限8%+自身攻击力150%的伤害，并附加【震慑效果】(每个效果释放后冷却2回合)\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：忍者到达<div fontcolor=45a536>12星</div>自动升级\", \"75840\", 0, 0, 1, {{61221,61231,61201,61241}}, 0, 0, 0, 0}",
	[536315.0] = "{536315, \"[觉醒]暴走威国\", \"BIG·MOM\", 53635, 0, 8, 0, 0, \"active_skill\", 0, 0, 5, 1, {5363013,5363014}, {}, 0, \"BIG·MOM站在战场中间，对敌方全体发动不稳定的凶残的斩击，造成1%-332%的法术伤害，若目标生命值低于25%，则直接斩杀。击杀目标为自身添加一层【摄魂印记】。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"53630\", 0, 0, 1, {{53611}}, 0, 0, 0, 0}",
	[554202.0] = "{554202, \"飘飘果实\", \"金狮子·史基\", 55420, 554203, 2, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5542002,5542012}, {{'atk_per',400},{'hp_max_per',200},{'dodge_magic',80}}, 0, \"攻击提升40%，生命值提升20%，抗控提升8%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>8星</div>自动升级\", \"70720\", 0, 1, 0, {}, 0, 0, 0, 0}",
	[772402.0] = "{772402, \"不灭之火\", \"文斯莫克·伊治\", 77240, 772403, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7724032,7724002,7724012,7724022}, {}, 0, \"伊治作为杰尔马家族的后裔，继承了家族世代相传的火焰能力。当伊治血量降低至30%,为自身提供【烈焰爆发】，并且触发一次【火花·双重·回旋】，(该效果每次战斗仅触发一次)\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"772401\", 0, 1, 1, {{77216,77212}}, 0, 0, 0, 0}",
	[537101.0] = "{537101, \"古代兵器\", \"白星\", 53710, 537102, 1, 0, 4, \"active_skill\", 0, 0, 5, 1, {5371001,5371101,5371201}, {}, 0, \"白星在战场上因害怕而哭泣，引来巨大的海王类席卷整个战场，对敌方全体造成72%的法术伤害，20%概率使目标【减速】，35%概率附加【出血】效果，若目标身上有【出血】效果，则有额外40%概率再增加一层【出血】，持续2回合。\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"53710\", 0, 0, 1, {{23002,21011}}, 0, 0, 1, 0}",
	[537105.0] = "{537105, \"[觉醒]古代兵器\", \"白星\", 53710, 0, 5, 0, 4, \"active_skill\", 0, 0, 5, 1, {5371003,5371103,5371203}, {}, 0, \"白星在战场上因害怕而哭泣，引来巨大的海王类席卷整个战场，对敌方全体造成117%的法术伤害，50%概率使目标【减速】，60%概率附加【出血】效果，若目标身上有【出血】效果，则有额外65%概率再增加一层【出血】，持续2回合。\", \"初始激活\", \"\", \"53710\", 0, 0, 1, {{23002,21011}}, 0, 0, 1, 0}",
	[533101.0] = "{533101, \"无双年糕刃弹\", \"卡塔库栗\", 53310, 533102, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {5331001,5331801}, {}, 0, \"卡塔库栗用武装色霸气将年糕包裹如雨般攻击敌方全体，造成96%的物理伤害且有60%概率将在命中目标身上添加一层等同自身攻击力30%的【年糕附着】效果，如目标血量高于80%，则额外40%概率再添加一层【年糕附着】\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"53310\", 0, 0, 1, {{53301}}, 0, 0, 1, 0}",
	[772401.0] = "{772401, \"不灭之火\", \"文斯莫克·伊治\", 77240, 772402, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7724031,7724001,7724011,7724021}, {}, 0, \"伊治作为杰尔马家族的后裔，继承了家族世代相传的火焰能力。当伊治血量降低至20%,为自身提供【烈焰爆发】，并且触发一次【火花·双重·回旋】，(该效果每次战斗仅触发一次)\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"772401\", 0, 1, 1, {{77216,77211}}, 0, 0, 0, 0}",
	[539304.0] = "{539304, \"桃源十拳\", \"光月御田\", 53930, 539305, 4, 0, 4, \"active_skill\", 0, \"max_hp_per\", 1, 1, {5393003,5398003,5398999}, {}, 0, \"光月御田的成名绝技，在半空中蓄力，攻击敌方生命值最高的单体，消耗自身25%的最大生命值，造成所消耗生命值数值*1.5倍的物理伤害(此伤害数值不被物连减免)，50%概率附带【破甲】和【出血】效果。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"53930\", 0, 1, 1, {{24100,21011}}, 0, 0, 2, 0}",
	[522111.0] = "{522111, \"复活\", \"汉库克\", 52211, 0, 10, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5221101}, {}, 0, \"生命值低于40%则回复施法者180%攻击力的生命值\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"20000\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[771411.0] = "{771411, \"狼神\", \"狼刑\", 77141, 0, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7714021}, {}, 0, \"在战斗开始时，将给所有友方添加【冻冻果实】效果，为友方提升10%吸血效果，10%攻击提升，5%暴击几率，持续2回合且不可驱散\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"504023\", 0, 1, 1, {}, 0, 0, 0, 0}",
