	[771414.0] = "{771414, \"狼神\", \"狼刑\", 77144, 0, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7714024}, {}, 0, \"在战斗开始时，将给所有友方添加【冻冻果实】效果，为友方提升25%吸血效果，30%攻击提升，20%暴击几率，持续2回合且不可驱散\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"504023\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[772403.0] = "{772403, \"不灭之火\", \"文斯莫克·伊治\", 77240, 772404, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7724033,7724003,7724013,7724023}, {}, 0, \"伊治作为杰尔马家族的后裔，继承了家族世代相传的火焰能力。当伊治血量降低至40%,为自身提供【烈焰爆发】，并且触发一次【火花·双重·回旋】，(该效果每次战斗仅触发一次)\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"772401\", 0, 1, 1, {{77216,77213}}, 0, 0, 0, 0}",
