	[553202.0] = "{553202, \"最高指挥\", \"佛之战国\", 55320, 553203, 2, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5532002}, {{'atk_per',250},{'hp_max_per',350},{'def_per',300}}, 0, \"佛之战国生命提升35%，攻击提升25%，防御提升30%，每回合开始，给所有友军添加【正义】效果\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>8星</div>自动升级\", \"24160\", 0, 1, 1, {{59001}}, 0, 0, 0, 0}",
	[524304.0] = "{524304, \"青炎\", \"马尔科\", 52430, 524305, 4, 0, 4, \"active_skill\", 0, 0, 1, 1, {5243003}, {}, 0, \"对全体敌方造成135%魔法伤害，并随机发动其中一种效果：1、对敌方优先中后排随机3个单位附加【攻击下降20%】效果；2、对敌方优先前中排随机3个单位附加【禁疗】效果；3、70%概率对敌方受击单位附加【破甲】效果；以上效果均持续2回合\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"23403\", 0, 1, 1, {{23203,21890,22104}}, 0, 0, 2, 0}",
