	[226403.0] = "{226403, \"龙威\", \"德雷克\", 22640, 226404, 3, 0, 0, \"passive_skill\", 0, 0, 1, 1, {2264003}, {}, 0, \"战斗开始时，降低敌方全体50%被治疗效果，持续4回合\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"25230\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[531104.0] = "{531104, \"命运抽牌\", \"霍金斯\", 53110, 531105, 4, 0, 2, \"active_skill\", 0, 0, 1, 1, {5311004}, {}, 0, \"霍金斯开始算命，50%概率对敌方前中排敌人造成238%的法术伤害，并有50%概率使目标获得【嘲讽】，持续2回合；50%概率对友方生命值最低的目标，回复280%攻击力的生命值\", \"初始激活\", \"\", \"23711\", 0, 0, 1, {{24001}}, 0, 0, 1, 0}",
	[538302.0] = "{538302, \"半玉·花柳\", \"桃兔\", 53830, 538303, 2, 0, 4, \"active_skill\", 0, 0, 1, 1, {5383002,5383112}, {}, 0, \"桃兔艺伎的魅力贯穿全场，友方角色50%获得【魅力绽放】效果，持续3回合，友方角色50%获得【血脉贲张】效果，持续3回合，敌方角色50%概率获得【嫉妒】效果，持续2回合，敌方角色50%获得【痴迷】效果，持续2回合。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>9星</div>自动升级\", \"53810\", 0, 1, 1, {{538412,538422,538432,538442}}, 0, 0, 2, 0}",
	[761401.0] = "{761401, \"灵灵果实\", \"佩罗娜\", 76140, 761402, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7614021}, {}, 0, \"佩罗娜阵亡时以20%生命值复活一次，普通攻击时，对生命最低的己方单体回复等同自身攻击力30%的生命值，并且驱散所有负面效果\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"761040\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[540301.0] = "{540301, \"鸣谪\", \"大和\", 54030, 540302, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {5403001,5403101,5408001}, {}, 0, \"大和在狼牙棒上缠绕闪电，挥出鸣谪，对随机敌方单体造成179%的物理伤害，造成伤害的同时，鸣谪会对目标造成【洞穿】效果，持续5回合。鸣谪再次攻击身上携带【洞穿】效果的目标时，会额外造成目标生命上限15%的伤害(最大不超过大和攻击力的10倍)。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"54030\", 0, 1, 1, {{54031}}, 0, 0, 2, 0}",
	[531103.0] = "{531103, \"命运抽牌\", \"霍金斯\", 53110, 531104, 3, 0, 2, \"active_skill\", 0, 0, 1, 1, {5311003}, {}, 0, \"霍金斯开始算命，50%概率对敌方前中排敌人造成218%的法术伤害，并有40%概率使目标获得【嘲讽】，持续2回合；50%概率对友方生命值最低的目标，回复240%攻击力的生命值\", \"初始激活\", \"\", \"23711\", 0, 0, 1, {{24001}}, 0, 0, 1, 0}",
	[538303.0] = "{538303, \"半玉·花柳\", \"桃兔\", 53830, 538304, 3, 0, 4, \"active_skill\", 0, 0, 1, 1, {5383003,5383113}, {}, 0, \"桃兔艺伎的魅力贯穿全场，友方角色50%获得【魅力绽放】效果，持续4回合，友方角色50%获得【血脉贲张】效果，持续4回合，敌方角色50%概率获得【嫉妒】效果，持续2回合，敌方角色50%获得【痴迷】效果，持续2回合。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"53810\", 0, 1, 1, {{538411,538421,538431,538441}}, 0, 0, 2, 0}",
	[520301.0] = "{520301, \"二档\", \"路飞\", 52030, 520302, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5203001,5203011}, {}, 0, \"路飞在生命值低于60%时触发二档，二档时驱散身上的异常状态，并提升自身15%攻击力、5%暴击率；二档状态下免疫所有控制技能，【Jet.枪】技能伤害提升至180%且无冷却时间，二档持续4回合,一场战斗只能触发1次\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"22973\", 0, 1, 1, {{16401,19802}}, 0, 0, 0, 0}",
	[540901.0] = "{540901, \"跑打动作\", \"大和\", 54090, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {5409001}, {}, 0, \"对前方单体造成100%物理伤害\", \"\", \"\", \"20000\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[531102.0] = "{531102, \"命运抽牌\", \"霍金斯\", 53110, 531103, 2, 0, 2, \"active_skill\", 0, 0, 1, 1, {5311002}, {}, 0, \"霍金斯开始算命，50%概率对敌方前中排敌人造成168%的法术伤害，并有30%概率使目标获得【嘲讽】，持续2回合；50%概率对友方生命值最低的目标，回复180%攻击力的生命值\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>7星</div>自动升级\", \"23711\", 0, 0, 1, {{24001}}, 0, 0, 1, 0}",
	[541305.0] = "{541305, \"[觉醒]阿修罗·亡者戏\", \"索隆(和之国)\", 54130, 0, 5, 0, 2, \"active_skill\", 0, \"min_hp_per\", 1, 1, {5411005,5411011,5411006}, {}, 0, \"索隆的终极招式，非【阿修罗形态】下效果与炼狱鬼斩一致。处于【阿修罗形态】下，则消耗自身25%的最大生命值，对敌方全体造成自身最大生命值25%加自身攻击力300%的真实伤害(该伤害无视免伤，无视防御，最大不超过自身攻击力的3倍)，吸取本次造成伤害的50%生命值\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"54130\", 0, 1, 1, {{54133}}, 0, 0, 2, 0}",
	[536314.0] = "{536314, \"暴走威国\", \"BIG·MOM\", 53634, 536315, 7, 0, 0, \"active_skill\", 0, 0, 5, 1, {5363013,5363014}, {}, 0, \"BIG·MOM站在战场中间，对敌方全体发动不稳定的凶残的斩击，造成1%-332%的法术伤害，若目标生命值低于25%，则直接斩杀。击杀目标为自身添加一层【摄魂印记】。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"53630\", 0, 0, 1, {{53611}}, 0, 0, 0, 0}",
	[527303.0] = "{527303, \"黑暗领域\", \"黑胡子\", 52730, 0, 3, 0, 4, \"active_skill\", 0, 0, 1, 1, {5273003,5273013}, {}, 0, \"黑胡子将黑暗果实能力压缩后释放，造成巨大的爆裂伤害，对敌方全体造成153%魔法伤害，随机降低2个单位15%控制率并在敌方形成一个持续2回合的【黑暗之地】\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"23803\", 0, 0, 1, {{29603,23413}}, 0, 0, 2, 0}",
	[531101.0] = "{531101, \"命运抽牌\", \"霍金斯\", 53110, 531102, 1, 0, 2, \"active_skill\", 0, 0, 1, 1, {5311001}, {}, 0, \"霍金斯开始算命，50%概率对敌方前中排敌人造成128%的法术伤害；50%概率对友方生命值最低的目标，回复140%攻击力的生命值\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"23711\", 0, 0, 1, {}, 0, 0, 1, 0}",
	[538301.0] = "{538301, \"半玉·花柳\", \"桃兔\", 53830, 538302, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {5383001,5383111}, {}, 0, \"桃兔艺伎的魅力贯穿全场，友方角色50%获得【魅力绽放】效果，持续2回合，友方角色50%获得【血脉贲张】效果，持续2回合，敌方角色50%概率获得【嫉妒】效果，持续2回合，敌方角色50%获得【痴迷】效果，持续2回合。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"53810\", 0, 1, 1, {{538411,538421,538431,538441}}, 0, 0, 2, 0}",
	[520302.0] = "{520302, \"二档\", \"路飞\", 52030, 520303, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5203002,5203012}, {}, 0, \"路飞在生命值低于60%时触发二档，二档时驱散身上的异常状态，并提升自身30%攻击力、10%暴击率；二档状态下免疫所有控制技能，【Jet.枪】技能伤害提升至231%且无冷却时间，二档持续4回合,一场战斗只能触发1次\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>9星</div>自动升级\", \"22973\", 0, 1, 1, {{16402,19802}}, 0, 0, 0, 0}",
	[541501.0] = "{541501, \"无惧死神\", \"索隆(和之国)\", 54150, 0, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {}, {}, 0, \"每回合开始时，会消耗极限值恢复自身生命值\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"54140\", 0, 1, 1, {{54149}}, 0, 0, 0, 0}",
	[552202.0] = "{552202, \"百兽凯多\", \"凯多(神龙)\", 55220, 552203, 2, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5522002}, {{'atk_per',250},{'hp_max_per',350},{'speed',20}}, 0, \"凯多生命提升35%，攻击提升25%，速度提升20，每回合开始，对敌方随机1名单位造成雷击使其陷入【眩晕】\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>8星</div>自动升级\", \"55220\", 0, 1, 1, {{28201}}, 0, 0, 0, 0}",
	[764104.0] = "{764104, \"火拳\", \"艾斯(龙年)\", 76410, 764105, 4, 0, 2, \"active_skill\", 0, 0, 1, 1, {7641004,7641104}, {}, 0, \"对敌方人数最多一排造成420%的物理伤害，对灼烧状态下的敌人增加40%伤害，该技能附加25%无视防御，有50%概率对敌方单位附加【神火·不知火】，击杀敌人再次施法(每回合最多触发一次)\", \"初始激活\", \"\", \"764010\", 0, 1, 1, {{76444}}, 0, 0, 1, 0}",
	[544901.0] = "{544901, \"跑打动作\", \"光月时\", 54490, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {5449001}, {}, 0, \"对前方单体造成100%物理伤害\", \"\", \"\", \"20000\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[536312.0] = "{536312, \"暴走威国\", \"BIG·MOM\", 53632, 536313, 5, 0, 0, \"active_skill\", 0, 0, 5, 1, {5363012,5363014}, {}, 0, \"BIG·MOM站在战场中间，对敌方全体发动不稳定的凶残的斩击，造成1%-268%的法术伤害，若目标生命值低于20%，则直接斩杀。击杀目标为自身添加一层【摄魂印记】。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>9星</div>自动升级\", \"53630\", 0, 0, 1, {{53611}}, 0, 0, 0, 0}",
	[552203.0] = "{552203, \"百兽凯多\", \"凯多(神龙)\", 55220, 552204, 3, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5522003}, {{'atk_per',400},{'hp_max_per',500},{'speed',35}}, 0, \"凯多生命提升50%，攻击提升40%，速度提升35，每回合开始，对敌方随机2名单位造成雷击使其陷入【眩晕】\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"55220\", 0, 1, 1, {{28201}}, 0, 0, 0, 0}",
	[513301.0] = "{513301, \"雷冶金\", \"艾尼路\", 51330, 513302, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {5133001,5133021}, {}, 0, \"艾尼路召唤雷霆攻击前方2个单位，对每个单位造成153%魔法伤害，35%概率对目标附加【迟缓】效果，持续2回合；同时为自己生成一个持续2回合的【护盾】，护盾值为本次技能带来伤害的10%\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"20230\", 0, 1, 1, {{28001,12102}}, 0, 0, 2, 0}",
	[520303.0] = "{520303, \"二档\", \"路飞\", 52030, 0, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5203003,5203013}, {}, 0, \"路飞在生命值低于60%时触发二档，二档时驱散身上的异常状态，并提升自身30%攻击力、10%暴击率、20%暴击伤害；二档状态下免疫所有控制技能，【Jet.枪】技能伤害提升至281%且无冷却时间，二档持续4回合,一场战斗只能触发1次\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"22973\", 0, 1, 1, {{16403,19802}}, 0, 0, 0, 0}",
	[759405.0] = "{759405, \"[觉醒]大吃一惊\", \"乌索普(新世界)\", 75940, 0, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7594005,7594015}, {}, 0, \"战斗开始为自身增加【大吃一惊】，击杀敌方单位自身增加【海上战士】\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：忍者到达<div fontcolor=45a536>12星</div>自动升级\", \"75940\", 0, 0, 1, {{75945,75955,75921,75935}}, 0, 0, 0, 0}",
	[781601.0] = "{781601, \"友方死亡触发\", \"熊(机械)\", 78160, 0, 1, 0, 0, \"passive_skill\", 0, 0, 2, 1, {7816001}, {}, 0, \"队友死亡时，自身获得1层【肉球果实】，持续4回合。\", \"\", \"\", \"781401\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[537305.0] = "{537305, \"[觉醒]万物之声\", \"白星\", 53730, 0, 5, 0, 4, \"active_skill\", 0, 0, 5, 1, {5373003,5373103}, {}, 0, \"白星聆听万物之声，在己方阵地上施加【波塞冬的庇护】，使友方全体每个单位免受2次伤害，同时使己方所有单位获得【波塞冬的加持】，持续2回合。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"53730\", 0, 1, 1, {{53733,53753}}, 0, 0, 2, 0}",
	[545204.0] = "{545204, \"手术果实觉醒\", \"罗(和之国)\", 54520, 545205, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5452004,5452104}, {{'hp_max_per',500},{'atk_per',450}}, 0, \"罗在果实觉醒后，生命提升50%，攻击提升45%。每回合开始时，会释放一次寂静领域，85%概率为敌方2个单位附加【寂静领域】，持续1回合\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"54520\", 0, 1, 1, {{54521}}, 0, 0, 0, 0}",
	[285001.0] = "{285001, \"重锤\", \"克利克\", 28500, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {2850001}, {}, 0, \"对前方单体造成100%物理伤害\", \"\", \"\", \"20000\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[781602.0] = "{781602, \"回合开始触发\", \"熊(机械)\", 78161, 0, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7816002}, {}, 0, \"回合开始时，100%概率获得获得1层【肉球果实】\", \"\", \"\", \"781401\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[542205.0] = "{542205, \"[觉醒]音音果实\", \"阿普\", 54220, 0, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {}, {{'hp_max_per',500},{'atk_per',550},{'hit_magic',180}}, 0, \"阿普生命提升50%，攻击提升55%，控制率提高18%。\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"54220\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[537302.0] = "{537302, \"万物之声\", \"白星\", 53730, 537303, 2, 0, 4, \"active_skill\", 0, 0, 5, 1, {5373002,5373102}, {}, 0, \"白星聆听万物之声，在己方阵地上施加【波塞冬的庇护】，使友方全体每个单位免受1次伤害，同时使己方所有单位获得【波塞冬的加持】，持续2回合。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>9星</div>自动升级\", \"53730\", 0, 1, 1, {{53732,53752}}, 0, 0, 2, 0}",
	[536311.0] = "{536311, \"暴走威国\", \"BIG·MOM\", 53631, 536312, 4, 0, 0, \"active_skill\", 0, 0, 5, 1, {5363011,5363014}, {}, 0, \"BIG·MOM站在战场中间，对敌方全体发动不稳定的凶残斩击，造成1%-196%的法术伤害，若目标生命值低于15%，则直接斩杀。击杀目标为自身添加一层【摄魂印记】。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"53630\", 0, 0, 1, {{53611}}, 0, 0, 0, 0}",
	[544404.0] = "{544404, \"治愈迁跃\", \"光月时\", 54440, 544405, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5444004,5444104}, {}, 0, \"每回合结束时，光月时引动时空，将上一个回合中通过【时空法阵】迁跃的治疗效果平摊至友方全体目标，产生攻击力82%加上【时空法阵】中迁跃的治疗，同时驱散友方全体1个负面效果。此技能产生治疗不会被迁跃。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"54440\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[544405.0] = "{544405, \"[觉醒]治愈迁跃\", \"光月时\", 54440, 0, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5444005,5444105}, {}, 0, \"每回合结束时，光月时引动时空，将上一个回合中通过【时空法阵】迁跃的治疗效果平摊至友方全体目标，产生攻击力92%加上【时空法阵】中迁跃的治疗，同时驱散友方全体1个负面效果。此技能产生治疗不会被迁跃。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"54440\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[537303.0] = "{537303, \"万物之声\", \"白星\", 53730, 537304, 3, 0, 4, \"active_skill\", 0, 0, 5, 1, {5373003,5373103}, {}, 0, \"白星聆听万物之声，在己方阵地上施加【波塞冬的庇护】，使友方全体每个单位免受2次伤害，同时使己方所有单位获得【波塞冬的加持】，持续2回合。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"53730\", 0, 1, 1, {{53733,53753}}, 0, 0, 2, 0}",
	[758411.0] = "{758411, \"强化\", \"鹰眼(七武海)\", 75841, 0, 1, 0, 0, \"passive_skill\", 0, 0, 1, 1, {7584101}, {}, 0, \"攻击力增加6%,自身行动后将恢复20%攻击力的生命值，持续2回合，不可驱散\", \"\", \"\", \"\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[542103.0] = "{542103, \"刮盘·斩\", \"阿普\", 54210, 542104, 3, 0, 4, \"active_skill\", 0, 0, 1, 1, {5421003,5421103,5421113,5421123,5421203,5421303,5421403,5421503,5421603,5421703,5421803,5421903}, {}, 0, \"阿普使用音波对目标进行斩击，对敌方全体造成88%的法术伤害，同时音爆会对敌方产生任意一种常规负面状态(减速、出血、致盲、迟缓、石化、沉默、封印、禁疗、睡眠、缓伤、破甲、混乱)，每种负面状态概率均为26%，负面状态持续2回合。\", \"初始激活\", \"\", \"54210\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[513303.0] = "{513303, \"雷冶金\", \"艾尼路\", 51330, 513304, 3, 0, 4, \"active_skill\", 0, 0, 1, 1, {5133003,5133023}, {}, 0, \"艾尼路召唤雷霆攻击前方2个单位，对每个单位造成220%魔法伤害，55%概率对目标附加【迟缓】效果，持续2回合；同时为自己生成一个持续2回合的【护盾】，护盾值为本次技能带来伤害的30%\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"20230\", 0, 1, 1, {{28001,12104}}, 0, 0, 2, 0}",
	[542203.0] = "{542203, \"音音果实\", \"阿普\", 54220, 542204, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {}, {{'hp_max_per',300},{'atk_per',350},{'hit_magic',90}}, 0, \"阿普生命提升30%，攻击提升35%，控制率提高9%。\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"54220\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[781001.0] = "{781001, \"普通攻击\", \"熊(机械)\", 78100, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {7810001}, {}, 0, \"对前方单体造成100%法术物理伤害\", \"\", \"\", \"-20000\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[542301.0] = "{542301, \"刮盘·爆\", \"阿普\", 54230, 542302, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {5423001,5423991}, {}, 0, \"阿普在敌方阵地炸开音波，对敌方全体造成72%的法术伤害，目标身上每存在一种负面效果，则额外增加2%的伤害，以及3%概率使目标陷入【音波共震】（每种负面状态单独计算概率）。对己方全体44%概率施加【音波协调】。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"54230\", 0, 1, 1, {{54231,54232}}, 0, 0, 2, 0}",
	[557901.0] = "{557901, \"跑打动作\", \"凯撒\", 55790, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {5579001}, {}, 0, \"对前方全体目标造成100%的物理伤害\", \"\", \"\", \"20000\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[537301.0] = "{537301, \"万物之声\", \"白星\", 53730, 537302, 1, 0, 4, \"active_skill\", 0, 0, 5, 1, {5373001,5373101}, {}, 0, \"白星聆听万物之声，在己方阵地上施加【波塞冬的庇护】，使友方全体每个单位免受1次伤害，同时使己方所有单位获得【波塞冬的加持】，持续2回合。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"53730\", 0, 1, 1, {{53731,53751}}, 0, 0, 2, 0}",
	[546203.0] = "{546203, \"合体果实\", \"巴雷特\", 54620, 546204, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5462003}, {{'hp_max_per',300},{'def_per',200}}, 0, \"生命提升30%，攻击提升20%，战斗开始时，友方所有五皇团角色抗控提高10%；增益效果均持续至战斗结束，且不会被驱散\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"54620\", 0, 1, 1, {{54623}}, 0, 0, 0, 0}",
	[779015.0] = "{779015, \"普通攻击\", \"贝克曼\", 77905, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {7790015}, {}, 0, \"对前方1个目标造成100%的魔法伤害\", \"\", \"\", \"20000\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[513302.0] = "{513302, \"雷冶金\", \"艾尼路\", 51330, 513303, 2, 0, 4, \"active_skill\", 0, 0, 1, 1, {5133002,5133022}, {}, 0, \"艾尼路召唤雷霆攻击前方2个单位，对每个单位造成184%魔法伤害，45%概率对目标附加【迟缓】效果，持续2回合；同时为自己生成一个持续2回合的【护盾】，护盾值为本次技能带来伤害的20%\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>7星</div>自动升级\", \"20230\", 0, 1, 1, {{28001,12103}}, 0, 0, 2, 0}",
	[755301.0] = "{755301, \"饼干防御\", \"克力架\", 75530, 755302, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7553001,7553011}, {}, 0, \"克力架受到伤害时召唤饼干战士对敌方生命值最低单位进行一次攻击，造成150%+防御*0.1的物理伤害，克力架被攻击时为自身增加【饼干护甲】。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"75530\", 0, 1, 1, {{75531}}, 0, 0, 2, 0}",
	[776304.0] = "{776304, \"威国&霸海\", \"夏洛特玲玲\", 77630, 776305, 4, 0, 4, \"active_skill\", 0, 0, 1, 1, {7763004,7763014,7763024}, {}, 0, \"四皇夏洛特·玲玲与凯多合体招式【威国&霸海】对敌方全体造成408%法术伤害附加自身最大生命值的80%自身攻击力的80%真实伤害，并且有50%的概率使受击着触发【灵魂消散】，该技能成功击杀目标触发技能【灵魂果实】\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"776301\", 0, 1, 1, {{77701}}, 0, 0, 2, 0}",
	[756401.0] = "{756401, \"甜点将星\", \"夏洛特·斯慕吉\", 75640, 756402, 1, 0, 4, \"passive_skill\", 0, \"max_atk\", 2, 1, {7564001}, {}, 0, \"在回合开始时，给攻击力最高的1名友方施加【榨榨果实】效果，免疫所有控制效果，攻击力增加10%，暴击率增加5%，效果持续2回合。触发后，该技能进入4回合的冷却时间\", \"\", \"\", \"75640\", 0, 1, 1, {{61431}}, 0, 0, 0, 0}",
	[551203.0] = "{551203, \"橡胶果实\", \"路飞(尼卡形态)\", 55120, 551204, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5512003,5512013}, {{'atk_per',400},{'hp_max_per',500},{'speed',35}}, 0, \"路飞生命提升50%，攻击提升40%，速度提升35，战斗开始时自身获得【绝缘橡胶】，己方随机两名英雄获得【控制免疫】持续一回合\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"70420\", 0, 1, 1, {{19852,58041}}, 0, 0, 0, 0}",
	[545505.0] = "{545505, \"[觉醒]耐性\", \"罗(和之国)\", 54550, 0, 5, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5455003}, {}, 0, \"0.19\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"54550\", 0, 1, 1, {{54553}}, 0, 0, 0, 0}",
	[546105.0] = "{546105, \"[觉醒]魔鬼之手\", \"巴雷特\", 54610, 0, 5, 0, 2, \"active_skill\", 0, 0, 1, 1, {5461005,5461105}, {}, 0, \"巴雷特跃至半空中，朝敌方单体施展出超强一击，造成240%的物理伤害，同时附带自身生命上限10%的无视防御伤害，有45%概率对目标附加【嘲讽】，持续2回合\", \"初始激活\", \"\", \"54610\", 0, 1, 1, {{24001}}, 0, 0, 1, 0}",
	[513305.0] = "{513305, \"[觉醒]雷冶金\", \"艾尼路\", 51330, 0, 5, 0, 4, \"active_skill\", 0, 0, 1, 1, {5133003,5133023}, {}, 0, \"艾尼路召唤雷霆攻击前方2个单位，对每个单位造成220%魔法伤害，55%概率对目标附加【迟缓】效果，持续2回合；同时为自己生成一个持续2回合的【护盾】，护盾值为本次技能带来伤害的30%\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"20230\", 0, 1, 1, {{28001,12104}}, 0, 0, 2, 0}",
	[546205.0] = "{546205, \"[觉醒]合体果实\", \"巴雷特\", 54620, 0, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5462005}, {{'hp_max_per',500},{'def_per',400}}, 0, \"生命提升50%，攻击提升40%，战斗开始时，友方所有五皇团角色抗控提高20%；增益效果均持续至战斗结束，且不会被驱散\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"54620\", 0, 1, 1, {{54623}}, 0, 0, 0, 0}",
	[546301.0] = "{546301, \"魔鬼形态\", \"巴雷特\", 54630, 546302, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5463001}, {}, 0, \"受到攻击时，50%概率获得1层【钢铁肌肉】，累计获得6层【钢铁肌肉】时，6层【钢铁肌肉】转化为1层【魔鬼形态】\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"54630\", 0, 1, 1, {{54631,54691}}, 0, 0, 0, 0}",
	[536305.0] = "{536305, \"[觉醒]威国\", \"BIG·MOM\", 53630, 0, 5, 0, 4, \"active_skill\", 0, 0, 5, 1, {5363003,5363004}, {}, 0, \"BIG·MOM站在战场中间，对敌方全体发动凶残的斩击，造成166%的法术伤害，若目标生命值低于25%，则直接斩杀。击杀目标为自身添加一层【摄魂印记】。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"53630\", 0, 0, 1, {{53611}}, 0, 0, 2, 0}",
	[732301.0] = "{732301, \"暗穴道\", \"黑胡子(四皇)\", 73230, 732302, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {7323001,7323013}, {}, 0, \"对所有敌人造成共计600%的法术伤害，这些伤害由地方所有单位均摊，受击单位越少，造成的伤害越高，伤害不超过黑胡子自身攻击力的5倍，并有40%概率附加【黑暗印记】效果\", \"\", \"\", \"73230\", 0, 1, 1, {{61091,21001}}, 0, 0, 2, 0}",
	[732021.0] = "{732021, \"默认攻击\", \"黑胡子(四皇)\", 73202, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {7320201}, {}, 0, \"对后排生命值最低的3个敌人造成110%法术伤害，并且有45%概率对每个目标施加【黑暗印记】\", \"\", \"\", \"20000\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[546401.0] = "{546401, \"战争机器\", \"巴雷特\", 54640, 546402, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5464001}, {}, 0, \"巴雷特是天生的战争机器，信奉独自战斗的力量，友方角色死亡时，巴雷特获得一层【BULLET】，累计达到4层【BULLET】时，4层【BULLET】转化成【最终姿态】，且【魔鬼之手】转化为【终极巨炮】。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"54640\", 0, 1, 1, {{54641,54681,54671}}, 0, 0, 0, 0}",
	[548101.0] = "{548101, \"旱灾\", \"杰克\", 54810, 548102, 1, 0, 2, \"active_skill\", 0, 0, 5, 1, {5481001,5481101,5481201,5481301}, {}, 0, \"百兽海贼团的三灾之一，因所踏之处如同旱灾出现般干涸腐朽，吸取敌方全体6%的防御附加到自己身上，杰克血量高于50%时，给自身附加持续2回合的【反弹护盾】，血量低于50%时回复自身3%的最大生命值\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"54810\", 0, 1, 1, {{54811,54831}}, 0, 0, 1, 0}",
	[513304.0] = "{513304, \"雷冶金\", \"艾尼路\", 51330, 513305, 4, 0, 4, \"active_skill\", 0, 0, 1, 1, {5133003,5133023}, {}, 0, \"艾尼路召唤雷霆攻击前方2个单位，对每个单位造成220%魔法伤害，55%概率对目标附加【迟缓】效果，持续2回合；同时为自己生成一个持续2回合的【护盾】，护盾值为本次技能带来伤害的30%\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"20230\", 0, 1, 1, {{28001,12104}}, 0, 0, 2, 0}",
	[153405.0] = "{153405, \"[觉醒]四皇之慑\", \"香克斯\", 15340, 0, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {1534104,1534004}, {}, 0, \"对生命值低于55%的单位伤害提升40%，同时对坦克职业的单位伤害提升30%\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"24210\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[215209.0] = "{215209, \"野蛮恢复\", \"海贼14号\", 21520, 215210, 9, 0, 4, \"active_skill\", 0, 0, 2, 1, {2152009}, {}, 0, \"为己方生命值最低的2个单位，恢复关联海贼14号攻击力的73.4%+56点生命值\", \"开启条件测试\", \"\", \"21520\", 0, 1, 1, {}, 0, 1, 2, 0}",
	[216202.0] = "{216202, \"情绪少女\", \"幽冥公主\", 21620, 216203, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {}, {{'atk_per',100},{'hp_max_per',250},{'cure',50}}, 0, \"生命提升25%，攻击提升10%，治疗效果提升5%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>8星</div>自动升级\", \"21630\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[536303.0] = "{536303, \"威国\", \"BIG·MOM\", 53630, 536304, 3, 0, 4, \"active_skill\", 0, 0, 5, 1, {5363003,5363004}, {}, 0, \"BIG·MOM站在战场中间，对敌方全体发动凶残的斩击，造成166%的法术伤害，若目标生命值低于25%，则直接斩杀。击杀目标为自身添加一层【摄魂印记】。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"53630\", 0, 0, 1, {{53611}}, 0, 0, 2, 0}",
	[548305.0] = "{548305, \"[觉醒]猛犸斩击\", \"杰克\", 54830, 0, 5, 0, 4, \"active_skill\", 0, 0, 1, 1, {5483004,5483104}, {}, 0, \"杰克对随机3名敌方发起猛烈斩击造成207%伤害，并根据自身物理防御提升攻击伤害，伤害不超过自身攻击10倍，并且必定附加【嘲讽】\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"54830\", 0, 1, 1, {{24003}}, 0, 0, 2, 0}",
	[253202.0] = "{253202, \"四分五裂果实\", \"小丑巴基\", 25320, 253203, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {}, {{'atk_per',100},{'hp_max_per',200}}, 0, \"生命提升20%，攻击提升10%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>8星</div>自动升级\", \"21650\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[549105.0] = "{549105, \"[觉醒]粉色毒雾\", \"蕾玖\", 54910, 0, 5, 0, 4, \"active_skill\", 0, 0, 1, 1, {5491003}, {}, 0, \"蕾玖对敌方释放出大量具有强烈毒性的毒雾，对敌方全体造成145%的法术伤害，并有55%概率为目标附加1层【粉红毒素】\", \"初始激活\", \"\", \"54910\", 0, 1, 1, {{54911}}, 0, 0, 1, 0}",
	[549204.0] = "{549204, \"外骨骼·毒蛾\", \"蕾玖\", 54920, 549205, 4, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5492003}, {{'atk_per',200},{'hp_max_per',350},{'cure',100}}, 0, \"搭配着杰尔马66的科技力量，蕾玖生命提升35%，攻击提升20%，治疗效果提升10%，受到攻击时，50%概率使攻击者沾染1层【粉红毒素】\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"54920\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[522305.0] = "{522305, \"[觉醒]甜甜箭\", \"汉库克\", 52230, 0, 5, 0, 4, \"active_skill\", 0, 0, 1, 1, {5223003,5223013}, {}, 0, \"对敌人全体单位造成135%物理伤害，并有70%概率附加2回合的【甜甜印记】，且对我方2个生命值最低的单位回复汉库克攻击128%的血量\", \"初始激活\", \"\", \"22991\", 0, 1, 1, {{20101}}, 0, 0, 2, 0}",
	[153901.0] = "{153901, \"刀扇\", \"香克斯\", 15390, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {1539001}, {}, 0, \"0\", \"\", \"\", \"20310\", 0, 1, 1, {}, 0, 1, 1, 0}",
	[779301.0] = "{779301, \"威慑射击\", \"贝克曼\", 77930, 779302, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {7793001,7793011}, {}, 0, \"贝克曼用燧发式来福枪威胁敌人，令其不敢动弹!对前方一列目标造成162%法术伤害;附加自身攻击力50%，自身生命值50%的真实伤害，为所有命中目标附加【攻击降低】与【防御降低】(该伤害最大不超过自身攻击力的6倍)\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"779301\", 0, 1, 1, {{78401,78411}}, 0, 0, 2, 0}",
	[536301.0] = "{536301, \"威国\", \"BIG·MOM\", 53630, 536302, 1, 0, 4, \"active_skill\", 0, 0, 5, 1, {5363001,5363004}, {}, 0, \"BIG·MOM站在战场中间，对敌方全体发动凶残的斩击，造成98%的法术伤害，若目标生命值低于15%，则直接斩杀。击杀目标为自身添加一层【摄魂印记】。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"53630\", 0, 0, 1, {{53611}}, 0, 0, 2, 0}",
	[550001.0] = "{550001, \"普通攻击\", \"奎因\", 55000, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {5500001}, {}, 0, \"对前方单体造成100%物理伤害\", \"\", \"\", \"20000\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[554402.0] = "{554402, \"传奇大海贼\", \"金狮子·史基\", 55440, 554403, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5544302}, {}, 0, \"攻击目标时，有60%概率额外进行1次【普通攻击】，造成110%伤害，被攻击时60%概率使用伤害率为120%的【普通攻击】进行反击，不受【封印】和【静电】效果影响；每次被攻击自身恢复生命上限1%的生命值\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"70740\", 0, 1, 0, {}, 0, 0, 0, 0}",
	[510401.0] = "{510401, \"以牙还牙\", \"卡普\", 51040, 510402, 1, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5104001}, {}, 0, \"受到攻击时，50%概率使用【特大铁球】对目标进行反击\", \"\", \"\", \"21680\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[768404.0] = "{768404, \"血统因子\", \"伽治\", 76840, 768405, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7684004,7684014,7684024}, {{'hp_max_per',400},{'def_per',200},{'res',200}}, 0, \"文斯莫克家族独有得血统因子，血量提升40%，防御力提升20%，免伤提升20%，每次受到攻击叠加一层【血统因子】，叠加至5层为自身增加【血统因子·觉醒】\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"768401\", 0, 1, 1, {{110201,61944}}, 0, 0, 0, 0}",
	[550201.0] = "{550201, \"龙龙果实·腕龙\", \"奎因\", 55020, 550202, 1, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5502001,5502101}, {{'hp_max_per',150},{'atk_per',150},{'def_per',150}}, 0, \"动物系·龙龙果实·古代种·腕龙形态能力者，生命提高15%，攻击提高15%，防御提高15%。每次受到伤害不会超过最大生命值的20%（对真实伤害无效），当生命值低于50%时受到伤害前将会回复20%最大生命值，此效果每次战斗只生效1次\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"55020\", 0, 1, 1, {}, 0, 0, 0, 0}",
