	[780514.0] = "{780514, \"震荡\", \"白胡子(巅峰)\", 78051, 780515, 4, 0, 0, \"passive_skill\", 0, 0, 1, 1, {7805104}, {}, 0, \"每次攻击时有60%概率对目标附加【震荡】\", \"\", \"\", \"\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[732402.0] = "{732402, \"能量倾斜\", \"黑胡子(四皇)\", 73240, 732403, 2, 0, 0, \"passive_skill\", 0, 0, 2, 1, {7324002}, {}, 0, \"对目标存在黑暗印记的敌人增伤50%，黑胡子将果实能量分配给其他队友，战斗开始时，提高全体队友10%攻击力，不能被移除，持续2回合。每当敌方被击杀时将再次触发，最多叠加2层。\", \"\", \"\", \"73240\", 0, 1, 1, {{61082}}, 0, 0, 0, 0}",
	[551402.0] = "{551402, \"果实觉醒\", \"路飞(尼卡形态)\", 55140, 551403, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5514002,5514012,5514022}, {}, 0, \"路飞死亡后触发果实觉醒，敲响【解放之鼓】立即以35%的血量复活，自身永久增加【果实觉醒】，驱散友方随机3名英雄的负面状态(不包括控制类)\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"70440\", 0, 1, 1, {{58011,58002}}, 0, 0, 0, 0}",
	[510405.0] = "{510405, \"[觉醒]以牙还牙\", \"卡普\", 51040, 0, 5, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5104003}, {}, 0, \"在受到攻击时，80%概率使用【特大铁球】对目标进行反击\", \"\", \"\", \"21680\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[769403.0] = "{769403, \"森森果实\", \"绿牛\", 76940, 769404, 3, 0, 0, \"passive_skill\", 0, 0, 2, 1, {7694003,7694013,7694023}, {}, 0, \"森森果实能力者战斗开始对己方全体英雄增加【治疗提升】，对友方传奇阵容英雄增加【森森攻击】【森森防御】，对自身增加【自然之力】\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"769401\", 0, 1, 1, {{76936,76923,76943,76953}}, 0, 0, 0, 0}",
	[768402.0] = "{768402, \"血统因子\", \"伽治\", 76840, 768403, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7684002,7684012,7684022}, {{'hp_max_per',200},{'def_per',100},{'res',100}}, 0, \"文斯莫克家族独有得血统因子，血量提升20%，防御力提升10%，免伤提升10%，每次受到攻击叠加一层【血统因子】，叠加至5层为自身增加【血统因子·觉醒】\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"768401\", 0, 1, 1, {{110201,61942}}, 0, 0, 0, 0}",
	[547301.0] = "{547301, \"大王猿枪\", \"路飞(四挡)\", 54730, 547302, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {5473001}, {}, 0, \"橡胶猿王枪的加强版，继续向肌肉里加气强化自身手臂释放出来的招式。对敌方全体造成135%物理伤害并有30%概率附加一层橡胶炸弹\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"70330\", 0, 1, 1, {{57001}}, 0, 0, 2, 0}",
