	[777201.0] = "{777201, \"武装色霸气\", \"路飞(和之国)\", 77720, 777202, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7772001}, {{'hp_max_per',200},{'atk_per',100},{'speed',10},{'crit_rate',50}}, 0, \"生命提升20%，攻击力提升10%，速度提升10，暴击率提升5%，友方单位发起攻击时，路飞使用【橡胶·火箭炮】对敌方单位进行追击，每回合最多追击3次\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"777201\", 0, 1, 1, {{77821}}, 0, 0, 0, 0}",
