	[774204.0] = "{774204, \"黑槛战阵\", \"日奈\", 77420, 774205, 4, 0, 0, \"passive_skill\", 0, \"max_speed\", 1, 1, {7742004}, {{'hp_max_per',500},{'atk_per',400},{'speed',40},{'hit_magic',200}}, 0, \"生命提升50%，攻击力提升40%，速度提升40，控制提升20%，回合开始敌方随机2名单位施加【镣铐】\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"774201\", 0, 1, 1, {{77501}}, 0, 0, 0, 0}",
