	[503403.0] = "{503403, \"黑刀秋水\", \"龙马\", 50340, 503404, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5034003,5034013}, {}, 0, \"龙马为我方最先出手的单位时，则本次攻击时附加25%伤害和15%暴击率；否则每次攻击时有100%概率额外增加1个攻击目标，造成原技能80%的伤害\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"70026\", 0, 1, 1, {}, 0, 0, 0, 0}",
