	[774205.0] = "{774205, \"[觉醒]黑槛战阵\", \"日奈\", 77420, 0, 5, 0, 0, \"passive_skill\", 0, \"max_speed\", 1, 1, {7742005}, {{'hp_max_per',600},{'atk_per',500},{'speed',50},{'hit_magic',400}}, 0, \"生命提升60%，攻击力提升50%，速度提升50，控制提升40%，回合开始敌方随机3名单位施加【镣铐】\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"774201\", 0, 1, 1, {{77501}}, 0, 0, 0, 0}",
	[769504.0] = "{769504, \"森森果实\", \"绿牛\", 76950, 769505, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7695004}, {}, 0, \"森森果实能力者战斗开始对己方全体英雄增加【治疗提升】，对友方传奇阵容英雄增加【森森攻击】【森森防御】，对自身增加【自然之力】\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"769401\", 0, 1, 1, {{76936,76924,76944,76954}}, 0, 0, 0, 0}",
	[153404.0] = "{153404, \"四皇之慑\", \"香克斯\", 15340, 153405, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {1534104,1534004}, {}, 0, \"对生命值低于45%的单位伤害提升35%，同时对坦克职业的单位伤害提升25%\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"24210\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[777301.0] = "{777301, \"橡胶·象枪\", \"路飞(和之国)\", 77730, 777302, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {7773001,7773011,7770111,7773021}, {}, 0, \"路飞使用【橡胶·象枪】对敌方发起攻击，对敌方全体单位造成198%物理伤害附加自身攻击力的50%，自身生命值的50%真实伤害，对灼烧状态下的单位额外增加20%的伤害，且必定暴击，击杀目标再次释放（每回合仅触发一次）\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"777301\", 0, 1, 1, {{76010}}, 0, 0, 2, 0}",
	[762405.0] = "{762405, \"[觉醒]人体肉盾·巴托\", \"巴托洛米奥\", 76240, 0, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7624005}, {}, 0, \"战斗开始为自身增加50%防御力提升，并且每次受到攻击额外提升5%防御力，最大叠加10层(该效果受封印效果影响)\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"762040\", 0, 0, 1, {{76245,76255}}, 0, 0, 0, 0}",
	[522301.0] = "{522301, \"甜甜箭\", \"汉库克\", 52230, 522302, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {5223001}, {}, 0, \"对敌人全体单位造成94%物理伤害，并有50%概率附加2回合的【甜甜印记】\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"22991\", 0, 1, 1, {{20101}}, 0, 0, 2, 0}",
	[507901.0] = "{507901, \"普通攻击\", \"乔巴\", 50790, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {5079001}, {}, 0, \"对前方单体造成100%魔法伤害\", \"\", \"\", \"20000\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[542404.0] = "{542404, \"战斗音乐\", \"阿普\", 54240, 542405, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5424101,5424102,5424103,5424001,5424002,5424003}, {}, 0, \"回合结束时阿普会弹奏战斗音乐，39%概率使友方全体身上携带的增益效果时间刷新至初始回合，33%概率使敌方全体身上携带的负面和控制效果时间刷新至初始回合。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"54240\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[770401.0] = "{770401, \"露娜利亚族\", \"烬\", 77040, 770402, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7704001}, {}, 0, \"露娜利亚族拥有极高的速度，烬在战斗开始后为自身增加【露娜利亚族】【负面状态免疫】，烬的每次攻击都会叠加一层【露娜利亚族】，【露娜利亚族】叠加至5层释放【御守·火龙皇】释放技能后清空自身增益buff，并且为自身提供【最终形态】\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"770040\", 0, 1, 1, {{77001,77101,77102,19851}}, 0, 0, 0, 0}",
	[767304.0] = "{767304, \"糖果潮汐\", \"佩罗斯佩罗\", 76730, 767305, 4, 0, 4, \"active_skill\", 0, 0, 1, 1, {7673004}, {}, 0, \"召唤糖果潮汐随机使用攻击或者祝福技能：如果发动攻击，它将对敌方全体造成305%的法术伤害，并附加【攻击降低】【命中降低】【受疗降低】【中毒】效果；如果发动祝福，将恢复友方全体基于佩罗斯佩罗最大生命值的40%，并附加【攻击提升】【受疗提升】【命中提升】效果\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"206101\", 0, 1, 1, {{23511,61854,20704,21502,10202,11204,31142}}, 0, 0, 2, 0}",
	[767201.0] = "{767201, \"分发糖果\", \"佩罗斯佩罗\", 76720, 767202, 1, 0, 0, \"passive_skill\", 0, 0, 2, 1, {7672001}, {{'hp_max_per',100},{'atk_per',100},{'speed_per',50}}, 0, \"攻击力提升10%，生命值提升10%，速度提升5%，队伍造成暴击时，根据暴击产生伤害量的7%为己方全体单位回血\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"203221\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[772404.0] = "{772404, \"不灭之火\", \"文斯莫克·伊治\", 77240, 772405, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7724034,7724004,7724014,7724024}, {}, 0, \"伊治作为杰尔马家族的后裔，继承了家族世代相传的火焰能力。当伊治血量降低至50%,为自身提供【烈焰爆发】，并且触发一次【火花·双重·回旋】，(该效果每次战斗仅触发一次)\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"772401\", 0, 1, 1, {{77216,77214}}, 0, 0, 0, 0}",
	[770404.0] = "{770404, \"露娜利亚族\", \"烬\", 77040, 770405, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7704004}, {}, 0, \"露娜利亚族拥有极高的速度，烬在战斗开始后为自身增加【露娜利亚族】【负面状态免疫】，烬的每次攻击都会叠加一层【露娜利亚族】，【露娜利亚族】叠加至5层释放【御守·火龙皇】释放技能后清空自身增益buff，并且为自身提供【最终形态】\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"770040\", 0, 1, 1, {{77004,77101,77102,19851}}, 0, 0, 0, 0}",
	[522302.0] = "{522302, \"甜甜箭\", \"汉库克\", 52230, 522303, 2, 0, 4, \"active_skill\", 0, 0, 1, 1, {5223002,5223012}, {}, 0, \"对敌人全体单位造成112%物理伤害，并有60%概率附加2回合的【甜甜印记】，且对我方2个生命值最低的单位回复汉库克攻击106%的血量\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>9星</div>自动升级\", \"22991\", 0, 1, 1, {{20101}}, 0, 0, 2, 0}",
	[552104.0] = "{552104, \"雷鸣八卦\", \"凯多(神龙)\", 55210, 552105, 4, 0, 2, \"active_skill\", 0, 0, 1, 1, {5521004,5521011}, {}, 0, \"对敌方全体造成235%法术伤害，并且有50%概率将其击晕附加【眩晕】效果，此攻击必中，且必定眩晕一名目标\", \"初始激活\", \"\", \"55210\", 0, 1, 1, {{28201}}, 0, 0, 1, 0}",
	[153155.0] = "{153155, \"[觉醒]格里芬\", \"香克斯\", 15315, 0, 5, 0, 4, \"active_skill\", 0, 0, 1, 1, {1531505}, {}, 0, \"香克斯挥舞格里芬，对敌方前两排单位造成245%物理伤害，并附加【流血】状态，持续2回合\", \"初始激活\", \"\", \"15340\", 0, 1, 1, {{21301}}, 0, 1, 1, 0}",
	[770403.0] = "{770403, \"露娜利亚族\", \"烬\", 77040, 770404, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7704003}, {}, 0, \"露娜利亚族拥有极高的速度，烬在战斗开始后为自身增加【露娜利亚族】【负面状态免疫】，烬的每次攻击都会叠加一层【露娜利亚族】，【露娜利亚族】叠加至5层释放【御守·火龙皇】释放技能后清空自身增益buff，并且为自身提供【最终形态】\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"770040\", 0, 1, 1, {{77003,77101,77102,19851}}, 0, 0, 0, 0}",
	[544403.0] = "{544403, \"治愈迁跃\", \"光月时\", 54440, 544404, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5444003,5444103}, {}, 0, \"每回合结束时，光月时引动时空，将上一个回合中通过【时空法阵】迁跃的治疗效果平摊至友方全体目标，产生攻击力72%加上【时空法阵】中迁跃的治疗，同时驱散友方全体1个负面效果。此技能产生治疗不会被迁跃。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"54440\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[544302.0] = "{544302, \"伤害迁跃\", \"光月时\", 54430, 544303, 2, 0, 4, \"active_skill\", 0, 0, 1, 1, {5443002}, {}, 0, \"光月时引动时空的力量，将通过【时空法阵】迁跃到未来的伤害在此时全部释放，平摊至敌方全体，造成基础69%法术伤害加上【时空法阵】中的迁跃法术伤害，单个目标受到的最大伤害不超过光月时攻击力的800%，同时由于力量迁跃的强大效果，使敌方单位有35%概率【致盲】，持续2回合。此技能产生的伤害不会被迁跃。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>9星</div>自动升级\", \"54430\", 0, 1, 1, {{54412}}, 0, 0, 2, 0}",
	[153403.0] = "{153403, \"四皇之慑\", \"香克斯\", 15340, 153404, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {1534103,1534003}, {}, 0, \"对生命值低于40%的单位伤害提升30%，同时对坦克职业的单位伤害提升20%\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"24210\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[515301.0] = "{515301, \"无上大快刀\", \"鹰眼\", 51530, 515302, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {5153001}, {}, 0, \"鹰眼释放所有怒气施展华丽而猛烈剑术，对前方单体造成3次各105%物理伤害的斩击（共315%伤害），每3层【怒气】则额外增加1次斩击（最多2次，共5连击），额外斩击的最后一击会对目标以外随机2个单位造成相同系数的溅射伤害，怒气在行动结束后消失\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"22933\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[522303.0] = "{522303, \"甜甜箭\", \"汉库克\", 52230, 522304, 3, 0, 4, \"active_skill\", 0, 0, 1, 1, {5223003,5223013}, {}, 0, \"对敌人全体单位造成135%物理伤害，并有70%概率附加2回合的【甜甜印记】，且对我方2个生命值最低的单位回复汉库克攻击128%的血量\", \"初始激活\", \"\", \"22991\", 0, 1, 1, {{20101}}, 0, 0, 2, 0}",
	[778301.0] = "{778301, \"起电·针刺\", \"尼治\", 77830, 778302, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {7783001}, {}, 0, \"尼治高速移动至敌方阵营释放【起电·针刺】对敌方全体造成168%法术伤害，附加自身攻击力的50%真实伤害，该技能命中目标必定附加【麻痹】（免疫状态除外）\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"778301\", 0, 1, 1, {{28101}}, 0, 0, 2, 0}",
