	[250202.0] = "{250202, \"凯鸟\", \"路奇\", 25020, 250203, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {}, {{'atk_per',200},{'crit_rate',100}}, 0, \"攻击力提升20%，暴击率提升10%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>8星</div>自动升级\", \"20220\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[542201.0] = "{542201, \"音音果实\", \"阿普\", 54220, 542202, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {}, {{'hp_max_per',150},{'atk_per',100},{'hit_magic',30}}, 0, \"阿普生命提升15%，攻击提升10%，控制率提高3%。\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"54220\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[542303.0] = "{542303, \"刮盘·爆\", \"阿普\", 54230, 542304, 3, 0, 4, \"active_skill\", 0, 0, 1, 1, {5423003,5423993}, {}, 0, \"阿普在敌方阵地炸开音波，对敌方全体造成91%的法术伤害，目标身上每存在一种负面效果，则额外增加4%的伤害，以及5%概率使目标陷入【音波共震】（每种负面状态单独计算概率）。对己方全体75%概率施加【音波协调】。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"54230\", 0, 1, 1, {{54231,54232}}, 0, 0, 0, 0}",
	[522304.0] = "{522304, \"甜甜箭\", \"汉库克\", 52230, 522305, 4, 0, 4, \"active_skill\", 0, 0, 1, 1, {5223003,5223013}, {}, 0, \"对敌人全体单位造成135%物理伤害，并有70%概率附加2回合的【甜甜印记】，且对我方2个生命值最低的单位回复汉库克攻击128%的血量\", \"初始激活\", \"\", \"22991\", 0, 1, 1, {{20101}}, 0, 0, 2, 0}",
	[544402.0] = "{544402, \"治愈迁跃\", \"光月时\", 54440, 544403, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5444002,5444102}, {}, 0, \"每回合结束时，光月时引动时空，将上一个回合中通过【时空法阵】迁跃的治疗效果平摊至友方全体目标，产生攻击力57%加上【时空法阵】中迁跃的治疗，同时75%驱散友方全体1个负面效果。此技能产生治疗不会被迁跃。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"54440\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[769404.0] = "{769404, \"森森果实\", \"绿牛\", 76940, 769405, 4, 0, 0, \"passive_skill\", 0, 0, 2, 1, {7694004,7694014,7694024}, {}, 0, \"森森果实能力者战斗开始对己方全体英雄增加【治疗提升】，对友方传奇阵容英雄增加【森森攻击】【森森防御】，对自身增加【自然之力】\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"769401\", 0, 1, 1, {{76936,76924,76944,76954}}, 0, 0, 0, 0}",
	[770402.0] = "{770402, \"露娜利亚族\", \"烬\", 77040, 770403, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7704002}, {}, 0, \"露娜利亚族拥有极高的速度，烬在战斗开始后为自身增加【露娜利亚族】【负面状态免疫】，烬的每次攻击都会叠加一层【露娜利亚族】，【露娜利亚族】叠加至5层释放【御守·火龙皇】释放技能后清空自身增益buff，并且为自身提供【最终形态】\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"770040\", 0, 1, 1, {{77002,77101,77102,19851}}, 0, 0, 0, 0}",
	[760402.0] = "{760402, \"supre\", \"弗兰奇(新世界)\", 76040, 760403, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7604002,7604012}, {}, 0, \"弗兰奇阵亡后以30%血量复活并且为自身增加【super】持续至战斗结束\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"760040\", 0, 0, 1, {{76031}}, 0, 0, 0, 0}",
	[525105.0] = "{525105, \"[觉醒]大喷火\", \"赤犬\", 52510, 0, 5, 0, 4, \"active_skill\", 0, 0, 5, 1, {5251003}, {}, 0, \"赤犬毁灭性一击，对敌方全体单位造成135%物理伤害，并有70%概率附加【破甲】状态，持续2回合\", \"初始激活\", \"\", \"23501\", 0, 0, 1, {{22104}}, 0, 0, 1, 0}",
	[552201.0] = "{552201, \"百兽凯多\", \"凯多(神龙)\", 55220, 552202, 1, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5522001}, {{'atk_per',150},{'hp_max_per',250},{'speed',10}}, 0, \"凯多生命提升25%，攻击提升15%，速度提升10，每回合开始，对敌方随机1名单位造成雷击使其陷入【眩晕】\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"55220\", 0, 1, 1, {{28201}}, 0, 0, 0, 0}",
	[558901.0] = "{558901, \"普通攻击\", \"圆月猫蝮蛇\", 55890, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {5589001}, {}, 0, \"对前方1个目标造成100%的物理伤害\", \"\", \"\", \"405181\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[515303.0] = "{515303, \"无上大快刀\", \"鹰眼\", 51530, 515304, 3, 0, 4, \"active_skill\", 0, 0, 1, 1, {5153501,5153003}, {}, 0, \"鹰眼释放所有怒气施展华丽而猛烈剑术，临时提升自身30%命中率后，对前方单体造成3次各150%物理伤害的斩击（共450%伤害），每3层【怒气】则额外增加1次斩击（最多2次，共5连击），额外斩击的最后一击会对目标以外随机2个单位造成相同系数的溅射伤害，怒气在行动结束后消失\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"22933\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[525104.0] = "{525104, \"大喷火\", \"赤犬\", 52510, 525105, 4, 0, 4, \"active_skill\", 0, 0, 5, 1, {5251003}, {}, 0, \"赤犬毁灭性一击，对敌方全体单位造成135%物理伤害，并有70%概率附加【破甲】状态，持续2回合\", \"初始激活\", \"\", \"23501\", 0, 0, 1, {{22104}}, 0, 0, 1, 0}",
	[773103.0] = "{773103, \"死·狮子歌歌\", \"索隆(鬼岛)\", 77310, 773104, 3, 0, 2, \"active_skill\", 0, 0, 1, 1, {7731003,7731013}, {}, 0, \"索隆使用一刀流·居合·死·狮子歌歌，对敌方全体发起攻击，对敌方造成268%物理伤害+索隆自身攻击力的70%真实伤害（敌方受到伤害最大不超过索隆自身攻击力的8倍），并且有70%概率使敌方进入流血状态。\", \"初始激活\", \"\", \"773101\", 0, 1, 1, {{77303}}, 0, 0, 1, 0}",
	[781103.0] = "{781103, \"熊之冲击\", \"熊(机械)\", 78110, 781104, 3, 0, 2, \"active_skill\", 0, 0, 1, 1, {7811003,7811101}, {}, 0, \"临时提升15%暴击率和20%命中，攻击敌方全体，造成320%法术伤害，附加自身攻击力的70%，自身生命值的20%真实伤害，(该伤害最大不超过自身攻击力的10倍)，70%概率附加【破甲】，持续2回合；\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>7星</div>自动升级\", \"781101\", 0, 1, 1, {{22102}}, 0, 0, 1, 0}",
	[541201.0] = "{541201, \"响彻天堂\", \"索隆(和之国)\", 54120, 541202, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5412001}, {{'hp_max_per',200},{'atk_per',100},{'dodge_rate',50},{'speed',10}}, 0, \"索隆为完成与古伊娜的约定而练就了无与伦比的意志，生命提升10%，攻击提升10%，闪避率提升5%，速度提升10。索隆受到伤害时最大不超过自身生命值的80%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"54120\", 0, 1, 1, {{54121}}, 0, 0, 0, 0}",
	[541203.0] = "{541203, \"响彻天堂\", \"索隆(和之国)\", 54120, 541204, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5412003}, {{'hp_max_per',400},{'atk_per',300},{'dodge_rate',150},{'speed',30}}, 0, \"索隆为完成与古伊娜的约定而练就了无与伦比的意志，生命提升40%，攻击提升35%，闪避率提升15%，速度提升30。索隆受到伤害时最大不超过自身生命值的60%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"54120\", 0, 1, 1, {{54123}}, 0, 0, 0, 0}",
	[525103.0] = "{525103, \"大喷火\", \"赤犬\", 52510, 525104, 3, 0, 4, \"active_skill\", 0, 0, 5, 1, {5251003}, {}, 0, \"赤犬毁灭性一击，对敌方全体单位造成135%物理伤害，并有70%概率附加【破甲】状态，持续2回合\", \"初始激活\", \"\", \"23501\", 0, 0, 1, {{22104}}, 0, 0, 1, 0}",
	[540404.0] = "{540404, \"镜山\", \"大和\", 54040, 540405, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5404006,5404104}, {}, 0, \"战斗开始时，大和为自己附加【镜山】，持续8回合，自身【镜山】延迟80%的伤害。同时为除自己外的随机1个友方单位附加【镜山】，持续2个回合，友方【镜山】延迟40%的伤害。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"54040\", 0, 1, 1, {{54049}}, 0, 0, 0, 0}",
	[515302.0] = "{515302, \"无上大快刀\", \"鹰眼\", 51530, 515303, 2, 0, 4, \"active_skill\", 0, 0, 1, 1, {5153501,5153002}, {}, 0, \"鹰眼释放所有怒气施展华丽而猛烈剑术，临时提升自身30%命中率后，对前方单体造成3次各125%物理伤害的斩击（共375%伤害），每3层【怒气】则额外增加1次斩击（最多2次，共5连击），额外斩击的最后一击会对目标以外随机2个单位造成相同系数的溅射伤害，怒气在行动结束后消失\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>9星</div>自动升级\", \"22933\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[541202.0] = "{541202, \"响彻天堂\", \"索隆(和之国)\", 54120, 541203, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5412002}, {{'hp_max_per',350},{'atk_per',200},{'dodge_rate',100},{'speed',20}}, 0, \"索隆为完成与古伊娜的约定而练就了无与伦比的意志，生命提升25%，攻击提升25%，闪避率提升10%，速度提升20。索隆受到伤害时最大不超过自身生命值的70%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>8星</div>自动升级\", \"54120\", 0, 1, 1, {{54122}}, 0, 0, 0, 0}",
	[525102.0] = "{525102, \"大喷火\", \"赤犬\", 52510, 525103, 2, 0, 4, \"active_skill\", 0, 0, 5, 1, {5251002}, {}, 0, \"赤犬毁灭性一击，对敌方随机4个单位造成110%物理伤害，并有50%概率附加【破甲】状态，持续2回合\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>7星</div>自动升级\", \"23501\", 0, 0, 1, {{22103}}, 0, 0, 1, 0}",
	[754405.0] = "{754405, \"[觉醒]女帝权柄\", \"汉库克(七武海)\", 75440, 0, 5, 0, 0, \"passive_skill\", 0, 0, 2, 1, {7544005}, {}, 0, \"汉库克攻击【魅惑】状态下的敌人，有50%概率附加【俘虏】战斗开始时,提升己方全体法师50%魔法伤害（(该效果不可驱散)，持续4回合\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"75440\", 0, 0, 1, {{75445}}, 0, 0, 0, 0}",
	[540205.0] = "{540205, \"[觉醒]犬犬果实\", \"大和\", 54020, 0, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5402003}, {{'hp_max_per',300},{'atk_per',400}}, 0, \"生命提升30%，攻击提升40%。在战斗开始时，友方除大和外所有草帽团暴击率提高9%。大和的所有攻击都有90%概率为自己添加一层【白蛇驱】。\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"54020\", 0, 1, 1, {{54061}}, 0, 0, 0, 0}",
	[224401.0] = "{224401, \"必杀·加把火\", \"乌索普\", 22440, 224402, 1, 0, 0, \"passive_skill\", 0, 0, 1, 1, {2244001}, {}, 0, \"对处于【出血】或【大出血】状态的单位伤害提升10%\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"22430\", 0, 1, 1, {{21001}}, 0, 0, 0, 0}",
	[525101.0] = "{525101, \"大喷火\", \"赤犬\", 52510, 525102, 1, 0, 4, \"active_skill\", 0, 0, 5, 1, {5251001}, {}, 0, \"赤犬毁灭性一击，对敌方随机4个单位造成90%物理伤害，并有30%概率附加【破甲】状态，持续2回合\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"23501\", 0, 0, 1, {{22102}}, 0, 0, 1, 0}",
	[515305.0] = "{515305, \"[觉醒]无上大快刀\", \"鹰眼\", 51530, 0, 5, 0, 4, \"active_skill\", 0, 0, 1, 1, {5153501,5153003}, {}, 0, \"鹰眼释放所有怒气施展华丽而猛烈剑术，临时提升自身30%命中率后，对前方单体造成3次各150%物理伤害的斩击（共450%伤害），每3层【怒气】则额外增加1次斩击（最多2次，共5连击），额外斩击的最后一击会对目标以外随机2个单位造成相同系数的溅射伤害，怒气在行动结束后消失\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"22933\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[779303.0] = "{779303, \"威慑射击\", \"贝克曼\", 77930, 779304, 3, 0, 4, \"active_skill\", 0, 0, 1, 1, {7793003,7793013}, {}, 0, \"贝克曼用燧发式来福枪威胁敌人，令其不敢动弹!对前方一列目标造成302%法术伤害;附加自身攻击力70%，自身生命值70%的真实伤害，为所有命中目标附加【攻击降低】与【防御降低】(该伤害最大不超过自身攻击力的8倍)\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"779301\", 0, 1, 1, {{78403,78413}}, 0, 0, 2, 0}",
	[775304.0] = "{775304, \"雷鸣八卦\", \"大和\", 77530, 775305, 4, 0, 4, \"active_skill\", 0, 0, 1, 1, {7753004,7753014,7753024,7753034}, {}, 0, \"大和学习凯多终极招式雷鸣八卦，对敌方全体英雄造成428%物理伤害加自身生命值60%的真实伤害(该伤害最大不超过自身攻击力的8倍)并且必定【眩晕】敌方一名单位，此攻击命中【冰冻,镣铐】状态下的敌人伤害增加80%，使受击者进入【破防】状态\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"775301\", 0, 1, 1, {{22104,28201}}, 0, 0, 2, 0}",
	[781503.0] = "{781503, \"法术增伤\", \"熊(机械)\", 78150, 781504, 3, 0, 0, \"passive_skill\", 0, 0, 1, 1, {7815003}, {}, 0, \"对忍术职业伤害提升30%；回合开始时，100%概率获得获得1层【肉球果实】；队友死亡时，自身获得1层【肉球果实】，持续4回合。\", \"\", \"\", \"781401\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[545205.0] = "{545205, \"[觉醒]手术果实觉醒\", \"罗(和之国)\", 54520, 0, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5452005,5452105}, {{'hp_max_per',600},{'atk_per',550}}, 0, \"罗在果实觉醒后，生命提升60%，攻击提升55%。每回合开始时，会释放一次寂静领域，85%概率为敌方2个单位附加【寂静领域】，持续1回合\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"54520\", 0, 1, 1, {{54521}}, 0, 0, 0, 0}",
	[760205.0] = "{760205, \"[觉醒]弗兰奇弗兰奇\", \"弗兰奇(新世界)\", 76020, 760206, 5, 0, 0, \"passive_skill\", 0, 0, 2, 1, {7602005,7602015}, {{'atk_per',600},{'hp_max_per',600},{'crit_rate',300}}, 0, \"攻击力提升60%，生命值提升60%，暴击率提升30%，击杀敌方单位给友方单位增加【火上浇油】，随机眩晕敌方一名单位\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：忍者到达<div fontcolor=45a536>12星</div>自动升级\", \"760020\", 0, 0, 1, {{28201,76044}}, 0, 0, 0, 0}",
	[539001.0] = "{539001, \"普通攻击\", \"光月御田\", 53900, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {5390001}, {}, 0, \"对前方单体造成100%物理伤害\", \"\", \"\", \"20000\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[775303.0] = "{775303, \"雷鸣八卦\", \"大和\", 77530, 775304, 3, 0, 4, \"active_skill\", 0, 0, 1, 1, {7753003,7753013,7753023,7753033}, {}, 0, \"大和学习凯多终极招式雷鸣八卦，对敌方全体英雄造成348%物理伤害加自身生命值50%的真实伤害(该伤害最大不超过自身攻击力的7倍)并且必定【眩晕】敌方一名单位，此攻击命中【冰冻,镣铐】状态下的敌人伤害增加70%，使受击者进入【破防】状态\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"775301\", 0, 1, 1, {{22103,28201}}, 0, 0, 2, 0}",
	[515304.0] = "{515304, \"无上大快刀\", \"鹰眼\", 51530, 515305, 4, 0, 4, \"active_skill\", 0, 0, 1, 1, {5153501,5153003}, {}, 0, \"鹰眼释放所有怒气施展华丽而猛烈剑术，临时提升自身30%命中率后，对前方单体造成3次各150%物理伤害的斩击（共450%伤害），每3层【怒气】则额外增加1次斩击（最多2次，共5连击），额外斩击的最后一击会对目标以外随机2个单位造成相同系数的溅射伤害，怒气在行动结束后消失\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"22933\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[552205.0] = "{552205, \"[觉醒]百兽凯多\", \"凯多(神龙)\", 55220, 0, 5, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5522005}, {{'atk_per',650},{'hp_max_per',750},{'speed',60}}, 0, \"凯多生命提升75%，攻击提升65%，速度提升60，每回合开始，对敌方随机3名单位造成雷击使其陷入【眩晕】\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"55220\", 0, 1, 1, {{28201}}, 0, 0, 0, 0}",
	[539601.0] = "{539601, \"被动-加天羽\", \"光月御田\", 53960, 0, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5396001}, {}, 0, \"御田受到伤害时，自身获得一层【天羽羽斩】。\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"53920\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[539305.0] = "{539305, \"[觉醒]桃源十拳\", \"光月御田\", 53930, 0, 5, 0, 4, \"active_skill\", 0, \"max_hp_per\", 1, 1, {5393003,5398003,5398999}, {}, 0, \"光月御田的成名绝技，在半空中蓄力，攻击敌方生命值最高的单体，消耗自身25%的最大生命值，造成所消耗生命值数值*1.5倍的物理伤害(此伤害数值不被物连减免)，50%概率附带【破甲】和【出血】效果。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"53930\", 0, 1, 1, {{24100,21011}}, 0, 0, 2, 0}",
	[773401.0] = "{773401, \"阿修罗拔剑·亡者戏\", \"索隆(鬼岛)\", 77340, 773402, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7734001,7734011,7734021}, {}, 0, \"索隆终极招式血量低至20%触发【阿修罗拔剑·亡者戏】恢复自身已损失生命值，【死·狮子歌歌】强化为【千八百烦恼风】，(该效果每次战斗仅触发一次)\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"773401\", 0, 1, 1, {{77406,77401}}, 0, 0, 0, 0}",
	[224402.0] = "{224402, \"必杀·加把火\", \"乌索普\", 22440, 224403, 2, 0, 0, \"passive_skill\", 0, 0, 1, 1, {2244002}, {}, 0, \"对处于【出血】或【大出血】状态下的单位伤害提升15%\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"22430\", 0, 1, 1, {{21001}}, 0, 0, 0, 0}",
	[775305.0] = "{775305, \"[觉醒]雷鸣八卦\", \"大和\", 77530, 0, 5, 0, 4, \"active_skill\", 0, 0, 1, 1, {7753005,7753015,7753025,7753035}, {}, 0, \"大和学习凯多终极招式雷鸣八卦，对敌方全体英雄造成518%物理伤害加自身生命值80%的真实伤害(该伤害最大不超过自身攻击力的10倍)并且必定【眩晕】敌方2名单位，此攻击命中【冰冻,镣铐】状态下的敌人伤害增加100%，使受击者进入【破防】状态\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"775301\", 0, 1, 1, {{22105,28201}}, 0, 0, 2, 0}",
	[539301.0] = "{539301, \"桃源十拳\", \"光月御田\", 53930, 539302, 1, 0, 4, \"active_skill\", 0, \"max_hp_per\", 1, 1, {5393001,5398001,5398999}, {}, 0, \"光月御田的成名绝技，在半空中蓄力，攻击敌方生命值最高的单体，消耗自身15%的最大生命值，造成所消耗生命值数值*1.5倍的物理伤害(此伤害数值不被物连减免)，30%概率附带【破甲】和【出血】效果。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"53930\", 0, 1, 1, {{24100,21011}}, 0, 0, 2, 0}",
	[257901.0] = "{257901, \"普通攻击\", \"卡莉法\", 25790, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {2579001}, {}, 0, \"对前方单体造成100%魔法伤害\", \"\", \"\", \"20000\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[548001.0] = "{548001, \"普通攻击\", \"杰克\", 54800, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {5480001}, {}, 0, \"对前方单体造成100%物理伤害\", \"\", \"\", \"20000\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[763301.0] = "{763301, \"魂丧剑·直刺\", \"布鲁克(新世界)\", 76330, 763302, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {7633001,7633011,7633021,7633031}, {}, 0, \"布鲁克释放技能【鼻歌·吹雪斩】对敌方全体造成268%的魔法伤害，造成伤害时，如果敌方攻击小于布鲁克，将临时提升30%暴击几率，如果敌方速度小于布鲁克，将临时提升30%暴击伤害，如果敌方生命小于布鲁克，将临时提升30%伤害，如果敌方防御小于布鲁克，将临时提升30%无视防御\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"763030\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[553201.0] = "{553201, \"最高指挥\", \"佛之战国\", 55320, 553202, 1, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5532001}, {{'atk_per',150},{'hp_max_per',250},{'def_per',200}}, 0, \"佛之战国生命提升25%，攻击提升15%，防御提升20%，每回合开始，给所有友军添加【正义】效果\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"24160\", 0, 1, 1, {{59000}}, 0, 0, 0, 0}",
	[774304.0] = "{774304, \"袷羽槛\", \"日奈\", 77430, 774305, 4, 0, 4, \"active_skill\", 0, 0, 1, 1, {7743004,7743014}, {}, 0, \"日奈对敌方施展槛槛果实觉醒能力，对敌方全体造成438%法术伤害，敌方单位每存在一层增益buff，日奈本次伤害提升40%，本次攻击必定附加【镣铐】，对【镣铐】状态下的敌人附加【海楼石枷锁】\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"774301\", 0, 1, 1, {{77501,77502}}, 0, 0, 2, 0}",
	[545201.0] = "{545201, \"手术果实觉醒\", \"罗(和之国)\", 54520, 545202, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5452001,5452101}, {{'hp_max_per',100},{'atk_per',100}}, 0, \"罗在果实觉醒后，生命提升10%，攻击提升10%。每回合开始时，会释放一次寂静领域，33%概率为敌方1个单位附加【寂静领域】，持续1回合\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"54520\", 0, 1, 1, {{54521}}, 0, 0, 0, 0}",
	[250203.0] = "{250203, \"凯鸟\", \"路奇\", 25020, 0, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {}, {{'atk_per',300},{'crit_rate',150}}, 0, \"攻击力提升30%，暴击率提升15%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"20220\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[512401.0] = "{512401, \"燃烧月步\", \"山治\", 51240, 512402, 1, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5124021}, {}, 0, \"山治的攻击对处于【出血】或【大出血】状态下的单位暴击率提升10%，并且强化【恶魔飞踢】效果：对辅助职业的目标伤害提高10%，并有30%概率对辅助职业目标附加持续2回合的【沉默】效果\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"21340\", 0, 1, 1, {{24502}}, 0, 0, 0, 0}",
	[538402.0] = "{538402, \"芸者·浮世绘\", \"桃兔\", 53840, 538403, 2, 0, 0, \"passive_skill\", 0, 0, 3, 1, {5384002}, {}, 0, \"桃兔在场时，每回合结束，随机复活一名队友会以10%的生命值复活，如果没有队友死亡则随机一名队友伤害提高20%，伤害提升效果持续2回合\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"53840\", 0, 1, 1, {{538452}}, 0, 0, 0, 0}",
	[229101.0] = "{229101, \"镇魂神曲\", \"Mr.3（弃用）\", 22910, 0, 1, 0, 4, \"active_skill\", 0, 0, 2, 1, {2291001}, {}, 0, \"提升随机3个己方单位15%攻击力和10%暴击率，持续2回合\", \"初始激活\", \"\", \"22910\", 0, 1, 1, {}, 0, 1, 0, 0}",
	[539303.0] = "{539303, \"桃源十拳\", \"光月御田\", 53930, 539304, 3, 0, 4, \"active_skill\", 0, \"max_hp_per\", 1, 1, {5393003,5398003,5398999}, {}, 0, \"光月御田的成名绝技，在半空中蓄力，攻击敌方生命值最高的单体，消耗自身25%的最大生命值，造成所消耗生命值数值*1.5倍的物理伤害(此伤害数值不被物连减免)，50%概率附带【破甲】和【出血】效果。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"53930\", 0, 1, 1, {{24100,21011}}, 0, 0, 2, 0}",
	[891413.0] = "{891413, \"冰冻时刻（吸血效果）\", \"库赞\", 89143, 0, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {8914013}, {}, 0, \"在战斗开始时，将给所有友方添加【冻冻果实】效果，为友方提升20%吸血效果，20%攻击提升，15%暴击几率，持续2回合且不可驱散\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"504023\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[545203.0] = "{545203, \"手术果实觉醒\", \"罗(和之国)\", 54520, 545204, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5452003,5452103}, {{'hp_max_per',400},{'atk_per',350}}, 0, \"罗在果实觉醒后，生命提升40%，攻击提升35%。每回合开始时，会释放一次寂静领域，75%概率为敌方2个单位附加【寂静领域】，持续1回合\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>15星</div>自动升级\", \"54520\", 0, 1, 1, {{54521}}, 0, 0, 0, 0}",
	[224403.0] = "{224403, \"必杀·加把火\", \"乌索普\", 22440, 224404, 3, 0, 0, \"passive_skill\", 0, 0, 1, 1, {2244003}, {}, 0, \"对处于【出血】或【大出血】状态下的单位伤害提升20%，【普通攻击】优先攻击处于【出血】或【大出血】状态的单位\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"22430\", 0, 1, 1, {{21001}}, 0, 0, 0, 0}",
	[153151.0] = "{153151, \"格里芬\", \"香克斯\", 15315, 153152, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {1531501}, {}, 0, \"香克斯挥舞格里芬，对敌方前两排单位造成170%物理伤害\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"15340\", 0, 1, 1, {}, 0, 1, 1, 0}",
	[776302.0] = "{776302, \"威国&霸海\", \"夏洛特玲玲\", 77630, 776303, 2, 0, 4, \"active_skill\", 0, 0, 1, 1, {7763002,7763012,7763022}, {}, 0, \"四皇夏洛特·玲玲与凯多合体招式【威国&霸海】对敌方全体造成238%法术伤害附加自身最大生命值的60%自身攻击力的60%真实伤害，并且有30%的概率使受击着触发【灵魂消散】，该技能成功击杀目标触发技能【灵魂果实】\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>9星</div>自动升级\", \"776301\", 0, 1, 1, {{77701}}, 0, 0, 2, 0}",
	[545202.0] = "{545202, \"手术果实觉醒\", \"罗(和之国)\", 54520, 545203, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5452002,5452102}, {{'hp_max_per',250},{'atk_per',250}}, 0, \"罗在果实觉醒后，生命提升25%，攻击提升25%。每回合开始时，会释放一次寂静领域，50%概率为敌方1个单位附加【寂静领域】，持续1回合\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"54520\", 0, 1, 1, {{54521}}, 0, 0, 0, 0}",
	[767305.0] = "{767305, \"[觉醒]糖果潮汐\", \"佩罗斯佩罗\", 76730, 0, 5, 0, 4, \"active_skill\", 0, 0, 1, 1, {7673005}, {}, 0, \"召唤糖果潮汐随机使用攻击或者祝福技能：如果发动攻击，它将对敌方全体造成365%的法术伤害，并附加【攻击降低】【命中降低】【受疗降低】【中毒】效果；如果发动祝福，将恢复友方全体基于佩罗斯佩罗最大生命值的50%，并附加【攻击提升】【受疗提升】【命中提升】效果\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"206101\", 0, 1, 1, {{23512,61855,20701,21502,10203,11205,31142}}, 0, 0, 2, 0}",
	[544205.0] = "{544205, \"[觉醒]时时果实\", \"光月时\", 54420, 0, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5442005,5442105,5442205}, {{'hp_max_per',550},{'atk_per',500}}, 0, \"光月时生命提升55%，攻击提升50%；光月时在场时，会在战场上保留一个【时空法阵】，【时空法阵】生效时，友方全体将会被附带上【治愈迁跃】，敌方全体将会被附带上【伤害迁跃】。\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"54420\", 0, 1, 1, {{54421,54451,54454}}, 0, 0, 0, 0}",
	[776301.0] = "{776301, \"威国&霸海\", \"夏洛特玲玲\", 77630, 776302, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {7763001,7763011,7763021}, {}, 0, \"四皇夏洛特·玲玲与凯多合体招式【威国&霸海】对敌方全体造成198%法术伤害附加自身最大生命值的50%自身攻击力的50%真实伤害，并且有20%的概率使受击着触发【灵魂消散】，该技能成功击杀目标触发技能【灵魂果实】\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"776301\", 0, 1, 1, {{77701}}, 0, 0, 2, 0}",
	[538001.0] = "{538001, \"普通攻击\", \"桃兔\", 53800, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {5380001}, {}, 0, \"对前方单体造成100%物理伤害\", \"\", \"\", \"20000\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[764312.0] = "{764312, \"大炎戒·炎帝\", \"艾斯(龙年)\", 76431, 764313, 2, 0, 2, \"active_skill\", 0, 0, 1, 1, {7643102,7643112,7643122}, {}, 0, \"普通状态下与【火拳】效果一致，进入炎帝状态下升级为【大炎戒·炎帝】对敌方全体单位造成180%物理伤害加自身攻击力的90%伤害，该伤害无视防御，并且有30%概率对敌方单位附加【神火·不知火】，对灼烧状态下的敌人增加20%伤害，击杀敌方单位再次施法(每回合最多触发一次)\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>9星</div>自动升级\", \"764030\", 0, 1, 1, {{76442}}, 0, 0, 2, 0}",
	[544204.0] = "{544204, \"时时果实\", \"光月时\", 54420, 544205, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5442004,5442104,5442204}, {{'hp_max_per',450},{'atk_per',400}}, 0, \"光月时生命提升45%，攻击提升40%；光月时在场时，会在战场上保留一个【时空法阵】，【时空法阵】生效时，友方全体将会被附带上【治愈迁跃】，敌方全体将会被附带上【伤害迁跃】。\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"54420\", 0, 1, 1, {{54421,54451,54454}}, 0, 0, 0, 0}",
	[553205.0] = "{553205, \"[觉醒]最高指挥\", \"佛之战国\", 55320, 0, 5, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5532005}, {{'atk_per',650},{'hp_max_per',750},{'def_per',600}}, 0, \"佛之战国生命提升75%，攻击提升65%，防御提升60%，每回合开始，给所有友军添加【正义】效果\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"24160\", 0, 1, 1, {{59004}}, 0, 0, 0, 0}",
	[217201.0] = "{217201, \"好天气\", \"Mr.情人节\", 21720, 0, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {}, {{'hp_max_per',100},{'atk_per',50}}, 0, \"生命提升10%，攻击提升5%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"41392\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[768302.0] = "{768302, \"电磁碎击\", \"伽治\", 76830, 768303, 2, 0, 4, \"active_skill\", 0, 0, 1, 1, {7683002}, {}, 0, \"伽治跃起使用长矛对敌方全体发动【电磁碎击】，对敌方全体造成180%的物理伤害附加自身最大生命值60%的伤害，并且有30%概率对敌方附加【麻痹】(该技能最大伤害不能超过自己攻击力的十倍)\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>9星</div>自动升级\", \"768301\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[558103.0] = "{558103, \"圆月·闪电突袭\", \"圆月猫蝮蛇\", 55810, 558104, 3, 0, 2, \"active_skill\", 0, 0, 1, 1, {5581003}, {}, 0, \"圆月猫蝮蛇对敌方单体进行3-5次突袭，第一段突袭造成60%伤害附加10%无视防御，第二段突袭造成90%伤害附加15%无视防御，第三段突袭造成135%伤害附加20%无视防御，有30%几率触发第四段突袭，第四段突袭造成202%伤害附加25%无视防御，有20%几率触发第五段突袭，第五段突袭造成303%伤害附加30%无视防御，每段突袭必定造成目标【感电】\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>15星</div>自动升级\", \"55810\", 0, 1, 1, {{63000}}, 0, 0, 1, 0}",
	[776303.0] = "{776303, \"威国&霸海\", \"夏洛特玲玲\", 77630, 776304, 3, 0, 4, \"active_skill\", 0, 0, 1, 1, {7763003,7763013,7763023}, {}, 0, \"四皇夏洛特·玲玲与凯多合体招式【威国&霸海】对敌方全体造成318%法术伤害附加自身最大生命值的70%自身攻击力的70%真实伤害，并且有40%的概率使受击着触发【灵魂消散】，该技能成功击杀目标触发技能【灵魂果实】\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"776301\", 0, 1, 1, {{77701}}, 0, 0, 2, 0}",
	[224404.0] = "{224404, \"必杀·加把火\", \"乌索普\", 22440, 224405, 4, 0, 0, \"passive_skill\", 0, 0, 1, 1, {2244003}, {}, 0, \"对处于【出血】或【大出血】状态下的单位伤害提升20%，【普通攻击】优先攻击处于【出血】或【大出血】状态的单位\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"22430\", 0, 1, 1, {{21001}}, 0, 0, 0, 0}",
	[554203.0] = "{554203, \"飘飘果实\", \"金狮子·史基\", 55420, 554204, 3, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5542003,5542013}, {{'atk_per',500},{'hp_max_per',300},{'dodge_magic',100}}, 0, \"攻击提升50%，生命值提升30%，抗控提升10%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"70720\", 0, 1, 0, {}, 0, 0, 0, 0}",
	[558102.0] = "{558102, \"圆月·闪电突袭\", \"圆月猫蝮蛇\", 55810, 558103, 2, 0, 2, \"active_skill\", 0, 0, 1, 1, {5581002}, {}, 0, \"圆月猫蝮蛇对敌方单体进行3-5次突袭，第一段突袭造成50%伤害附加10%无视防御，第二段突袭造成75%伤害附加15%无视防御，第三段突袭造成112%伤害附加20%无视防御，有25%几率触发第四段突袭，第四段突袭造成168%伤害附加25%无视防御，有15%几率触发第五段突袭，第五段突袭造成253%伤害附加30%无视防御，每段突袭必定造成目标【感电】\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>7星</div>自动升级\", \"55810\", 0, 1, 1, {{63000}}, 0, 0, 1, 0}",
	[203301.0] = "{203301, \"沙岚\", \"鳄鱼\", 20330, 203302, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {2033001,2033011}, {}, 0, \"攻守合一，对前排单体造成189%物理伤害，同时增加自身7%免伤，持续2回合\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"41493\", 0, 1, 1, {}, 0, 1, 2, 0}",
	[536405.0] = "{536405, \"思食症\", \"BIG·MOM\", 53650, 536406, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5364005,5364105,5364018}, {}, 0, \"混乱……开始了！当BIG·MOM的生命值降低至60%以下时，BIG·MOM会因为想要吃到美食而开始发狂，发出一声巨大的咆哮，使除自己外的全体目标陷入【恐惧震慑】状态，持续2回合，此后4个回合，BIG·MOM将【暴走】，且每回合为自己附加一层摄魂印记。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"53640\", 0, 0, 1, {{53644,53648,53699}}, 0, 0, 0, 0}",
	[775302.0] = "{775302, \"雷鸣八卦\", \"大和\", 77530, 775303, 2, 0, 4, \"active_skill\", 0, 0, 1, 1, {7753002,7753012,7753022,7753032}, {}, 0, \"大和学习凯多终极招式雷鸣八卦，对敌方全体英雄造成288%物理伤害加自身生命值40%的真实伤害(该伤害最大不超过自身攻击力的6倍)并且必定【眩晕】敌方一名单位，此攻击命中【冰冻,镣铐】状态下的敌人伤害增加60%，使受击者进入【破防】状态\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>9星</div>自动升级\", \"775301\", 0, 1, 1, {{22102,28201}}, 0, 0, 2, 0}",
	[558101.0] = "{558101, \"圆月·闪电突袭\", \"圆月猫蝮蛇\", 55810, 558102, 1, 0, 2, \"active_skill\", 0, 0, 1, 1, {5581001}, {}, 0, \"圆月猫蝮蛇对敌方单体进行3-5次突袭，第一段突袭造成40%伤害附加10%无视防御，第二段突袭造成60%伤害附加15%无视防御，第三段突袭造成90%伤害附加20%无视防御，有20%几率触发第四段突袭，第四段突袭造成135%伤害附加25%无视防御，有10%几率触发第五段突袭，第五段突袭造成202伤害附加30%无视防御，每段突袭必定造成目标【感电】\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"55810\", 0, 1, 1, {{63000}}, 0, 0, 1, 0}",
	[544201.0] = "{544201, \"时时果实\", \"光月时\", 54420, 544202, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5442001,5442101,5442201}, {{'hp_max_per',150},{'atk_per',100}}, 0, \"光月时生命提升15%，攻击提升10%；光月时在场时，会在战场上保留一个【时空法阵】，【时空法阵】生效时，友方全体将会被附带上【治愈迁跃】，敌方全体将会被附带上【伤害迁跃】。\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"54420\", 0, 1, 1, {{54421,54451,54454}}, 0, 0, 0, 0}",
	[536313.0] = "{536313, \"暴走威国\", \"BIG·MOM\", 53633, 536314, 6, 0, 0, \"active_skill\", 0, 0, 5, 1, {5363013,5363014}, {}, 0, \"BIG·MOM站在战场中间，对敌方全体发动不稳定的凶残的斩击，造成1%-332%的法术伤害，若目标生命值低于25%，则直接斩杀。击杀目标为自身添加一层【摄魂印记】。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"53630\", 0, 0, 1, {{53611}}, 0, 0, 0, 0}",
	[758402.0] = "{758402, \"最强剑豪\", \"鹰眼(七武海)\", 75840, 758403, 2, 0, 0, \"passive_skill\", 0, 0, 1, 1, {7584001,7584011,7584021,7585001}, {}, 0, \"鹰眼(七武海)血量达到一定百分比时受到伤害，将释放他的霸气以消除自身所有的控制效果，并根据他的生命百分比执行以下操作；≤70%：为所有友方恢复鹰眼(七武海)100%攻击力的生命值，并附加【强化】效果；≤50%：对所有敌人造成等同于鹰眼(七武海)生命值上限8%+自身攻击力150%的伤害(每个效果释放后冷却2回合)\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"75840\", 0, 0, 1, {{61221,61231,61201}}, 0, 0, 0, 0}",
	[533102.0] = "{533102, \"无双年糕刃弹\", \"卡塔库栗\", 53310, 533103, 2, 0, 4, \"active_skill\", 0, 0, 1, 1, {5331002,5331802}, {}, 0, \"卡塔库栗用武装色霸气将年糕包裹如雨般攻击敌方全体，造成128%的物理伤害且有80%概率将在命中目标身上添加一层等同自身攻击力40%的【年糕附着】效果，如目标血量高于60%，则额外50%概率再添加一层【年糕附着】\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>7星</div>自动升级\", \"53310\", 0, 0, 1, {{53302}}, 0, 0, 1, 0}",
	[778203.0] = "{778203, \"火花蓝·隐身\", \"尼治\", 77820, 778204, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7782003}, {{'hp_max_per',400},{'atk_per',300},{'speed',30},{'crit_rate',150}}, 0, \"生命提升50%，攻击力提升30%，速度提升30，暴击率提升15%，尼治使用技能后进入隐身状态\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"778201\", 0, 1, 1, {{77903}}, 0, 0, 0, 0}",
	[705402.0] = "{705402, \"五老星·科学武神\", \"萨坦圣\", 70540, 705403, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7054012,7054022,7054032}, {}, 0, \"回合开始对友方全体增加【土星降临】，对敌方血量最高的目标附加【土星标记】，自身首次死亡立即复活并且恢复60%生命值，获得【土星暴走】，持续至战斗结束\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"70540\", 0, 0, 1, {{70532,70542,70551}}, 0, 0, 0, 0}",
	[775011.0] = "{775011, \"普通攻击\", \"大和\", 77501, 775012, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {7750011}, {}, 0, \"对前方单体造成100%物理伤害\", \"\", \"\", \"20000\", 0, 1, 1, {}, 0, 0, 0, 0}",
