	[505405.0] = "{505405, \"[觉醒]炎戒\", \"艾斯（魂）\", 50540, 0, 5, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5054003}, {}, 0, \"战斗开始时，降低敌方全体20%攻击力（该效果不可被驱散），持续2回合\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"61294\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[558104.0] = "{558104, \"圆月·闪电突袭\", \"圆月猫蝮蛇\", 55810, 558105, 4, 0, 2, \"active_skill\", 0, 0, 1, 1, {5581004}, {}, 0, \"圆月猫蝮蛇对敌方单体进行3-5次突袭，第一段突袭造成80%伤害附加10%无视防御，第二段突袭造成120%伤害附加15%无视防御，第三段突袭造成180%伤害附加20%无视防御，有30%几率触发第四段突袭，第四段突袭造成270%伤害附加25%无视防御，有30%几率触发第五段突袭，第五段突袭造成405%伤害附加30%无视防御，每段突袭必定造成目标【感电】\", \"初始激活\", \"\", \"55810\", 0, 1, 1, {{63000}}, 0, 0, 1, 0}",
	[758405.0] = "{758405, \"[觉醒]最强剑豪\", \"鹰眼(七武海)\", 75840, 0, 5, 0, 0, \"passive_skill\", 0, 0, 1, 1, {7584001,7584011,7584021,7585001,7585102,7585204,7585205}, {}, 0, \"鹰眼(七武海)血量达到一定百分比时受到伤害，将释放他的霸气以消除自身所有的控制效果，并根据他的生命百分比执行以下操作；≤70%：为所有友方恢复鹰眼(七武海)100%攻击力的生命值，并附加【强化】效果；≤50%：对所有敌人造成等同于鹰眼(七武海)生命值上限8%+自身攻击力150%的伤害，并附加【震慑效果】，同时对其中1个敌人附加【眩晕】效果；≤30%：使自己获得【灵光一现】效果。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：忍者到达<div fontcolor=45a536>12星</div>自动升级\", \"75840\", 0, 0, 1, {{61221,61231,61201,61241}}, 0, 0, 0, 0}",
	[555303.0] = "{555303, \"地狱旅\", \"藤虎(三大将)\", 55530, 555304, 3, 0, 4, \"active_skill\", 0, 0, 2, 1, {5553013,5553023,5553033}, {}, 0, \"造成1000%的总伤害，由敌方所有单位共同承受，敌方存活英雄越少，每个单位所受伤害越高，每个单位所受伤害不得超过藤虎攻击力的4倍；同时有50%概率附加【致盲】，持续2回合；且各有50%概率驱散目标身上所有增益效果\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"55530\", 0, 1, 1, {{25001}}, 0, 0, 2, 0}",
	[777304.0] = "{777304, \"橡胶·象枪\", \"路飞(和之国)\", 77730, 777305, 4, 0, 4, \"active_skill\", 0, 0, 1, 1, {7773004,7773014,7770111,7773024}, {}, 0, \"路飞使用【橡胶·象枪】对敌方发起攻击，对敌方全体单位造成408%物理伤害附加自身攻击力的80%，自身生命值的80%真实伤害，对灼烧状态下的单位额外增加80%的伤害，且必定暴击，击杀目标再次释放（每回合仅触发一次）\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"777301\", 0, 1, 1, {{76013}}, 0, 0, 2, 0}",
	[758412.0] = "{758412, \"灵光一现\", \"鹰眼(七武海)\", 75842, 0, 1, 0, 0, \"passive_skill\", 0, 0, 1, 1, {7584201}, {}, 0, \"\", \"\", \"\", \"\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[535204.0] = "{535204, \"海军导师\", \"泽法\", 53520, 535205, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5352003}, {{'hp_max_per',350},{'atk_per',300}}, 0, \"生命提升35%，攻击提升30%。战斗开始时，友方全体海军提升6%的攻击力，此效果不可驱散，持续到战斗结束。\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"53520\", 0, 1, 1, {{53523}}, 0, 0, 0, 0}",
	[547104.0] = "{547104, \"业火手枪\", \"路飞(四挡)\", 54710, 547105, 4, 0, 2, \"active_skill\", 0, 0, 1, 1, {5471004}, {}, 0, \"橡胶象枪与橡胶火拳铳的融合，并将高级武装色霸气注入到了手枪里，对敌方全体造成185%物理伤害并有70%概率附加一层橡胶粘液\", \"初始激活\", \"\", \"70310\", 0, 1, 1, {{57011}}, 0, 0, 1, 0}",
