	[778404.0] = "{778404, \"高速移动\", \"尼治\", 77840, 778405, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7784004}, {}, 0, \"尼治普通攻击附加【感电效果】敌方所有目标使用技能尼治获得一层【高速移动】，【高速移动】叠加至3层尼治释放【起电针刺】，释放【起电针刺】后冷却1回合\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"778401\", 0, 1, 1, {{77914}}, 0, 0, 0, 0}",
