	[543203.0] = "{543203, \"大将候补\", \"茶豚\", 54320, 543204, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5432003}, {{'hp_max_per',450},{'atk_per',300}}, 0, \"茶豚生命提升45%，攻击提升30%；战斗开始时，茶豚获得【痛觉延迟】。\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"54320\", 0, 1, 1, {{54315}}, 0, 0, 0, 0}",
	[764303.0] = "{764303, \"大炎戒·炎帝\", \"艾斯(龙年)\", 76430, 764304, 3, 0, 2, \"active_skill\", 0, 0, 1, 1, {7643003,7643013}, {}, 0, \"普通状态下与【火拳】效果一致，进入炎帝状态下升级为【大炎戒·炎帝】对敌方全体单位造成220%物理伤害加自身攻击力的120%伤害，该伤害无视防御，并且有20%概率对敌方单位附加【神火·不知火】，对灼烧状态下的敌人增加30%伤害，击杀敌方单位再次施法(每回合最多触发一次)\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"764030\", 0, 1, 1, {{76443}}, 0, 0, 2, 0}",
	[775202.0] = "{775202, \"白蛇驱\", \"大和\", 77520, 775203, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7754022}, {{'hp_max_per',350},{'atk_per',200},{'speed',20},{'crit_rate',100}}, 0, \"生命提升35%，攻击力提升20%，速度提升20，暴击率提升10%，强化大和普通攻击，普工攻击造成150%加自身生命值10%的真实伤害(该伤害最大不超过自身攻击力的6倍)战斗开始为自身增加【鬼姬】\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>8星</div>自动升级\", \"775201\", 0, 1, 1, {{77611}}, 0, 0, 0, 0}",
