	[783202.0] = "{783202, \"基因改造\", \"山治(鬼岛)\", 78320, 783203, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7832002,7832012,7832022}, {{'hp_max_per',350},{'atk_per',200},{'speed',20},{'res',100}}, 0, \"攻击提升20%，生命提升35%，免伤提升10%，速度提升20；生命值低于50%以下，驱散自身负面状态与控制效果，增加自身15%免伤效果恢复20%生命值并且获得【基因改造】(触发后冷却4回合)\", \"激活条件：忍者到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：忍者到达<div fontcolor=45a536>8星</div>自动升级\", \"783201\", 0, 0, 1, {{78302,78312,78327}}, 0, 0, 0, 0}",
