	[535105.0] = "{535105, \"[觉醒]灭世计划\", \"泽法\", 53510, 0, 5, 0, 0, \"active_skill\", 0, 0, 5, 1, {5351003}, {}, 0, \"泽法秘密进行自己的灭世计划，第一步是弱化敌方，强化自身。吸取敌方全体12%的攻击力附加到自己身上，此效果每4个回合的前3回合均会释放\", \"初始激活\", \"\", \"53510\", 0, 0, 1, {{53515}}, 0, 0, 1, 0}",
	[760406.0] = "{760406, \"[觉醒]supre\", \"弗兰奇(新世界)\", 76040, 0, 6, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7604005,7604015}, {}, 0, \"弗兰奇阵亡后以100%血量复活并且为自身增加【super】持续至战斗结束\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：忍者到达<div fontcolor=45a536>12星</div>自动升级\", \"760040\", 0, 0, 1, {{76034}}, 0, 0, 0, 0}",
	[517303.0] = "{517303, \"影骑线\", \"多弗朗明哥\", 51730, 517304, 3, 0, 4, \"active_skill\", 0, 0, 1, 1, {5173003}, {}, 0, \"对全体造成150%魔法伤害，并偷取随机3个目标单位身上各1个增益Buff（不能偷取援护类、结界类、部分特殊效果等增益效果），技能有30%概率触发大成功，造成1.3倍技能伤害\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"22943\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[214204.0] = "{214204, \"霸气专家\", \"冥王雷利\", 21420, 0, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {}, {{'hp_max_per',400},{'atk_per',200},{'crit_rate',150}}, 0, \"生命提升40%，攻击提升20%，暴击率提升15%；\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"21120\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[771412.0] = "{771412, \"狼神\", \"狼刑\", 77142, 0, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7714022}, {}, 0, \"在战斗开始时，将给所有友方添加【冻冻果实】效果，为友方提升15%吸血效果，15%攻击提升，10%暴击几率，持续2回合且不可驱散\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"504023\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[760405.0] = "{760405, \"[觉醒]supre\", \"弗兰奇(新世界)\", 76040, 760406, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7604005,7604015}, {}, 0, \"弗兰奇阵亡后以100%血量复活并且为自身增加【super】持续至战斗结束\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：忍者到达<div fontcolor=45a536>12星</div>自动升级\", \"760040\", 0, 0, 1, {{76034}}, 0, 0, 0, 0}",
	[251204.0] = "{251204, \"双重果实\", \"黑胡子(新世界)\", 25120, 251205, 4, 0, 0, \"passive_skill\", 0, 0, 1, 1, {}, {{'atk_per',350},{'hp_max_per',150}}, 0, \"攻击力提升35%，生命提升15%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"61092\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[779501.0] = "{779501, \"红发大副\", \"贝克曼\", 77950, 0, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7795001}, {}, 0, \"贝克曼是红发海贼团副船长，香克斯的右手!战斗开始时，获得【香克斯右腕 I】登场时或者释放大招时，为己方全体附加【掌控全局 I】;每次获得【掌控全局】时，永久提升自身5%攻击力和防御力，可叠加10层受到致命伤害时，不会死亡，恢复全部生命，每场战斗可触发1次\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"779401\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[538103.0] = "{538103, \"金毘罗\", \"桃兔\", 53810, 538104, 3, 0, 4, \"active_skill\", 0, 0, 1, 1, {5381003}, {}, 0, \"桃兔站在战场中间，用武装色霸气覆盖金毘罗后，在敌方战场中快速穿梭，对敌方全体造成127%法术伤害，且有25%概率对敌方附加【离间】2回合。有25%概率对敌方附加【迟缓】2回合。\", \"初始激活\", \"\", \"53830\", 0, 0, 1, {}, 0, 0, 1, 0}",
	[517304.0] = "{517304, \"影骑线\", \"多弗朗明哥\", 51730, 517305, 4, 0, 4, \"active_skill\", 0, 0, 1, 1, {5173003}, {}, 0, \"对全体造成150%魔法伤害，并偷取随机3个目标单位身上各1个增益Buff（不能偷取援护类、结界类、部分特殊效果等增益效果），技能有30%概率触发大成功，造成1.3倍技能伤害\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"22943\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[783103.0] = "{783103, \"绞肉\", \"山治(鬼岛)\", 78310, 783104, 3, 0, 2, \"active_skill\", 0, 0, 1, 1, {7831003,7831101}, {}, 0, \"临时提升15%暴击率和20%命中，攻击敌方全体，造成320%物理伤害，附加自身攻击力的70%，自身生命值的20%真实伤害，(该伤害最大不超过自身攻击力的10倍)，70%概率附加【破甲】，持续2回合；\", \"初始激活\", \"\", \"783101\", 0, 1, 1, {{22103}}, 0, 0, 1, 0}",
	[151402.0] = "{151402, \"炙热领域\", \"艾斯\", 15140, 151403, 2, 0, 0, \"passive_skill\", 0, 0, 1, 1, {1514101}, {}, 0, \"进入战斗前2回合，以其炙热的领域降低敌方全体目标8%速度（该效果不可被驱散），持续2回合，对处于【迟缓】状态的单位伤害提升30%\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"15140\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[761404.0] = "{761404, \"灵灵果实\", \"佩罗娜\", 76140, 761405, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7614024}, {}, 0, \"佩罗娜阵亡时以50%生命值复活一次，普通攻击时，对生命最低的己方单体回复等同自身攻击力60%的生命值，并且驱散所有负面效果\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"761040\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[510303.0] = "{510303, \"追击\", \"卡普\", 51030, 510304, 3, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5103003}, {}, 0, \"不灭不休，攻击目标时，60%概率额外使出一道霸气追加攻击，造成120%攻击伤害\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"15240\", 0, 1, 1, {}, 0, 0, 0, 0}",
