	[765101.0] = "{765101, \"寂寞音符\", \"乌塔(世界歌姬)\", 76510, 765102, 1, 0, 2, \"active_skill\", 0, 0, 1, 1, {7651001,7651011,7651111}, {}, 0, \"乌塔对敌方全体目标释放寂寞音符，对敌方人数最多一排造成118%魔法伤害加自身攻击力10%生命值的10%伤害， 有30%对敌方施加【睡眠】，有30%对三名友方施加【攻击提升】\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"765010\", 0, 1, 1, {{24801,10161}}, 0, 0, 1, 0}",
	[764401.0] = "{764401, \"炎帝\", \"艾斯(龙年)\", 76440, 764402, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7644031,7644001,7644021}, {}, 0, \"艾斯(龙年)生命值低于40%，回复自身已损失生命值，进入炎帝状态，炎帝状态下【火拳】升级为【大炎戒·炎帝】，并且给自身增加【镜火炎】【阳炎】(触发后冷却4回合)\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"764040\", 0, 1, 1, {{76431,76441,76451,76411,76421}}, 0, 0, 0, 0}",
	[764314.0] = "{764314, \"大炎戒·炎帝\", \"艾斯(龙年)\", 76431, 764315, 4, 0, 2, \"active_skill\", 0, 0, 1, 1, {7643104,7643114,7643124}, {}, 0, \"普通状态下与【火拳】效果一致，进入炎帝状态下升级为【大炎戒·炎帝】对敌方全体单位造成260%物理伤害加自身攻击力的160%伤害，该伤害无视防御，并且有20%概率对敌方单位附加【神火·不知火】，对灼烧状态下的敌人增加40%伤害，击杀敌方单位再次施法(每回合最多触发一次)\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"764030\", 0, 1, 1, {{76444}}, 0, 0, 2, 0}",
