	[513353.0] = "{513353, \"雷冶金\", \"艾尼路\", 51335, 513354, 3, 0, 4, \"active_skill\", 0, 0, 1, 1, {5133503,5133523}, {}, 0, \"艾尼路召唤雷霆攻击前方2个单位，对每个单位造成220%魔法伤害，55%概率对目标附加【迟缓】效果，持续2回合；同时为自己生成一个持续2回合的【护盾】，护盾值为本次技能带来伤害的30%\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"20230\", 0, 1, 1, {{28001,12104}}, 0, 0, 2, 0}",
	[774305.0] = "{774305, \"[觉醒]袷羽槛\", \"日奈\", 77430, 0, 5, 0, 4, \"active_skill\", 0, 0, 1, 1, {7743005,7743015}, {}, 0, \"日奈对敌方施展槛槛果实觉醒能力，对敌方全体造成548%法术伤害，敌方单位每存在一层增益buff，日奈本次伤害提升50%，本次攻击必定附加【镣铐】，对【镣铐】状态下的敌人附加【海楼石枷锁】\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"774301\", 0, 1, 1, {{77501,77502}}, 0, 0, 2, 0}",
	[754401.0] = "{754401, \"女帝权柄\", \"汉库克(七武海)\", 75440, 754402, 1, 0, 0, \"passive_skill\", 0, 0, 2, 1, {7544001}, {}, 0, \"汉库克攻击【魅惑】状态下的敌人，有50%概率附加【俘虏】战斗开始时,提升己方全体法师10%魔法伤害（(该效果不可驱散)，持续2回合\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"75440\", 0, 0, 1, {{75441}}, 0, 0, 0, 0}",
	[522205.0] = "{522205, \"[觉醒]甜甜果实\", \"汉库克\", 52220, 0, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {}, {{'atk_per',400},{'hp_max_per',200},{'speed',30}}, 0, \"生命值提升40%，攻击力提升20%，速度提升30\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"22992\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[769102.0] = "{769102, \"禁憎森森\", \"绿牛\", 76910, 769103, 2, 0, 2, \"active_skill\", 0, 0, 1, 1, {7691002,7691012,7691102}, {}, 0, \"绿牛对敌方阵营释放【禁憎森森】对敌方全体单位造成180%魔法伤害，额外附加绿牛生命值最大的30%真实伤害，同时治疗友方全体单位，并有20%的概率对敌方单位附加【森之束缚】，同时对友方全体单位附加【治疗盾】\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>7星</div>自动升级\", \"769101\", 0, 1, 1, {{16301,76912}}, 0, 0, 1, 0}",
	[767302.0] = "{767302, \"糖果潮汐\", \"佩罗斯佩罗\", 76730, 767303, 2, 0, 4, \"active_skill\", 0, 0, 1, 1, {7673002}, {}, 0, \"召唤糖果潮汐随机使用攻击或者祝福技能：如果发动攻击，它将对敌方全体造成225%的法术伤害，并附加【攻击降低】【命中降低】【受疗降低】【中毒】效果；如果发动祝福，将恢复友方全体基于佩罗斯佩罗最大生命值的25%，并附加【攻击提升】【受疗提升】【命中提升】效果\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>9星</div>自动升级\", \"206101\", 0, 1, 1, {{23509,61852,20703,21502,10200,11202,31141}}, 0, 0, 2, 0}",
	[776305.0] = "{776305, \"[觉醒]威国&霸海\", \"夏洛特玲玲\", 77630, 0, 5, 0, 4, \"active_skill\", 0, 0, 1, 1, {7763005,7763015,7763025}, {}, 0, \"四皇夏洛特·玲玲与凯多合体招式【威国&霸海】对敌方全体造成538%法术伤害附加自身最大生命值的100%自身攻击力的100%真实伤害，并且有80%的概率使受击着触发【灵魂消散】，该技能成功击杀目标触发技能【灵魂果实】\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"776301\", 0, 1, 1, {{77701}}, 0, 0, 2, 0}",
	[545301.0] = "{545301, \"穿刺波动\", \"罗(和之国)\", 54530, 545302, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {5453001}, {}, 0, \"手术果实觉醒后的终极招式，通过波动直接伤害敌方全体，此技能无视20%防御，对敌方全体造成97%的法术伤害，同时目标身上每有一个负面效果，额外造成目标最大生命值1%的伤害（最大不超过罗攻击力5倍）\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"54530\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[513352.0] = "{513352, \"雷冶金\", \"艾尼路\", 51335, 513353, 2, 0, 4, \"active_skill\", 0, 0, 1, 1, {5133502,5133522}, {}, 0, \"艾尼路召唤雷霆攻击前方2个单位，对每个单位造成184%魔法伤害，45%概率对目标附加【迟缓】效果，持续2回合；同时为自己生成一个持续2回合的【护盾】，护盾值为本次技能带来伤害的20%\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>7星</div>自动升级\", \"20230\", 0, 1, 1, {{28001,12103}}, 0, 0, 2, 0}",
	[552103.0] = "{552103, \"雷鸣八卦\", \"凯多(神龙)\", 55210, 552104, 3, 0, 2, \"active_skill\", 0, 0, 1, 1, {5521003,5521011}, {}, 0, \"对敌方全体造成215%法术伤害，并且有40%概率将其击晕附加【眩晕】效果，此攻击必中，且必定眩晕一名目标\", \"初始激活\", \"\", \"55210\", 0, 1, 1, {{28201}}, 0, 0, 1, 0}",
	[551104.0] = "{551104, \"闪电雷枪\", \"路飞(尼卡形态)\", 55110, 551105, 4, 0, 2, \"active_skill\", 0, 0, 1, 1, {5511004}, {}, 0, \"路飞使用雷电长枪对敌方全体发起攻击，对敌方造成316%法术伤害附加路飞自身攻击力的25%最大生命值上限的25%真实伤害，并有40%的概率使敌方进入【麻痹】状态(该伤害最多不超过自身攻击力的6倍)\", \"初始激活\", \"\", \"70410\", 0, 1, 1, {{28101}}, 0, 0, 1, 0}",
	[782402.0] = "{782402, \"草帽航海士\", \"娜美(宙斯)\", 78240, 782403, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7824002,7824012}, {}, 0, \"回合开始为自身提供免疫控制，持续1回合，为友方全体单位提供以下随机一种效果；1、增加20%暴击率，持续1回合，2、增加20%攻击力，持续1回合，3、增加20%免伤，持续1回合，4、增加20%速度，持续1回合\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"782401\", 0, 0, 1, {{27102,26102}}, 0, 0, 0, 0}",
	[520399.0] = "{520399, \"二档还原\", \"路飞\", 52039, 0, 1, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5205011,5205021,5205031,5205041,5205051}, {}, 0, \"路飞发出猛烈的5连击，对单位共造成150%物理伤害，每一段有20%概率对单位叠加1层持续2回合的【出血】效果\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"22971\", 0, 1, 1, {}, 0, 0, 1, 0}",
	[777302.0] = "{777302, \"橡胶·象枪\", \"路飞(和之国)\", 77730, 777303, 2, 0, 4, \"active_skill\", 0, 0, 1, 1, {7773002,7773012,7770111,7773022}, {}, 0, \"路飞使用【橡胶·象枪】对敌方发起攻击，对敌方全体单位造成238%物理伤害附加自身攻击力的60%，自身生命值的60%真实伤害，对灼烧状态下的单位额外增40%的伤害，且必定暴击，击杀目标再次释放（每回合仅触发一次）\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>9星</div>自动升级\", \"777301\", 0, 1, 1, {{76011}}, 0, 0, 2, 0}",
