	[520201.0] = "{520201, \"橡胶果实\", \"路飞\", 52020, 520202, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {}, {{'atk_per',200},{'hp_max_per',100},{'crit_rate',50}}, 0, \"橡胶果实赋予了路飞无与伦比的战斗灵活性，使其攻击提升20%，生命提升10%，暴击率提升5%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"22972\", 0, 1, 1, {}, 0, 0, 0, 0}",
