	[771303.0] = "{771303, \"狼神·破空斩\", \"狼刑\", 77130, 771304, 3, 0, 4, \"active_skill\", 0, 0, 1, 1, {7713003}, {}, 0, \"狼刑召唤狼神对敌方释放狼神·破空斩对敌方全体造成等同于[自身生命上限15% + 目标攻击力150%]的真实伤害，并且有40%的几率给目标附加【封印】效果\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"77103\", 0, 1, 1, {{22001}}, 0, 0, 2, 0}",
