	[757402.0] = "{757402, \"海贼王\", \"罗杰\", 75740, 757403, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7574002,7574012}, {}, 0, \"战斗开始，自身获得【航海王】增益，并且为友方全体英雄增加【航海王庇佑】\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"75740\", 0, 0, 1, {{75742}}, 0, 0, 0, 0}",
	[227102.0] = "{227102, \"黑刀·大龙卷\", \"索隆(新世界)\", 22710, 227103, 2, 0, 2, \"active_skill\", 0, \"max_speed\", 1, 1, {2271002}, {}, 0, \"索隆进入新世界的必杀技，，对敌方全体造成92%物理伤害，60%概率附加【流血】状态，持续2回合\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>7星</div>自动升级\", \"60691\", 0, 1, 1, {{21304}}, 0, 1, 1, 0}",
	[519303.0] = "{519303, \"毒龙舞\", \"麦哲伦\", 51930, 519304, 3, 0, 4, \"active_skill\", 0, 0, 2, 1, {5193013,5193023}, {}, 0, \"麦哲伦激发毒素召唤巨大的毒素巨浪，造成751%的总魔法伤害，由敌方所有单位共同承受，敌方存活英雄越少，每个单位所受伤害越高，每个单位所受伤害最高不超过麦哲伦攻击力的4倍；同时有30%概率对受击单位附加【致盲】效果，持续2回合\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"22963\", 0, 1, 1, {{25001}}, 0, 0, 2, 0}",
