	[757401.0] = "{757401, \"海贼王\", \"罗杰\", 75740, 757402, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7574001,7574011}, {}, 0, \"战斗开始，自身获得【航海王】增益，并且为友方全体英雄增加【航海王庇佑】\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"75740\", 0, 0, 1, {{75741}}, 0, 0, 0, 0}",
	[771103.0] = "{771103, \"裂空斩击\", \"狼刑\", 77110, 771104, 3, 0, 2, \"active_skill\", 0, 0, 1, 1, {7711003}, {}, 0, \"狼神对敌方释放裂空斩击，对敌方全体单位造成物理伤害，伤害值为[自身生命上限10%+目标攻击力160%],并且有40%的几率给目标附加【封印】效果\", \"初始激活\", \"\", \"77101\", 0, 1, 1, {{22001}}, 0, 0, 1, 0}",
	[763504.0] = "{763504, \"灵魂之王\", \"布鲁克(新世界)\", 74450, 744505, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7635004}, {}, 0, \"战斗开始时，给全体队友增加【灵魂之王】，增加30%速度，增加30%攻击，增加20%暴击几率\", \"激活条件：忍者到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：忍者到达<div fontcolor=45a536>6星</div>自动升级\", \"705014\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[705901.0] = "{705901, \"普通攻击\", \"萨坦圣\", 70590, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {7059001}, {}, 0, \"对前方1个目标造成100%的魔法伤害\", \"\", \"\", \"405181\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[763503.0] = "{763503, \"灵魂之王\", \"布鲁克(新世界)\", 74450, 744504, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7635003}, {}, 0, \"战斗开始时，给全体队友增加【灵魂之王】，增加25%速度，增加25%攻击，增加15%暴击几率\", \"激活条件：忍者到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：忍者到达<div fontcolor=45a536>6星</div>自动升级\", \"705014\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[519304.0] = "{519304, \"毒龙舞\", \"麦哲伦\", 51930, 519305, 4, 0, 4, \"active_skill\", 0, 0, 2, 1, {5193013,5193023}, {}, 0, \"麦哲伦激发毒素召唤巨大的毒素巨浪，造成751%的总魔法伤害，由敌方所有单位共同承受，敌方存活英雄越少，每个单位所受伤害越高，每个单位所受伤害最高不超过麦哲伦攻击力的4倍；同时有30%概率对受击单位附加【致盲】效果，持续2回合\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"22963\", 0, 1, 1, {{25001}}, 0, 0, 2, 0}",
	[525202.0] = "{525202, \"熔岩之力\", \"赤犬\", 52520, 525203, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {}, {{'hp_max_per',300},{'atk_per',150},{'tenacity',200}}, 0, \"赤犬生命提升30%，攻击提升15%，抗暴提升20%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>8星</div>自动升级\", \"23503\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[768305.0] = "{768305, \"[觉醒]电磁碎击\", \"伽治\", 76830, 0, 5, 0, 4, \"active_skill\", 0, 0, 1, 1, {7683005}, {}, 0, \"伽治跃起使用长矛对敌方全体发动【电磁碎击】，对敌方全体造成565%的物理伤害附加自身最大生命值%100的伤害，并且有60%概率对敌方附加【麻痹】(该技能最大伤害不能超过自己攻击力的十倍)\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"768301\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[505301.0] = "{505301, \"神火·不知火\", \"艾斯（魂）\", 50530, 505302, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {5053001}, {}, 0, \"未知之火，若火爆裂，对全体敌方造成30%伤害并从【降疗30%】【减命中20%】【减攻30%】【中毒】中随机附加1种负面状态，持续2回合；若火柔和，则恢复己方全体10%最大生命并提升10%攻击2回合\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"61293\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[512303.0] = "{512303, \"恶魔风脚\", \"山治\", 51230, 512304, 3, 0, 4, \"active_skill\", 0, 0, 1, 1, {5123003,5123013}, {}, 0, \"发动迅捷的突袭，攻击单位数最多的一列，对每个目标共造成206%的物理伤害，并有90%概率对目标附加【出血】状态，25%概率对目标附加【混乱状态】，均持续2回合\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"21350\", 0, 1, 1, {{21011,28501}}, 0, 0, 2, 0}",
	[510321.0] = "{510321, \"追击\", \"卡普\", 51032, 510331, 2, 0, 0, \"active_skill\", 0, 0, 1, 1, {5103201}, {}, 0, \"攻击目标时，40%概率额外使出一道霸气追加攻击，造成80%攻击伤害\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"15240\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[552105.0] = "{552105, \"[觉醒]雷鸣八卦\", \"凯多(神龙)\", 55210, 0, 5, 0, 2, \"active_skill\", 0, 0, 1, 1, {5521005,5521011}, {}, 0, \"对敌方全体造成255%法术伤害，并且有60%概率将其击晕附加【眩晕】效果，此攻击必中，且必定眩晕两名目标\", \"初始激活\", \"\", \"55210\", 0, 1, 1, {{28201}}, 0, 0, 1, 0}",
	[215203.0] = "{215203, \"野蛮恢复\", \"海贼14号\", 21520, 215204, 3, 0, 4, \"active_skill\", 0, 0, 2, 1, {2152003}, {}, 0, \"为己方生命值最低的2个单位，恢复关联海贼14号攻击力的66.2%+32点生命值\", \"开启条件测试\", \"\", \"21520\", 0, 1, 1, {}, 0, 1, 2, 0}",
	[519305.0] = "{519305, \"[觉醒]毒龙舞\", \"麦哲伦\", 51930, 0, 5, 0, 4, \"active_skill\", 0, 0, 2, 1, {5193013,5193023}, {}, 0, \"麦哲伦激发毒素召唤巨大的毒素巨浪，造成751%的总魔法伤害，由敌方所有单位共同承受，敌方存活英雄越少，每个单位所受伤害越高，每个单位所受伤害最高不超过麦哲伦攻击力的4倍；同时有30%概率对受击单位附加【致盲】效果，持续2回合\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"22963\", 0, 1, 1, {{25001}}, 0, 0, 2, 0}",
	[529001.0] = "{529001, \"普通攻击\", \"藤虎\", 52900, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {5290001}, {}, 0, \"对前方单体造成100%物理伤害\", \"\", \"\", \"20000\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[550101.0] = "{550101, \"疫灾\", \"奎因\", 55010, 550102, 1, 0, 2, \"active_skill\", 0, 0, 1, 1, {5501001,5501101}, {}, 0, \"对敌方全体进行劈砍，造成80%魔法伤害，并有50%概率使目标感染持续2回合的[瘟疫标记]，不可叠加，不可被驱散\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"55010\", 0, 1, 1, {{55014}}, 0, 0, 1, 0}",
