	[512302.0] = "{512302, \"恶魔风脚\", \"山治\", 51230, 512303, 2, 0, 4, \"active_skill\", 0, 0, 1, 1, {5123002,5123012}, {}, 0, \"发动迅捷的突袭，攻击单位数最多的一列，对每个目标共造成172%的物理伤害，并有75%概率对目标附加【出血】状态，20%概率对目标附加【混乱状态】，均持续2回合\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>9星</div>自动升级\", \"21350\", 0, 1, 1, {{21011,28501}}, 0, 0, 2, 0}",
	[781402.0] = "{781402, \"肉球果实\", \"熊(机械)\", 78140, 781403, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7814002}, {}, 0, \"对忍术职业伤害提升20%；回合开始时，给自己附加【肉球复活】，100%概率获得获得1层【肉球果实】；队友死亡时，自身获得1层【肉球果实】，持续4回合。\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"781401\", 0, 0, 1, {{27102,26102}}, 0, 0, 0, 0}",
	[550102.0] = "{550102, \"疫灾\", \"奎因\", 55010, 550103, 2, 0, 2, \"active_skill\", 0, 0, 1, 1, {5501002,5501102}, {}, 0, \"对敌方全体进行劈砍，造成100%魔法伤害，并有60%概率使目标感染持续2回合的[瘟疫标记]，不可叠加，不可被驱散\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>7星</div>自动升级\", \"55010\", 0, 1, 1, {{55015}}, 0, 0, 1, 0}",
	[758404.0] = "{758404, \"最强剑豪\", \"鹰眼(七武海)\", 75840, 758405, 4, 0, 0, \"passive_skill\", 0, 0, 1, 1, {7584001,7584011,7584021,7585001,7585102,7585204}, {}, 0, \"鹰眼(七武海)血量达到一定百分比时受到伤害，将释放他的霸气以消除自身所有的控制效果，并根据他的生命百分比执行以下操作；≤70%：为所有友方恢复鹰眼(七武海)100%攻击力的生命值，并附加【强化】效果；≤50%：对所有敌人造成等同于鹰眼(七武海)生命值上限8%+自身攻击力150%的伤害，并附加【震慑效果】，同时对其中1个敌人附加【眩晕】效果(每个效果释放后冷却2回合)\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：忍者到达<div fontcolor=45a536>12星</div>自动升级\", \"75840\", 0, 0, 1, {{61221,61231,61201,61241}}, 0, 0, 0, 0}",
	[515354.0] = "{515354, \"无上大快刀\", \"鹰眼\", 51535, 515355, 4, 0, 4, \"active_skill\", 0, 0, 1, 1, {5153501,5159903}, {}, 0, \"鹰眼释放所有怒气施展华丽而猛烈剑术，临时提升自身30%命中率后，对前方单体造成3次各150%物理伤害的斩击（共450%伤害），每3层【怒气】则额外增加1次斩击（最多2次，共5连击），额外斩击的最后一击会对目标以外随机2个单位造成相同系数的溅射伤害，怒气在行动结束后消失\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"22933\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[781401.0] = "{781401, \"肉球果实\", \"熊(机械)\", 78140, 781402, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7814001}, {}, 0, \"对忍术职业伤害提升10%；回合开始时，给自己附加【肉球复活】，100%概率获得获得1层【肉球果实】；队友死亡时，自身获得1层【肉球果实】，持续4回合。\", \"\", \"\", \"781401\", 0, 0, 1, {{27101,26101}}, 0, 0, 0, 0}",
	[550103.0] = "{550103, \"疫灾\", \"奎因\", 55010, 550104, 3, 0, 2, \"active_skill\", 0, 0, 1, 1, {5501003,5501103}, {}, 0, \"对敌方全体进行劈砍，造成120%魔法伤害，并有70%概率使目标感染持续2回合的[瘟疫标记]，不可叠加，不可被驱散\", \"初始激活\", \"\", \"55010\", 0, 1, 1, {{55016}}, 0, 0, 1, 0}",
	[512305.0] = "{512305, \"[觉醒]恶魔风脚\", \"山治\", 51230, 0, 5, 0, 4, \"active_skill\", 0, 0, 1, 1, {5123003,5123013}, {}, 0, \"发动迅捷的突袭，攻击单位数最多的一列，对每个目标共造成206%的物理伤害，并有90%概率对目标附加【出血】状态，25%概率对目标附加【混乱状态】，均持续2回合\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"21350\", 0, 1, 1, {{21011,28501}}, 0, 0, 2, 0}",
	[515203.0] = "{515203, \"天下第一\", \"鹰眼\", 51520, 515204, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {}, {{'atk_per',400},{'hp_max_per',200},{'crit_rate',150}}, 0, \"攻击提升40%，生命提升20%，暴击率提升15%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"22932\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[732303.0] = "{732303, \"暗穴道\", \"黑胡子(四皇)\", 73230, 732304, 3, 0, 4, \"active_skill\", 0, 0, 1, 1, {7323003,7323033}, {}, 0, \"对所有敌人造成共计900%的法术伤害，这些伤害由地方所有单位均摊，受击单位越少，造成的伤害越高，伤害不超过黑胡子自身攻击力的6倍，并有60%概率附加【黑暗印记】效果\", \"\", \"\", \"73230\", 0, 1, 1, {{61091,21001}}, 0, 0, 2, 0}",
	[546304.0] = "{546304, \"魔鬼形态\", \"巴雷特\", 54630, 546305, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5463004}, {}, 0, \"受到攻击时，50%概率获得1层【钢铁肌肉】，累计获得6层【钢铁肌肉】时，6层【钢铁肌肉】转化为1层【魔鬼形态】\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"54630\", 0, 1, 1, {{54631,54693}}, 0, 0, 0, 0}",
	[535205.0] = "{535205, \"[觉醒]海军导师\", \"泽法\", 53520, 0, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5352003}, {{'hp_max_per',350},{'atk_per',300}}, 0, \"生命提升35%，攻击提升30%。战斗开始时，友方全体海军提升6%的攻击力，此效果不可驱散，持续到战斗结束。\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"53520\", 0, 1, 1, {{53523}}, 0, 0, 0, 0}",
	[277001.0] = "{277001, \"普通攻击\", \"海贼12号\", 27700, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {2770001}, {}, 0, \"对前方单体造成100%物理伤害\", \"\", \"\", \"20000\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[263101.0] = "{263101, \"强力挥砍\", \"海贼8号\", 26310, 0, 1, 0, 2, \"active_skill\", 0, 0, 1, 1, {2631001,2631101}, {}, 0, \"对敌方单体造成162%物理伤害，对处于【减速】状态的目标伤害提升30%\", \"初始激活\", \"\", \"20710\", 0, 0, 1, {{23001}}, 0, 0, 1, 0}",
	[505304.0] = "{505304, \"神火·不知火\", \"艾斯（魂）\", 50530, 505305, 4, 0, 4, \"active_skill\", 0, 0, 1, 1, {5053003}, {}, 0, \"未知之火，若火爆裂，对全体敌方造成30%伤害并从【降疗30%】【减命中20%】【减攻30%】【中毒】中随机附加2种负面状态，持续2回合；若火柔和，则恢复己方全体15%最大生命并提升20%攻击2回合\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"61293\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[758401.0] = "{758401, \"最强剑豪\", \"鹰眼(七武海)\", 75840, 758402, 1, 0, 0, \"passive_skill\", 0, 0, 1, 1, {7584001,7584011,7584021}, {}, 0, \"鹰眼(七武海)血量达到一定百分比时受到伤害，将释放他的霸气以消除自身所有的控制效果，并根据他的生命百分比执行以下操作；≤70%：为所有友方恢复鹰眼(七武海)100%攻击力的生命值，并附加【强化】效果(每个效果释放后冷却2回合)\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"75840\", 0, 0, 1, {{61221}}, 0, 0, 0, 0}",
	[777502.0] = "{777502, \"流樱(复活)\", \"路飞(和之国)\", 77750, 777502, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7775002}, {}, 0, \"\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"225501\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[516405.0] = "{516405, \"[觉醒]果实觉醒\", \"白胡子\", 51640, 0, 5, 0, 0, \"passive_skill\", 0, 0, 2, 1, {5164013}, {}, 0, \"若敌方单位在携带【空间撕裂】时死亡，则己方全体单位回复白胡子120%攻击力的生命值；且白胡子每次攻击将有60%概率给目标附加【空间撕裂】，持续2回合\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"22584\", 0, 1, 1, {{29201}}, 0, 0, 0, 0}",
	[782203.0] = "{782203, \"气象知识\", \"娜美(宙斯)\", 78220, 782204, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7822003,7822013}, {{'hp_max_per',400},{'atk_per',300},{'speed',30},{'crit_rate',150}}, 0, \"攻击提升30%，生命提升40%，暴击率提升15%，速度提升30；回合结束时，对【低压】目标扣血7%，对【高压】目标恢复自身生命值上限7%生命值\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>8星</div>自动升级\", \"782201\", 0, 0, 1, {}, 0, 0, 0, 0}",
	[764305.0] = "{764305, \"[觉醒]大炎戒·炎帝\", \"艾斯(龙年)\", 76430, 0, 5, 0, 2, \"active_skill\", 0, 0, 1, 1, {7643005,7643015}, {}, 0, \"普通状态下与【火拳】效果一致，进入炎帝状态下升级为【大炎戒·炎帝】对敌方全体单位造成300%物理伤害加自身攻击力的200%伤害，该伤害无视防御，并且有20%概率对敌方单位附加【神火·不知火】，对灼烧状态下的敌人增加50%伤害，击杀敌方单位再次施法(每回合最多触发一次)\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"764030\", 0, 1, 1, {{76445}}, 0, 0, 2, 0}",
	[783105.0] = "{783105, \"[魂]绞肉\", \"山治(鬼岛)\", 78310, 0, 5, 0, 2, \"active_skill\", 0, 0, 1, 1, {7831005,7831103}, {}, 0, \"临时提升60%暴击率和80%命中，攻击敌方全体，造成490%物理伤害，附加自身攻击力的150%，自身生命值的30%真实伤害，(该伤害最大不超过自身攻击力的15倍)，100%概率附加【破甲】，持续2回合；\", \"初始激活\", \"升级条件：10星忍者<div fontcolor=45a536>技能突破</div>升级\", \"783101\", 0, 1, 1, {{22105}}, 0, 0, 1, 0}",
	[157102.0] = "{157102, \"迫击炮\", \"阿布萨罗姆\", 15710, 157103, 2, 0, 2, \"active_skill\", 0, 0, 1, 1, {1571002,1571102}, {}, 0, \"使用隐藏在手袖中的迫击炮，对生命最低的敌方单体造成184%物理伤害，80%概率附加【流血】状态，持续2回合\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>7星</div>自动升级\", \"22220\", 0, 1, 1, {{21301}}, 0, 0, 1, 0}",
