	[256401.0] = "{256401, \"八尺镜\", \"黄猿\", 25640, 256402, 1, 0, 0, \"passive_skill\", 0, 0, 2, 1, {}, {}, 0, \"强化【八尺琼勾玉】，使用八尺琼勾玉时额外对除了目标以外的随机敌方单体造成40%伤害\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"50894\", 0, 5, 1, {}, 0, 0, 0, 0}",
