	[512315.0] = "{512315, \"[觉醒]恶魔风脚\", \"山治\", 51231, 0, 5, 0, 4, \"active_skill\", 0, 0, 1, 1, {5123003,5123013,5124001,5124011}, {}, 0, \"发动迅捷的突袭，攻击单位数最多的一列，对每个目标共造成206%的物理伤害，并有90%概率对目标附加【出血】状态，25%概率对目标附加【混乱状态】，均持续2回合\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"21350\", 0, 1, 1, {{21011,28501}}, 0, 0, 2, 0}",
	[510333.0] = "{510333, \"[觉醒]追击\", \"卡普\", 51033, 0, 5, 0, 0, \"active_skill\", 0, 0, 1, 1, {5103301}, {}, 0, \"攻击目标时，50%概率额外使出一道霸气追加攻击，造成100%攻击伤害\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"15240\", 0, 1, 1, {}, 0, 0, 0, 0}",
