	[764304.0] = "{764304, \"大炎戒·炎帝\", \"艾斯(龙年)\", 76430, 764305, 4, 0, 2, \"active_skill\", 0, 0, 1, 1, {7643004,7643014}, {}, 0, \"普通状态下与【火拳】效果一致，进入炎帝状态下升级为【大炎戒·炎帝】对敌方全体单位造成260%物理伤害加自身攻击力的160%伤害，该伤害无视防御，并且有20%概率对敌方单位附加【神火·不知火】，对灼烧状态下的敌人增加40%伤害，击杀敌方单位再次施法(每回合最多触发一次)\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"764030\", 0, 1, 1, {{76444}}, 0, 0, 2, 0}",
	[533104.0] = "{533104, \"无双年糕刃弹\", \"卡塔库栗\", 53310, 533105, 4, 0, 4, \"active_skill\", 0, 0, 1, 1, {5331003,5331803}, {}, 0, \"卡塔库栗用武装色霸气将年糕包裹如雨般攻击敌方全体，造成160%的物理伤害且有100%概率将在命中目标身上添加一层等同自身攻击力50%的【年糕附着】效果，如目标血量高于40%，则额外60%概率再添加一层【年糕附着】\", \"初始激活\", \"\", \"53310\", 0, 0, 1, {{53303}}, 0, 0, 1, 0}",
	[547102.0] = "{547102, \"业火手枪\", \"路飞(四挡)\", 54710, 547103, 2, 0, 2, \"active_skill\", 0, 0, 1, 1, {5471002}, {}, 0, \"橡胶象枪与橡胶火拳铳的融合，并将高级武装色霸气注入到了手枪里，对敌方全体造成135%物理伤害并有40%概率附加一层橡胶粘液\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>7星</div>自动升级\", \"70310\", 0, 1, 1, {{57011}}, 0, 0, 1, 0}",
