	[532202.0] = "{532202, \"金鱼王后\", \"金鱼乙姬\", 53220, 532203, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {}, {{'hp_max_per',200},{'atk_per',150},{'speed',20}}, 0, \"乙姬生命提升20%，攻击提升15%，速度提升20点，乙姬所造成的所有治疗均会对目标添加【意识传达】\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>8星</div>自动升级\", \"53220\", 0, 1, 1, {{53222}}, 0, 0, 0, 0}",
