	[781403.0] = "{781403, \"肉球果实\", \"熊(机械)\", 78140, 781404, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7814003}, {}, 0, \"对忍术职业伤害提升30%；回合开始时，给自己附加【肉球复活】，100%概率获得获得1层【肉球果实】；队友死亡时，自身获得1层【肉球果实】，持续4回合。\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"781401\", 0, 0, 1, {{27103,26103}}, 0, 0, 0, 0}",
