	[514301.0] = "{514301, \"佛之守护\", \"战国\", 51430, 514302, 1, 0, 4, \"active_skill\", 0, 0, 2, 1, {5143001}, {}, 0, \"使我方全体魔法免伤提升10%，且对我方全体附加【灵魂结界】效果，均摊我方所有单位受到的攻击伤害，持续2回合，效果均不可被驱散\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"24150\", 0, 1, 1, {{19101}}, 0, 0, 2, 0}",
	[764311.0] = "{764311, \"大炎戒·炎帝\", \"艾斯(龙年)\", 76431, 764312, 1, 0, 2, \"active_skill\", 0, 0, 1, 1, {7643101,7643111,7643121}, {}, 0, \"普通状态下与【火拳】效果一致，进入炎帝状态下升级为【大炎戒·炎帝】对敌方全体单位造成120%物理伤害加自身攻击力的60%伤害，该伤害无视防御，并且有20%概率对敌方单位附加【神火·不知火】，对灼烧状态下的敌人增加10%伤害，击杀敌方单位再次施法(每回合最多触发一次)\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"764030\", 0, 1, 1, {{76441}}, 0, 0, 2, 0}",
