	[504403.0] = "{504403, \"影子缠绕\", \"月光莫利亚\", 50440, 504404, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5044003}, {}, 0, \"每次攻击为目标附加1个【影子缠绕】，敌方每携带1个【影子缠绕】提升月光莫利亚3%攻击，最多可叠加10层攻击提升，印记不可被驱散；携带3个【影子缠绕】的敌方单位受到的伤害增加30%\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"42094\", 0, 1, 1, {{37170}}, 0, 0, 0, 0}",
