	[545305.0] = "{545305, \"[觉醒]穿刺波动\", \"罗(和之国)\", 54530, 0, 5, 0, 4, \"active_skill\", 0, 0, 1, 1, {5453005}, {}, 0, \"手术果实觉醒后的终极招式，通过波动直接伤害敌方全体，此技能无视70%防御，对敌方全体造成262%的法术伤害，同时目标身上每有一个负面效果，额外造成目标最大生命值2%的伤害（最大不超过罗攻击力5倍）\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"54530\", 0, 1, 1, {}, 0, 0, 2, 0}",
