	[757302.0] = "{757302, \"神避\", \"罗杰\", 75730, 757303, 2, 0, 4, \"active_skill\", 0, 0, 1, 1, {7573002,7573012,7573021}, {}, 0, \"罗杰发动终极招式【神避】，对敌方全体单位造成罗杰攻击力150%+生命值上限的15%伤害（该伤害无视防御，不受免伤效果影响），对【霸王色·破甲】状态下的敌人增伤50%\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>9星</div>自动升级\", \"75730\", 0, 1, 1, {{75711,75712}}, 0, 0, 2, 0}",
