	[781502.0] = "{781502, \"法术增伤\", \"熊(机械)\", 78150, 781503, 2, 0, 0, \"passive_skill\", 0, 0, 1, 1, {7815002}, {}, 0, \"对忍术职业伤害提升20%；回合开始时，100%概率获得获得1层【肉球果实】；队友死亡时，自身获得1层【肉球果实】，持续4回合。\", \"\", \"\", \"781401\", 0, 0, 1, {}, 0, 0, 0, 0}",
