	[537401.0] = "{537401, \"惊吓\", \"白星\", 53740, 537402, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5374001}, {}, 0, \"战场上有单位死亡时，白星会受到惊吓，有50%的概率使用一次【古代兵器】。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"53740\", 0, 1, 1, {}, 0, 0, 0, 0}",
