	[216151.0] = "{216151, \"情绪治愈\", \"幽冥公主\", 21615, 216152, 1, 0, 4, \"active_skill\", 0, 0, 2, 1, {2161001,2161301,2161401}, {}, 0, \"复活己方单体，并回复其等同自身攻击力171%的生命；若己方无死亡单位，则为生命最低的己方单位恢复等同自身攻击力247%的生命\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"21615\", 0, 1, 1, {}, 0, 0, 2, 0}",
