	[549302.0] = "{549302, \"腐骨毒雾\", \"蕾玖\", 54930, 549303, 2, 0, 4, \"active_skill\", 0, 0, 1, 1, {5493002,5493102,5493202}, {}, 0, \"蕾玖在己方阵地喷吐出腐骨毒雾，会使4名友方单位失去最大生命16%的当前生命值（此效果可致死），同时驱除目标3个负面状态，且附加【再生毒素】，持续4回合\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>9星</div>自动升级\", \"54930\", 0, 1, 1, {{54931}}, 0, 0, 2, 0}",
	[548103.0] = "{548103, \"旱灾\", \"杰克\", 54810, 548104, 3, 0, 2, \"active_skill\", 0, 0, 5, 1, {5481003,5481103,5481203,5481303}, {}, 0, \"百兽海贼团的三灾之一，因所踏之处如同旱灾出现般干涸腐朽，吸取敌方全体15%的防御附加到自己身上，杰克血量高于50%时，给自身附加持续2回合的【反弹护盾】，血量低于50%时回复自身8%的最大生命值\", \"初始激活\", \"\", \"54810\", 0, 1, 1, {{54815,54833}}, 0, 0, 1, 0}",
