	[770305.0] = "{770305, \"[觉醒]御守·火龙皇\", \"烬\", 77030, 0, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7703005}, {}, 0, \"【最终形态】下可施展，炎灾·烬最终招式御守·火龙皇，对敌方全体造成388%加自身攻击力90%加自身防御力400%的物理伤害(此伤害无视防御)，(露娜利亚族叠加至5层下次攻击释放该技能)\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"770030\", 0, 1, 1, {{77005}}, 0, 0, 0, 0}",
	[551202.0] = "{551202, \"橡胶果实\", \"路飞(尼卡形态)\", 55120, 551203, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5512002,5512012}, {{'atk_per',250},{'hp_max_per',350},{'speed',20}}, 0, \"路飞生命提升35%，攻击提升25%，速度提升20，战斗开始时自身获得【绝缘橡胶】，己方随机两名英雄获得【控制免疫】持续一回合\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>8星</div>自动升级\", \"70420\", 0, 1, 1, {{19852,58041}}, 0, 0, 0, 0}",
	[545304.0] = "{545304, \"穿刺波动\", \"罗(和之国)\", 54530, 545305, 4, 0, 4, \"active_skill\", 0, 0, 1, 1, {5453004}, {}, 0, \"手术果实觉醒后的终极招式，通过波动直接伤害敌方全体，此技能无视60%防御，对敌方全体造成192%的法术伤害，同时目标身上每有一个负面效果，额外造成目标最大生命值2%的伤害（最大不超过罗攻击力5倍）\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"54530\", 0, 1, 1, {}, 0, 0, 2, 0}",
