	[516121.0] = "{516121, \"丛云切\", \"白胡子\", 51612, 516122, 1, 0, 2, \"active_skill\", 0, 0, 1, 1, {5161001,5161011,5164003}, {}, 0, \"对敌方群体造成104%的物理伤害，并有60%概率对目标附加持续2回合的【空间撕裂】效果（该技能判定为1次伤害）\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"22581\", 0, 1, 1, {{29201}}, 0, 0, 1, 0}",
