	[216331.0] = "{216331, \"情绪鼓舞\", \"幽冥公主\", 21633, 216332, 1, 0, 4, \"active_skill\", 0, \"max_atk\", 2, 1, {2163101,2163001,2162003}, {}, 0, \"幽冥公主鼓舞团队成员！为攻击最高的2个己方单位驱散1个负面状态，并提升其15%攻击力，持续2回合\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"21640\", 0, 1, 1, {}, 0, 0, 1, 0}",
	[558403.0] = "{558403, \"月之狮子·觉醒\", \"圆月猫蝮蛇\", 55840, 558404, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5584003,5584023,5584033}, {}, 0, \"每回合开始对敌方随机一名单位，附加【毛皮族注视】。圆月猫蝮蛇战斗至濒死状态(血量＝＜30%)激活自身最大潜力，同时获得【月之狮子·觉醒】【月之狮子·暴走】。\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>15星</div>自动升级\", \"55840\", 0, 0, 1, {{63033,63040}}, 0, 0, 0, 0}",
