	[543403.0] = "{543403, \"告白动力\", \"茶豚\", 54340, 543404, 3, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5434003}, {}, 0, \"自身受到敌方攻击时，茶豚会向目标进行告白，此次告白有33%概率成功，告白成功时，目标会陷入【离间】2回合，同时友方会因此获得【情绪低落】效果2回合。告白失败时，目标伤害提升10%，同时友方因此获得【大受鼓舞】效果2回合。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"54340\", 0, 1, 1, {{28601,54341,54342,54345}}, 0, 0, 0, 0}",
	[523401.0] = "{523401, \"援护\", \"甚平\", 52340, 523402, 1, 0, 0, \"passive_skill\", 0, 0, 7, 1, {5234001}, {}, 0, \"每回合开始时，选择我方的优先后排生命值最低的1个英雄，若其生命值低于50%，则对其附加一个【绝对援护】效果，持续1回合\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"23314\", 0, 0, 1, {{12851}}, 0, 0, 0, 0}",
	[543402.0] = "{543402, \"告白动力\", \"茶豚\", 54340, 543403, 2, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5434002}, {}, 0, \"自身受到敌方攻击时，茶豚会向目标进行告白，此次告白有21%概率成功，告白成功时，目标会陷入【离间】2回合，同时友方会因此获得【情绪低落】效果2回合。告白失败时，目标伤害提升10%，同时友方因此获得【大受鼓舞】效果2回合。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"54340\", 0, 1, 1, {{28601,54341,54342,54345}}, 0, 0, 0, 0}",
	[256201.0] = "{256201, \"闪闪果实\", \"黄猿\", 25620, 256202, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {}, {{'hp_max_per',100},{'atk_per',150}}, 0, \"攻击提升15%，生命提升10%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"50892\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[542405.0] = "{542405, \"[觉醒]战斗音乐\", \"阿普\", 54240, 0, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5424101,5424102,5424103,5424001,5424002,5424003}, {}, 0, \"回合结束时阿普会弹奏战斗音乐，39%概率使友方全体身上携带的增益效果时间刷新至初始回合，33%概率使敌方全体身上携带的负面和控制效果时间刷新至初始回合。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"54240\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[152204.0] = "{152204, \"武装硬化\", \"战桃丸\", 15220, 152205, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {}, {{'atk_per',500},{'hp_max_per',250},{'speed',35}}, 0, \"攻击提升50%，生命提升25%，速度提升35点\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"15070\", 0, 1, 1, {}, 0, 0, 0, 0}",
