	[556302.0] = "{556302, \"魔神风脚·牛肉爆裂\", \"山治(外骨骼)\", 55630, 556303, 2, 0, 4, \"active_skill\", 0, 0, 1, 1, {5563002,5563012}, {}, 0, \"山治(外骨骼)释放魔神风脚·牛肉爆裂，对敌方全体造成255%物理伤害，有40%概率给目标附加【灼烧】效果，击杀目标后将再次释放此技能(每回合只可触发一次)\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>9星</div>自动升级\", \"55630\", 0, 1, 1, {{21010}}, 0, 0, 2, 0}",
	[541405.0] = "{541405, \"[觉醒]阿修罗·极\", \"索隆(和之国)\", 54140, 0, 5, 0, 1, \"passive_skill\", 0, 0, 5, 1, {5414305,5414205,5415005,5414105}, {}, 0, \"当索隆(和之国)自身生命值低于80%时，索隆将化身阿修罗形态，清除自身所有负面状态，且立即恢复自身血量至100%，消耗同等极限值，处于阿修罗状态下，有60%概率触发【霸王震慑】使敌人忘却被动2回合。处于【阿修罗形态】下时，索隆【无惧死神】。阿修罗形态持续2回合，处于阿修罗状态时，为我方英雄增加【闪避提升】。(该技能冷却4回合)\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"54140\", 0, 1, 1, {{541441,54151,54145}}, 0, 0, 0, 0}",
