	[516402.0] = "{516402, \"果实觉醒\", \"白胡子\", 51640, 516403, 2, 0, 0, \"passive_skill\", 0, 0, 2, 1, {5164012}, {}, 0, \"若敌方单位在携带【空间撕裂】时死亡，则己方全体单位回复白胡子100%攻击力的生命值；且白胡子每次攻击将有40%概率给目标附加【空间撕裂】，持续2回合\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"22584\", 0, 1, 1, {{29201}}, 0, 0, 0, 0}",
