	[516403.0] = "{516403, \"果实觉醒\", \"白胡子\", 51640, 516404, 3, 0, 0, \"passive_skill\", 0, 0, 2, 1, {5164013}, {}, 0, \"若敌方单位在携带【空间撕裂】时死亡，则己方全体单位回复白胡子120%攻击力的生命值；且白胡子每次攻击将有60%概率给目标附加【空间撕裂】，持续2回合\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"22584\", 0, 1, 1, {{29201}}, 0, 0, 0, 0}",
	[541401.0] = "{541401, \"阿修罗·极\", \"索隆(和之国)\", 54140, 541402, 1, 0, 1, \"passive_skill\", 0, 0, 5, 1, {5414301,5414201,5415001,5414101}, {}, 0, \"当索隆(和之国)自身生命值低于80%时，索隆将化身阿修罗形态，清除自身所有负面状态，且立即恢复自身血量至100%，消耗同等极限值，处于阿修罗状态下，有20%概率触发【霸王震慑】使敌人忘却被动2回合。处于【阿修罗形态】下时，索隆【无惧死神】。阿修罗形态持续2回合，处于阿修罗状态时，为我方英雄增加【闪避提升】。(该技能冷却4回合)\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"54140\", 0, 1, 1, {{541421,54151,54145}}, 0, 0, 0, 0}",
	[516404.0] = "{516404, \"果实觉醒\", \"白胡子\", 51640, 516405, 4, 0, 0, \"passive_skill\", 0, 0, 2, 1, {5164013}, {}, 0, \"若敌方单位在携带【空间撕裂】时死亡，则己方全体单位回复白胡子120%攻击力的生命值；且白胡子每次攻击将有60%概率给目标附加【空间撕裂】，持续2回合\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"22584\", 0, 1, 1, {{29201}}, 0, 0, 0, 0}",
	[245301.0] = "{245301, \"生命释放\", \"猫头鹰\", 24530, 0, 1, 0, 4, \"active_skill\", 0, 0, 2, 1, {2453001,2453101}, {}, 0, \"为生命最低的3个己方单位回复等同自身攻击力146%的生命，60%概率驱散目标所有负面状态\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"50393\", 0, 1, 1, {}, 0, 1, 2, 0}",
	[541403.0] = "{541403, \"阿修罗·极\", \"索隆(和之国)\", 54140, 541404, 3, 0, 1, \"passive_skill\", 0, 0, 5, 1, {5414303,5414203,5415003,5414103}, {}, 0, \"当索隆(和之国)自身生命值低于80%时，索隆将化身阿修罗形态，清除自身所有负面状态，且立即恢复自身血量至100%，消耗同等极限值，处于阿修罗状态下，有40%概率触发【霸王震慑】使敌人忘却被动2回合。处于【阿修罗形态】下时，索隆【无惧死神】。阿修罗形态持续2回合，处于阿修罗状态时，为我方英雄增加【闪避提升】。(该技能冷却4回合)\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"54140\", 0, 1, 1, {{541441,54151,54145}}, 0, 0, 0, 0}",
	[509403.0] = "{509403, \"城堡·沼泽\", \"贝基\", 50940, 0, 3, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5094011,5094003}, {}, 0, \"受到攻击时，自身叠加一个持续至战斗结束的【速度提升】效果，提升自身2%速度，最多可叠加5层，且有100%概率对攻击者进行伤害等同贝基攻击力130%的反击，反击无视闪避；若反击目标为战士职业，则必定暴击\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"20810\", 0, 1, 1, {{10731}}, 0, 0, 0, 0}",
	[223201.0] = "{223201, \"战鬼\", \"韦伯\", 22320, 223202, 1, 0, 0, \"passive_skill\", 0, 0, 1, 1, {}, {{'atk_per',100},{'hp_max_per',50}}, 0, \"攻击提升10%，生命提升5%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"22320\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[541402.0] = "{541402, \"阿修罗·极\", \"索隆(和之国)\", 54140, 541403, 2, 0, 1, \"passive_skill\", 0, 0, 5, 1, {5414302,5414202,5415002,5414102}, {}, 0, \"当索隆(和之国)自身生命值低于80%时，索隆将化身阿修罗形态，清除自身所有负面状态，且立即恢复自身血量至100%，消耗同等极限值，处于阿修罗状态下，有30%概率触发【霸王震慑】使敌人忘却被动2回合。处于【阿修罗形态】下时，索隆【无惧死神】。阿修罗形态持续2回合，处于阿修罗状态时，为我方英雄增加【闪避提升】。(该技能冷却4回合)\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"54140\", 0, 1, 1, {{541431,54151,54145}}, 0, 0, 0, 0}",
	[256205.0] = "{256205, \"[觉醒]闪闪果实\", \"黄猿\", 25620, 0, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {}, {{'hp_max_per',200},{'atk_per',350},{'speed',20}}, 0, \"攻击提升35%，生命提升20%，速度提升20\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"50892\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[509402.0] = "{509402, \"城堡·沼泽\", \"贝基\", 50940, 509403, 2, 0, 0, \"passive_skill\", 0, 0, 1, 1, {5094011,5094002}, {}, 0, \"受到攻击时，自身叠加一个持续至战斗结束的【速度提升】效果，提升自身2%速度，最多可叠加5层，且有100%概率对攻击者进行伤害等同贝基攻击力120%的反击，反击无视闪避\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"20810\", 0, 1, 1, {{10731}}, 0, 0, 0, 0}",
	[755901.0] = "{755901, \"普通攻击\", \"克力架\", 75590, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {7559001}, {}, 0, \"对前方1个目标造成100%的魔法伤害\", \"\", \"\", \"20000\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[209301.0] = "{209301, \"逆流\", \"薇薇\", 20930, 209302, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {2093001,2093401,2093101,2093401,2093201,2093401,2093301}, {}, 0, \"连续攻击前方单体3次，共造成360%物理伤害，若目标处于【流血】状态，则伤害提升15%；使用后停止行动1回合\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"20920\", 0, 1, 1, {{24201}}, 0, 0, 2, 0}",
	[515351.0] = "{515351, \"无上大快刀\", \"鹰眼\", 51535, 515352, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {5159901}, {}, 0, \"鹰眼释放所有怒气施展华丽而猛烈剑术，对前方单体造成3次各105%物理伤害的斩击（共315%伤害），每3层【怒气】则额外增加1次斩击（最多2次，共5连击），额外斩击的最后一击会对目标以外随机2个单位造成相同系数的溅射伤害，怒气在行动结束后消失\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"22933\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[540405.0] = "{540405, \"镜山\", \"大和\", 54040, 0, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5404006,5404105}, {}, 0, \"战斗开始时，大和为自己附加【镜山】，持续8回合，自身【镜山】延迟80%的伤害。同时为除自己外的随机2个友方单位附加【镜山】，持续2个回合，友方【镜山】延迟40%的伤害。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"54040\", 0, 1, 1, {{54049}}, 0, 0, 0, 0}",
	[223202.0] = "{223202, \"战鬼\", \"韦伯\", 22320, 223203, 2, 0, 0, \"passive_skill\", 0, 0, 1, 1, {}, {{'atk_per',200},{'hp_max_per',100}}, 0, \"攻击提升20%，生命提升10%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>8星</div>自动升级\", \"22320\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[540402.0] = "{540402, \"镜山\", \"大和\", 54040, 540403, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5404004}, {}, 0, \"战斗开始时，大和为自己附加【镜山】，持续4回合。【镜山】延迟60%的伤害\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"54040\", 0, 1, 1, {{54049}}, 0, 0, 0, 0}",
	[540403.0] = "{540403, \"镜山\", \"大和\", 54040, 540404, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5404005}, {}, 0, \"战斗开始时，大和为自己附加【镜山】，持续8回合。【镜山】延迟70%的伤害\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"54040\", 0, 1, 1, {{54049}}, 0, 0, 0, 0}",
	[520901.0] = "{520901, \"跑打动作\", \"路飞\", 52090, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {5209001}, {}, 0, \"对前方单体造成100%物理伤害\", \"\", \"\", \"20000\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[515353.0] = "{515353, \"无上大快刀\", \"鹰眼\", 51535, 515354, 3, 0, 4, \"active_skill\", 0, 0, 1, 1, {5153501,5159903}, {}, 0, \"鹰眼释放所有怒气施展华丽而猛烈剑术，临时提升自身30%命中率后，对前方单体造成3次各150%物理伤害的斩击（共450%伤害），每3层【怒气】则额外增加1次斩击（最多2次，共5连击），额外斩击的最后一击会对目标以外随机2个单位造成相同系数的溅射伤害，怒气在行动结束后消失\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"22933\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[216001.0] = "{216001, \"普通攻击\", \"幽冥公主\", 21600, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {2160001}, {}, 0, \"对前方单体造成100%伤害\", \"\", \"\", \"20000\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[540401.0] = "{540401, \"镜山\", \"大和\", 54040, 540402, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5404003}, {}, 0, \"战斗开始时，大和为自己附加【镜山】，持续2回合。【镜山】延迟50%的伤害\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"54040\", 0, 1, 1, {{54049}}, 0, 0, 0, 0}",
	[151202.0] = "{151202, \"烧烧果实\", \"艾斯\", 15120, 151203, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {}, {{'atk_per',300},{'hp_max_per',150},{'hit_magic',50}}, 0, \"艾斯因为烧烧果实获得了强大的力量，攻击提升30%，生命提升15%，控制提升5%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>8星</div>自动升级\", \"24330\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[223203.0] = "{223203, \"战鬼\", \"韦伯\", 22320, 0, 3, 0, 0, \"passive_skill\", 0, 0, 1, 1, {}, {{'atk_per',300},{'hp_max_per',150}}, 0, \"攻击提升30%，生命提升15%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"22320\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[515352.0] = "{515352, \"无上大快刀\", \"鹰眼\", 51535, 515353, 2, 0, 4, \"active_skill\", 0, 0, 1, 1, {5153501,5159902}, {}, 0, \"鹰眼释放所有怒气施展华丽而猛烈剑术，临时提升自身30%命中率后，对前方单体造成3次各125%物理伤害的斩击（共375%伤害），每3层【怒气】则额外增加1次斩击（最多2次，共5连击），额外斩击的最后一击会对目标以外随机2个单位造成相同系数的溅射伤害，怒气在行动结束后消失\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>9星</div>自动升级\", \"22933\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[539404.0] = "{539404, \"御田二刀流\", \"光月御田\", 53940, 539405, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5394001}, {}, 0, \"己方造成暴击时，45%概率使御田获得一层【阎魔】。己方受到伤害时，33%概率使御田获得一层【天羽羽斩】。在使用【桃源白泷】时，每层【天羽羽斩】提高30%的物理伤害和30%的吸血效果。御田在使用【桃源十拳】时会消耗所有【阎魔】层数和【天羽羽斩】层数，每层【阎魔】提高附带消耗生命值*0.3的物理伤害和无视15%的防御，每层【天羽羽斩】会为自身回复3%的最大生命值。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"53940\", 0, 1, 1, {{53951,53961}}, 0, 0, 0, 0}",
	[202101.0] = "{202101, \"正义轰击\", \"鱼人3号\", 20210, 0, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {2021001}, {}, 0, \"对敌方前两排单位造成110%魔法伤害，且有40%概率使目标暴击率降低15%，持续2回合\", \"初始激活\", \"\", \"15220\", 0, 1, 1, {}, 0, 0, 1, 0}",
	[782405.0] = "{782405, \"[觉醒]草帽航海士\", \"娜美(宙斯)\", 78240, 0, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7824005,7824015}, {}, 0, \"回合开始为自身提供免疫控制，持续1回合，为友方全体单位提供以下随机一种效果；1、增加50%暴击率，持续1回合，2、增加50%攻击力，持续1回合，3、增加50%免伤，持续1回合，4、增加50%速度，持续1回合\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"782401\", 0, 0, 1, {{27105,26105}}, 0, 0, 0, 0}",
	[515355.0] = "{515355, \"[觉醒]无上大快刀\", \"鹰眼\", 51535, 0, 5, 0, 4, \"active_skill\", 0, 0, 1, 1, {5153501,5159903}, {}, 0, \"鹰眼释放所有怒气施展华丽而猛烈剑术，临时提升自身30%命中率后，对前方单体造成3次各150%物理伤害的斩击（共450%伤害），每3层【怒气】则额外增加1次斩击（最多2次，共5连击），额外斩击的最后一击会对目标以外随机2个单位造成相同系数的溅射伤害，怒气在行动结束后消失\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"22933\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[279101.0] = "{279101, \"挥刀斩\", \"海贼13号\", 27910, 0, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {2791001,2791101}, {}, 0, \"对随机3个敌方单位造成128%魔法伤害，若产生暴击则对目标附加【出血】状态，持续2回合\", \"初始激活\", \"\", \"21920\", 0, 3, 1, {{21001}}, 0, 0, 1, 0}",
	[265201.0] = "{265201, \"树之荫\", \"强者海贼1号\", 26520, 0, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {}, {{'atk_per',100},{'hp_max_per',50}}, 0, \"攻击提升10%，生命提升5%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"26420\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[546104.0] = "{546104, \"魔鬼之手\", \"巴雷特\", 54610, 546105, 4, 0, 2, \"active_skill\", 0, 0, 1, 1, {5461004,5461104}, {}, 0, \"巴雷特跃至半空中，朝敌方单体施展出超强一击，造成240%的物理伤害，同时附带自身生命上限10%的无视防御伤害，有45%概率对目标附加【嘲讽】，持续2回合\", \"初始激活\", \"\", \"54610\", 0, 1, 1, {{24001}}, 0, 0, 1, 0}",
	[151201.0] = "{151201, \"烧烧果实\", \"艾斯\", 15120, 151202, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {}, {{'atk_per',200},{'hp_max_per',100}}, 0, \"艾斯因为烧烧果实获得了强大的力量，攻击提升20%，生命提升10%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"24330\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[539403.0] = "{539403, \"御田二刀流\", \"光月御田\", 53940, 539404, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5394001}, {}, 0, \"己方造成暴击时，45%概率使御田获得一层【阎魔】。己方受到伤害时，33%概率使御田获得一层【天羽羽斩】。在使用【桃源白泷】时，每层【天羽羽斩】提高30%的物理伤害和30%的吸血效果。御田在使用【桃源十拳】时会消耗所有【阎魔】层数和【天羽羽斩】层数，每层【阎魔】提高附带消耗生命值*0.3的物理伤害和无视15%的防御，每层【天羽羽斩】会为自身回复3%的最大生命值。\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"53940\", 0, 1, 1, {{53951,53961}}, 0, 0, 0, 0}",
	[506901.0] = "{506901, \"普通攻击\", \"索隆(伟大航路)\", 50690, 0, 1, 1, 0, \"active_skill\", 0, 0, 1, 1, {5069001}, {}, 0, \"对前方单体造成100%物理伤害\", \"\", \"\", \"20000\", 0, 1, 1, {}, 0, 0, 0, 0}",
	[521301.0] = "{521301, \"四档形态\", \"路飞(新世界)\", 52130, 521302, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5213001,5213011,5213041,5213021}, {}, 0, \"生命值低于50%时触发，驱散身上的异常状态且回复自身20%生命值，并提升自身15%攻击力、10%魔法免伤（均持续4回合，且不可被驱散）；对己方所有五皇团英雄单位附加持续4回合的5%【伤害提升】；四档形态状态下免疫所有控制技能，【橡皮灰熊枪】变为【大猿王枪】且无冷却时间；四档形态持续4回合，每场战斗只能触发1次\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"22983\", 0, 1, 1, {{21401,16599}}, 0, 0, 0, 0}",
	[208305.0] = "{208305, \"[觉醒]可乐大炮\", \"弗兰奇\", 20830, 0, 5, 0, 4, \"active_skill\", 0, 0, 1, 1, {2083005,2083105}, {}, 0, \"满怀愤怒的一击，对前方单体造成546%物理伤害，若目标处于【出血】或【大出血】状态，则暴击率提升70%，暴击伤害提升40%\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"31493\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[242303.0] = "{242303, \"双手剪\", \"闪电\", 24230, 0, 3, 0, 4, \"active_skill\", 0, 0, 1, 1, {2423001,2423103,2423203}, {}, 0, \"隐匿身形后发动双手剪，优先对中后排随机一个单位造成374%物理伤害，本次攻击暴击率提升20%，若击杀目标，则目标无法以任何常规方式复活（该效果对【圣灵】技能无效）\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"24240\", 0, 1, 1, {}, 0, 0, 2, 0}",
	[546101.0] = "{546101, \"魔鬼之手\", \"巴雷特\", 54610, 546102, 1, 0, 2, \"active_skill\", 0, 0, 1, 1, {5461001,5461101}, {}, 0, \"巴雷特跃至半空中，朝敌方单体施展出超强一击，造成129%的物理伤害，同时附带自身生命上限4%的无视防御伤害，有20%概率对目标附加【嘲讽】，持续2回合\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"54610\", 0, 1, 1, {{24001}}, 0, 0, 1, 0}",
	[783401.0] = "{783401, \"黑足\", \"山治(鬼岛)\", 78340, 783402, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7834001}, {}, 0, \"战斗开始时，100%概率获得获得1层【黑足】；受到伤害时时，自身获得1层【黑足】，持续4回合。\", \"激活条件：忍者到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：忍者到达<div fontcolor=45a536>6星</div>自动升级\", \"783401\", 0, 0, 1, {{78321,78326}}, 0, 0, 0, 0}",
