	[546102.0] = "{546102, \"魔鬼之手\", \"巴雷特\", 54610, 546103, 2, 0, 2, \"active_skill\", 0, 0, 1, 1, {5461002,5461102}, {}, 0, \"巴雷特跃至半空中，朝敌方单体施展出超强一击，造成202%的物理伤害，同时附带自身生命上限7%的无视防御伤害，有30%概率对目标附加【嘲讽】，持续2回合\", \"初始激活\", \"升级条件：英雄到达<div fontcolor=45a536>7星</div>自动升级\", \"54610\", 0, 1, 1, {{24001}}, 0, 0, 1, 0}",
	[545105.0] = "{545105, \"[觉醒]冲击波动\", \"罗(和之国)\", 54510, 0, 5, 0, 4, \"active_skill\", 0, 0, 1, 1, {5451005,5451105,5421103,5421113,5421123,5421203,5421303,5421403,5421503,5421603,5421703,5421803,5421903}, {}, 0, \"手术果实觉醒后的招式，锁定敌方当前身上负面效果(包含控制)最多的敌方单体，对之贯穿KROOM，造成550%的法术伤害，同时手术刀会对敌方产生任意一种常规负面状态(减速、出血、致盲、迟缓、石化、沉默、封印、禁疗、睡眠、缓伤、破甲、混乱)，此技能无视50%防御，且目标身上每有1个负面效果，额外造成其最大生命值3%的伤害，最高不超过罗攻击力5倍的伤害。\", \"初始激活\", \"\", \"54510\", 0, 1, 1, {}, 0, 0, 1, 0}",
	[783404.0] = "{783404, \"黑足\", \"山治(鬼岛)\", 78340, 783405, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7834004}, {}, 0, \"战斗开始时，100%概率获得获得1层【黑足】；受到伤害时时，自身获得1层【黑足】，持续4回合。\", \"激活条件：忍者到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：10星忍者<div fontcolor=45a536>技能突破</div>升级\", \"783401\", 0, 0, 1, {{78321,78326}}, 0, 0, 0, 0}",
