	[151203.0] = "{151203, \"烧烧果实\", \"艾斯\", 15120, 151204, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {}, {{'atk_per',400},{'hp_max_per',200},{'hit_magic',100}}, 0, \"艾斯因为烧烧果实获得了强大的力量，攻击提升40%，生命提升20%，控制提升10%\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"24330\", 0, 1, 1, {}, 0, 0, 0, 0}",
