	[780401.0] = "{780401, \"传奇海贼\", \"白胡子(巅峰)\", 78040, 780402, 1, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7804001,7804011,7804021}, {}, 0, \"生命值低于40%时触发，清除自身所有负面状态，并获得2回合【果实觉醒】状态；该状态下免疫一切伤害，每次攻击时有30%概率对目标附加【震荡】，每次受击时有20%概率对攻击方附加【震荡】\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>6星</div>自动升级\", \"780401\", 0, 1, 1, {{62406,25606,25501,25601,25701}}, 0, 0, 0, 0}",
	[547304.0] = "{547304, \"大王猿枪\", \"路飞(四挡)\", 54730, 547305, 4, 0, 4, \"active_skill\", 0, 0, 1, 1, {5473004}, {}, 0, \"橡胶猿王枪的加强版，继续向肌肉里加气强化自身手臂释放出来的招式。对敌方全体造成225%物理伤害并有80%概率附加一层橡胶炸弹\", \"激活条件：英雄到达<div fontcolor=45a536>3阶</div>自动激活\", \"\", \"70330\", 0, 1, 1, {{57004}}, 0, 0, 2, 0}",
	[780402.0] = "{780402, \"传奇海贼\", \"白胡子(巅峰)\", 78040, 780403, 2, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7804002,7804012,7804022}, {}, 0, \"生命值低于50%时触发，清除自身所有负面状态，并获得2回合【果实觉醒】状态；该状态下免疫一切伤害，每次攻击时有40%概率对目标附加【震荡】，每次受击时有30%概率对攻击方附加【震荡】\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"升级条件：英雄到达<div fontcolor=45a536>10星</div>自动升级\", \"780401\", 0, 1, 1, {{62406,25606,25502,25602,25702}}, 0, 0, 0, 0}",
	[526205.0] = "{526205, \"[觉醒]革命军\", \"萨博（路西）\", 52620, 0, 5, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5262003,5262013}, {{'atk_per',400},{'hp_max_per',200},{'crit_rate',150}}, 0, \"攻击提升40%，生命值提升20%，暴击率提升15%；若受到的单次伤害大于自身生命值的30%，则受到的最终伤害减少20%，同时对攻击方附加【致命打击】，持续4回合\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"23602\", 0, 0, 1, {{29401}}, 0, 0, 0, 0}",
	[276101.0] = "{276101, \"重击\", \"女儿国战士\", 27610, 0, 1, 0, 4, \"active_skill\", 0, 0, 1, 1, {2761001}, {}, 0, \"女儿国战士对敌人发起打击，对前方单体敌人造成230%物理伤害，30%概率附加【出血】状态，持续2回合\", \"初始激活\", \"\", \"30591\", 0, 1, 1, {{21001}}, 0, 0, 1, 0}",
	[780403.0] = "{780403, \"传奇海贼\", \"白胡子(巅峰)\", 78040, 780404, 3, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7804003,7804013,7804023}, {}, 0, \"生命值低于60%时触发，清除自身所有负面状态，并获得2回合【果实觉醒】状态；该状态下免疫一切伤害，每次攻击时有50%概率对目标附加【震荡】，每次受击时有40%概率对攻击方附加【震荡】\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"780401\", 0, 1, 1, {{62406,25606,25503,25603,25703}}, 0, 0, 0, 0}",
	[526204.0] = "{526204, \"革命军\", \"萨博（路西）\", 52620, 526205, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {5262003,5262013}, {{'atk_per',400},{'hp_max_per',200},{'crit_rate',150}}, 0, \"攻击提升40%，生命值提升20%，暴击率提升15%；若受到的单次伤害大于自身生命值的30%，则受到的最终伤害减少20%，同时对攻击方附加【致命打击】，持续4回合\", \"激活条件：英雄到达<div fontcolor=45a536>1阶</div>自动激活\", \"\", \"23602\", 0, 0, 1, {{29401}}, 0, 0, 0, 0}",
	[780404.0] = "{780404, \"传奇海贼\", \"白胡子(巅峰)\", 78040, 780405, 4, 0, 0, \"passive_skill\", 0, 0, 5, 1, {7804004,7804014,7804024}, {}, 0, \"生命值低于70%时触发，清除自身所有负面状态，并获得2回合【果实觉醒】状态；该状态下免疫一切伤害，每次攻击时有60%概率对目标附加【震荡】，每次受击时有50%概率对攻击方附加【震荡】\", \"激活条件：英雄到达<div fontcolor=45a536>5阶</div>自动激活\", \"\", \"780401\", 0, 1, 1, {{62406,25606,25504,25604,25704}}, 0, 0, 0, 0}",
